/* Ngữ pháp JLPT N5–N1 — 374 mẫu thật (N5 84 · N4 74 · N3/N2/N1 mỗi cấp 72),
   biên soạn theo Minna no Nihongo + Kanzen/Sou Matome, cùng dữ liệu bản web chính SoraKanji.
   Mỗi mẫu: p = mẫu · s = cấu trúc · m = giải nghĩa · ex = [[câu Nhật, dịch Việt], …] · n = lưu ý.
   N4 có thêm lesson (Bài 26–50 Minna Sơ cấp 2); N3/N2/N1 có thêm group (6 nhóm chủ đề × 12 mẫu). */
window.GRAMMAR_DATA = {"N5": [{"p": "N は N です", "s": "[N1] は [N2] です。", "m": "“N1 là N2” — câu giới thiệu, khẳng định cơ bản nhất. は là trợ từ đánh dấu chủ đề của câu.", "ex": [["わたしは学生です。", "Tôi là học sinh."], ["田中さんは先生です。", "Anh Tanaka là giáo viên."], ["わたしはベトナム人です、友達は日本人です。", "Tôi là người Việt Nam, bạn tôi là người Nhật."], ["兄は会社員ですが、姉は学生です。", "Anh trai tôi là nhân viên công ty, chị gái tôi là học sinh."], ["これはわたしの辞書ですが、とても大切です。", "Đây là từ điển của tôi, nó rất quan trọng."]], "n": "は viết là は nhưng đọc là “wa”."}, {"p": "N は N じゃありません", "s": "[N1] は [N2] じゃありません。", "m": "Phủ định của です: “N1 không phải là N2”.", "ex": [["わたしは先生じゃありません。", "Tôi không phải là giáo viên."], ["あの人は日本人じゃありません。", "Người kia không phải là người Nhật."], ["わたしは先生じゃありません、学生です。", "Tôi không phải là giáo viên, tôi là học sinh."], ["あの人は日本人じゃありません、ベトナム人です。", "Người kia không phải là người Nhật, là người Việt Nam."], ["これは辞書じゃありません、教科書です。", "Đây không phải là từ điển, là sách giáo khoa."]], "n": "Văn viết trang trọng dùng ではありません thay cho じゃありません."}, {"p": "N も", "s": "[N] も [N] です。", "m": "も nghĩa là “cũng” — dùng khi một thứ có cùng tính chất với thứ đã nói trước.", "ex": [["わたしも学生です。", "Tôi cũng là học sinh."], ["あの人もベトナム人です。", "Người kia cũng là người Việt Nam."], ["わたしも学生です、弟も学生です。", "Tôi cũng là học sinh, em trai tôi cũng là học sinh."], ["あの人もベトナム人ですが、わたしもベトナム人です。", "Người kia cũng là người Việt Nam, tôi cũng là người Việt Nam."], ["弟も先生です、妹も先生です。", "Em trai tôi cũng là giáo viên, em gái tôi cũng là giáo viên."]], "n": "も thay hẳn vị trí của は (không viết はも)."}, {"p": "N の N", "s": "[N1] の [N2]", "m": "“N2 của N1” — の nối hai danh từ, chỉ sở hữu hoặc bổ nghĩa; danh từ chính nằm ở sau.", "ex": [["これはわたしの本です。", "Đây là sách của tôi."], ["あれは日本語の本です。", "Kia là sách tiếng Nhật."], ["これはわたしの友達のかばんです。", "Đây là cặp sách của bạn tôi."], ["あれは日本の車です、とても速いです。", "Kia là xe của Nhật, rất nhanh."], ["この本は日本語の本ですが、少し難しいです。", "Cuốn sách này là sách tiếng Nhật, hơi khó."]], "n": "の còn dùng trong cụm như 会社の人 (người của công ty)."}, {"p": "これ・それ・あれ", "s": "これ／それ／あれ は [N] です。", "m": "Đại từ chỉ vật: これ gần người nói, それ gần người nghe, あれ xa cả hai người.", "ex": [["これは辞書です。", "Đây là từ điển."], ["あれは学校です。", "Kia là trường học."], ["これはわたしの本です、とても面白いです。", "Đây là sách của tôi, rất thú vị."], ["それは兄の車です、新しいです。", "Đó là xe của anh trai tôi, còn mới."], ["あれは学校ですが、大きいです。", "Kia là trường học, rất lớn."]], "n": "Không dùng これ／それ／あれ để chỉ người vì thiếu lịch sự; chỉ người dùng あの人."}, {"p": "この・その・あの", "s": "この／その／あの + [N]", "m": "Tính từ chỉ định đứng ngay trước danh từ: cái này / cái đó / cái kia.", "ex": [["この本は高いです。", "Cuốn sách này đắt."], ["その車は新しいです。", "Chiếc xe đó mới."], ["この本は面白いです、毎日読みます。", "Cuốn sách này thú vị, tôi đọc mỗi ngày."], ["その車は新しいです、とても速いです。", "Chiếc xe đó mới, rất nhanh."], ["あの人は先生です、日本語を教えます。", "Người kia là giáo viên, dạy tiếng Nhật."]], "n": "この bắt buộc phải có danh từ đi sau; これ thì đứng một mình."}, {"p": "ここ・そこ・あそこ", "s": "ここ／そこ／あそこ は [nơi chốn] です。", "m": "Đại từ chỉ địa điểm: ở đây (gần tôi), ở đó (gần bạn), ở kia (xa cả hai).", "ex": [["ここは教室です。", "Đây là phòng học."], ["トイレはあそこです。", "Nhà vệ sinh ở đằng kia."], ["ここは学校です、大きいです。", "Đây là trường học, rất lớn."], ["そこは図書館です、静かです。", "Đó là thư viện, yên tĩnh."], ["あそこは病院です、新しいです。", "Kia là bệnh viện, còn mới."]], "n": "Cách nói lịch sự hơn: こちら・そちら・あちら."}, {"p": "N は どこですか", "s": "[N] は どこですか。", "m": "Hỏi nơi chốn: “N ở đâu?”", "ex": [["駅はどこですか。", "Ga tàu ở đâu?"], ["銀行はどこですか。", "Ngân hàng ở đâu?"], ["駅はどこですか、教えてください。", "Ga tàu ở đâu, xin hãy chỉ cho tôi."], ["郵便局はどこですか、近いですか。", "Bưu điện ở đâu, có gần không?"], ["トイレはどこですか、あそこですか。", "Nhà vệ sinh ở đâu, ở đằng kia phải không?"]], "n": "Trả lời: [N] は ここ／そこ／あそこです, hoặc dùng mẫu あります／います ở Bài 22."}, {"p": "Từ để hỏi: 何・だれ・いつ・いくつ・いくら", "s": "[Từ để hỏi] + ですか。", "m": "Từ để hỏi đặt đúng vào vị trí của thông tin cần hỏi trong câu: 何 (cái gì), だれ (ai), いつ (khi nào), いくつ (mấy cái / mấy tuổi), いくら (bao nhiêu tiền).", "ex": [["これは何ですか。", "Đây là cái gì?"], ["会議はいつですか。", "Cuộc họp là khi nào?"], ["これは何ですか、辞書ですか。", "Đây là cái gì, là từ điển phải không?"], ["あの人は誰ですか、先生ですか。", "Người kia là ai, là giáo viên phải không?"], ["本は何冊ですか、3冊ですか。", "Có mấy cuốn sách, 3 cuốn phải không?"]], "n": "何 đọc là なん trước です và trước lượng từ (何時 なんじ), đọc là なに trong các trường hợp như 何を・何の."}, {"p": "V ます／ません", "s": "V + ます (khẳng định) / V + ません (phủ định)", "m": "Thể lịch sự ở hiện tại – tương lai: “làm / không làm”.", "ex": [["わたしは毎日日本語を勉強します。", "Tôi học tiếng Nhật mỗi ngày."], ["あしたは行きません。", "Ngày mai tôi không đi."], ["あしたは行きませんが、家で本を読みますね。", "Ngày mai tôi không đi, ở nhà đọc sách nhé."], ["毎朝パンを食べます、夜はご飯を食べます。", "Mỗi sáng tôi ăn bánh mì, buổi tối ăn cơm."], ["毎晩テレビを見ますが、ニュースは見ませんね。", "Mỗi tối tôi xem ti vi, nhưng không xem tin tức."]], "n": "Chia động từ: nhóm Ⅰ đổi âm cuối sang hàng い + ます (書きます); nhóm Ⅱ bỏ る + ます (食べます); nhóm Ⅲ: します・来ます."}, {"p": "V ました／ませんでした", "s": "V + ました (đã làm) / V + ませんでした (đã không làm)", "m": "Thể lịch sự ở quá khứ.", "ex": [["昨日映画を見ました。", "Hôm qua tôi đã xem phim."], ["先週は来ませんでした。", "Tuần trước tôi đã không đến."], ["昨日映画を見ましたが、とても面白かったです。", "Hôm qua tôi đã xem phim, rất thú vị."], ["先週は来ませんでしたが、今週は来ましたよ。", "Tuần trước tôi đã không đến, tuần này tôi đã đến đấy."], ["昨日は早く起きました、今日は起きませんでしたよ。", "Hôm qua tôi đã dậy sớm, hôm nay tôi đã không dậy."]], "n": "ました là quá khứ của ます; ませんでした là quá khứ của ません."}, {"p": "N を V", "s": "[N] を [V] ます", "m": "を đánh dấu tân ngữ trực tiếp — đối tượng chịu tác động của hành động.", "ex": [["パンを食べます。", "Tôi ăn bánh mì."], ["本を読みます。", "Tôi đọc sách."], ["パンを食べます、牛乳を飲みます。", "Tôi ăn bánh mì, uống sữa."], ["毎日本を読みます、新聞も読みます。", "Mỗi ngày tôi đọc sách, cũng đọc báo."], ["映画を見ますが、音楽も聞きます。", "Tôi xem phim, cũng nghe nhạc."]], "n": "を đọc là “o”."}, {"p": "N へ／に 行きます", "s": "[Nơi chốn] へ／に + 行きます・来ます・帰ります", "m": "Chỉ hướng / đích đến của động từ di chuyển.", "ex": [["学校へ行きます。", "Tôi đi đến trường."], ["国へ帰ります。", "Tôi về nước."], ["学校へ行きます、友達に会います。", "Tôi đi đến trường, gặp bạn."], ["国に帰ります、家族に会います。", "Tôi về nước, gặp gia đình."], ["日本へ来ます、東京に行きます。", "Tôi đến Nhật, đi Tokyo."]], "n": "へ đọc là “e”. に cũng chỉ đích đến; へ nhấn mạnh hướng đi hơn."}, {"p": "N で 行きます", "s": "[Phương tiện] で + 行きます・来ます", "m": "で chỉ phương tiện, cách thức di chuyển: “bằng …”.", "ex": [["電車で行きます。", "Tôi đi bằng tàu điện."], ["バスで来ました。", "Tôi đã đến bằng xe buýt."], ["電車で行きます、速いです。", "Tôi đi bằng tàu điện, nhanh lắm."], ["バスで来ます、友達もバスで来ます。", "Tôi đến bằng xe buýt, bạn tôi cũng đến bằng xe buýt."], ["車で行きます、駅まで行きます。", "Tôi đi bằng ô tô, đi đến ga."]], "n": "Đi bộ không dùng で: nói 歩いて行きます."}, {"p": "N と V", "s": "[Người] と [V] ます", "m": "と nghĩa là “cùng với (ai đó)”.", "ex": [["友達と話します。", "Tôi nói chuyện với bạn."], ["家族と旅行します。", "Tôi đi du lịch cùng gia đình."], ["友達と話します、楽しいです。", "Tôi nói chuyện với bạn, vui lắm."], ["家族と旅行します、京都に行きます。", "Tôi đi du lịch cùng gia đình, đi Kyoto."], ["先生と日本語を話します、毎日練習します。", "Tôi nói tiếng Nhật với thầy, luyện tập mỗi ngày."]], "n": "“Một mình” nói là 一人で（ひとりで）."}, {"p": "N から N まで", "s": "[N1] から [N2] まで", "m": "“Từ N1 đến N2” — dùng cho cả thời gian lẫn nơi chốn.", "ex": [["9時から5時まで働きます。", "Tôi làm việc từ 9 giờ đến 5 giờ."], ["家から駅まで歩きます。", "Tôi đi bộ từ nhà đến ga."], ["9時から5時まで働きます、忙しいです。", "Tôi làm việc từ 9 giờ đến 5 giờ, bận lắm."], ["家から駅まで歩きます、30分かかります。", "Tôi đi bộ từ nhà đến ga, mất 30 phút."], ["月曜日から金曜日まで学校に行きます、土曜日は休みです。", "Tôi đi học từ thứ Hai đến thứ Sáu, thứ Bảy nghỉ."]], "n": "から và まで có thể dùng tách riêng từng trợ từ."}, {"p": "Tính từ い／な", "s": "Aい + です ／ Aな + です", "m": "Tính từ い kết thúc bằng い (高い, 面白い); tính từ な cần な khi đứng trước danh từ (静かな町) nhưng bỏ な trước です.", "ex": [["この本は面白いです。", "Cuốn sách này thú vị."], ["この町は静かです。", "Thị trấn này yên tĩnh."], ["静かな町はとてもきれいです、住みやすいです。", "Thị trấn yên tĩnh rất đẹp, dễ sống."], ["きれいな花ですね、とても好きです。", "Hoa đẹp nhỉ, tôi rất thích."], ["有名な先生です、とても優しいです。", "Là thầy giáo nổi tiếng, rất hiền."]], "n": "Phủ định: tính từ い → bỏ い + くないです (面白くないです); tính từ な → じゃありません (静かじゃありません)."}, {"p": "V たいです", "s": "V (bỏ ます) + たいです", "m": "“Muốn làm V” — chỉ nguyện vọng của chính người nói.", "ex": [["日本へ行きたいです。", "Tôi muốn đi Nhật."], ["寿司を食べたいです。", "Tôi muốn ăn sushi."], ["日本へ行きたいですが、まだ行きません。", "Tôi muốn đi Nhật, nhưng vẫn chưa đi."], ["寿司を食べたいですか、ラーメンを食べたいですか。", "Bạn muốn ăn sushi hay muốn ăn ramen?"], ["水を飲みたいですね、とても暑いです。", "Tôi muốn uống nước quá, trời rất nóng."]], "n": "Tân ngữ trước たい có thể dùng が thay を: 水が飲みたいです (Tôi muốn uống nước)."}, {"p": "V てください", "s": "V (thể て) + ください", "m": "“Hãy / Xin hãy …” — câu yêu cầu, nhờ vả lịch sự.", "ex": [["ここに名前を書いてください。", "Xin hãy viết tên vào đây."], ["もう一度言ってください。", "Xin hãy nói lại một lần nữa."], ["ちょっと待ってください、今行きます。", "Xin hãy đợi một chút, tôi đến ngay đây."], ["この本を読んでくださいね、面白いですよ。", "Xin hãy đọc cuốn sách này nhé, thú vị lắm."], ["ここに名前を書いてください、ペンを使ってください。", "Xin hãy viết tên vào đây, xin hãy dùng cây bút này."]], "n": "Thể て: nhóm Ⅰ い・ち・り→って, み・び・に→んで, き→いて, ぎ→いで, し→して; nhóm Ⅱ bỏ る + て; nhóm Ⅲ: して・来て（きて)."}, {"p": "V てもいいです", "s": "V (thể て) + もいいです", "m": "“Được phép làm V” — cho phép hoặc xin phép.", "ex": [["写真を撮ってもいいです。", "Được chụp ảnh."], ["ここに座ってもいいですか。", "Tôi ngồi ở đây có được không?"], ["写真を撮ってもいいですか。", "Tôi chụp ảnh có được không?"], ["これでもいいですか。", "Cái này cũng được chứ?"], ["それでもいいですか、ほかの色でもいいですか。", "Như vậy cũng được chứ, màu khác cũng được chứ?"]], "n": "Hỏi xin phép dùng dạng câu hỏi ～てもいいですか."}, {"p": "V てはいけません", "s": "V (thể て) + はいけません", "m": "“Không được làm V” — cấm đoán, quy định.", "ex": [["ここで写真を撮ってはいけません。", "Không được chụp ảnh ở đây."], ["タバコを吸ってはいけません。", "Không được hút thuốc."], ["ここで写真を撮ってはいけませんよ。", "Không được chụp ảnh ở đây đâu."], ["ここでタバコを吸ってはいけませんから、気をつけてください。", "Không được hút thuốc ở đây, xin hãy chú ý."], ["教室で食べてはいけません、静かにしてください。", "Không được ăn trong lớp học, xin hãy giữ yên lặng."]], "n": "は trong ては đọc là “wa”."}, {"p": "N が あります／います", "s": "[Nơi] に [N] が あります／います", "m": "Nói về sự tồn tại: あります dùng cho đồ vật, cây cối; います dùng cho người và động vật.", "ex": [["部屋に机があります。", "Trong phòng có cái bàn."], ["公園に子供がいます。", "Ở công viên có trẻ con."], ["部屋に机がありますね、公園に子供がいますよ。", "Trong phòng có cái bàn đấy, ở công viên có trẻ con đấy."], ["部屋に机があります、椅子が新しいです。", "Trong phòng có cái bàn, ghế còn mới."], ["公園に子供がいます、犬もいます。", "Ở công viên có trẻ con, cũng có chó."], ["庭に犬がいます、家の中に猫がいます。", "Trong vườn có chó, trong nhà có mèo."]], "n": "Trợ từ đi kèm địa điểm là に; を không dùng trong mẫu này."}, {"p": "So sánh: より／のほうが", "s": "[A] は [B] より [Tính từ] です ／ [A] のほうが [B] より [Tính từ] です", "m": "So sánh hơn: “A … hơn B”.", "ex": [["電車はバスより速いです。", "Tàu điện nhanh hơn xe buýt."], ["肉のほうが魚より好きです。", "Tôi thích thịt hơn cá."], ["電車はバスより速いですが、高いです。", "Tàu điện nhanh hơn xe buýt, nhưng đắt."], ["電車のほうがバスより速いですが、車はもっと速いです。", "Tàu điện nhanh hơn xe buýt, nhưng ô tô còn nhanh hơn."], ["肉のほうが魚より好きですが、野菜はもっと好きです。", "Tôi thích thịt hơn cá, nhưng thích rau hơn nữa."], ["この本はあの本より面白いですが、高いです。", "Cuốn sách này thú vị hơn cuốn sách kia, nhưng đắt."]], "n": "So sánh nhất trong một nhóm: [Nhóm] で [A] が一番 [Tính từ] です."}, {"p": "V ながら", "s": "V1 (bỏ ます) + ながら、V2", "m": "“Vừa làm V1 vừa làm V2” — hai hành động xảy ra đồng thời, V2 là hành động chính.", "ex": [["音楽を聞きながら勉強します。", "Tôi vừa nghe nhạc vừa học."], ["歩きながら話します。", "Vừa đi bộ vừa nói chuyện."], ["音楽を聞きながら勉強します、楽しいです。", "Tôi vừa nghe nhạc vừa học, vui lắm."], ["歩きながら話します、友達と会います。", "Vừa đi bộ vừa nói chuyện, gặp bạn."], ["テレビを見ながらご飯を食べます、忙しいです。", "Tôi vừa xem ti vi vừa ăn cơm, bận lắm."]], "n": "Chủ ngữ của hai hành động phải là cùng một người."}, {"p": "V てから", "s": "V1 (thể て) + から、V2", "m": "“Sau khi làm xong V1 thì làm V2” — nhấn mạnh trình tự các hành động.", "ex": [["手を洗ってから、ご飯を食べます。", "Rửa tay xong rồi mới ăn cơm."], ["宿題をしてから、遊びます。", "Làm bài tập xong rồi mới chơi."], ["顔を洗ってから、ご飯を食べます。", "Rửa mặt xong rồi mới ăn cơm."], ["宿題をしてから、遊びに行きます。", "Làm bài tập xong rồi mới đi chơi."], ["歯を磨いてから、寝ます。", "Đánh răng xong rồi mới đi ngủ."]], "n": "Một ngày thường có nhiều hành động nối nhau bằng てから."}, {"p": "N で Vます", "s": "[N công cụ / ngôn ngữ] で + Vます。", "m": "で đứng sau danh từ chỉ công cụ, phương tiện làm việc hoặc ngôn ngữ được dùng để thực hiện hành động: “bằng …”. Đây là cách dùng で cho mọi hành động thường ngày, khác với で chỉ phương tiện di chuyển.", "ex": [["ペンで手紙を書きます。", "Tôi viết thư bằng bút."], ["パソコンでメールを送ります。", "Tôi gửi thư điện tử bằng máy tính."], ["日本語で話してください。", "Hãy nói bằng tiếng Nhật."], ["母は電話で友達と話します。", "Mẹ tôi nói chuyện với bạn qua điện thoại."], ["この仕事はコンピューターでします。", "Công việc này tôi làm bằng máy tính."]], "n": "Đừng nhầm で (công cụ/ngôn ngữ) với を (đối tượng của hành động): 手紙をペンで書きます — “viết thư bằng bút”."}, {"p": "「Từ」 は ～語で 何ですか", "s": "「[từ]」は [tên nước]語で 何ですか。", "m": "Dùng để hỏi một từ của tiếng này được nói thế nào trong một tiếng khác: “‘…’ trong tiếng … là gì?”. Tên ngôn ngữ thường tạo bằng tên nước + 語.", "ex": [["「ありがとう」はベトナム語で何ですか。", "“Arigatō” trong tiếng Việt là gì?"], ["「先生」は英語で何ですか。", "“Sensei” trong tiếng Anh là gì?"], ["「おはよう」は中国語で何ですか。", "“Ohayō” trong tiếng Trung là gì?"], ["「本」は韓国語で何ですか。", "“Hon” (sách) trong tiếng Hàn là gì?"], ["「さようなら」はフランス語で何ですか。", "“Sayōnara” trong tiếng Pháp là gì?"]], "n": "Khi trả lời, chỉ cần thay 何 bằng từ cần nói: 「ありがとう」はベトナム語で “cảm ơn” です."}, {"p": "N に N を あげます", "s": "[Người nhận] に + [vật] を + あげます。", "m": "あげます nghĩa là “cho, tặng”. Người cho là chủ ngữ của câu, người nhận được đánh dấu bằng に, còn vật được cho/tặng đánh dấu bằng を.", "ex": [["わたしは妹に本をあげました。", "Tôi đã tặng sách cho em gái."], ["兄は友達に時計をあげます。", "Anh trai tôi tặng đồng hồ cho bạn."], ["田中さんは子どもにお菓子をあげました。", "Anh Tanaka đã cho em bé bánh kẹo."], ["わたしは先生に花をあげます。", "Tôi tặng hoa cho thầy/cô giáo."], ["姉は弟にプレゼントをあげました。", "Chị gái tôi đã tặng quà cho em trai."]], "n": "あげます dùng khi cho người khác; khi người khác cho mình thì không dùng あげます mà dùng もらいます ở mẫu sau."}, {"p": "N に／から N を もらいます", "s": "[Người cho] に／から + [vật] を + もらいます。", "m": "もらいます nghĩa là “nhận, được cho”. Chủ ngữ là người nhận, người cho được đánh dấu bằng に hoặc から, vật nhận được đánh dấu bằng を.", "ex": [["わたしは父から誕生日のプレゼントをもらいました。", "Tôi đã nhận quà sinh nhật từ bố."], ["妹は先生に辞書をもらいました。", "Em gái tôi được thầy/cô giáo cho từ điển."], ["わたしは友達から写真をもらいました。", "Tôi đã nhận ảnh từ bạn."], ["子どもは母にお金をもらいます。", "Em bé nhận tiền từ mẹ."], ["兄は会社から賞をもらいました。", "Anh trai tôi đã nhận giải thưởng từ công ty."]], "n": "から dùng được với cả người lẫn tổ chức (会社から); に thường dùng với người cho cụ thể."}, {"p": "もう Vました／まだです", "s": "もう + Vました。／ いいえ、まだです。", "m": "もう đi cùng thể quá khứ nghĩa là “đã … rồi”, chỉ việc đã hoàn thành. Khi được hỏi もう Vましたか mà việc vẫn chưa xong, trả lời まだです nghĩa là “chưa”.", "ex": [["もう宿題をしました。", "Tôi đã làm bài tập rồi."], ["もう昼ごはんを食べましたか。", "Bạn đã ăn trưa chưa?"], ["いいえ、まだです。これから食べます。", "Chưa, bây giờ tôi mới ăn."], ["もうこの映画を見ました。", "Tôi đã xem bộ phim này rồi."], ["もう手紙を送りましたか。", "Bạn đã gửi thư chưa?"]], "n": "まだです chỉ để trả lời “chưa (làm xong)”; không nói まだしました. Câu đầy đủ “vẫn chưa làm” sẽ học ở các bài sau."}, {"p": "Lược trợ từ", "s": "Hội thoại thân mật: [N] + V — bỏ は・を・へ khi nghĩa đã rõ.", "m": "Khi nói chuyện thân mật với người thân hoặc bạn bè, các trợ từ như は, を đôi khi được lược bỏ mà nghĩa của câu vẫn rõ nhờ ngữ cảnh. Đây là lối nói suồng sã, chỉ gặp trong hội thoại thường ngày.", "ex": [["ごはん食べた？", "Ăn cơm chưa? (lược を)"], ["明日、学校行く？", "Mai có đi học không? (lược へ)"], ["この本、読んだ？", "Cuốn sách này đọc chưa? (lược を)"], ["水飲みたい。", "Muốn uống nước. (lược を)"], ["映画見に行こう。", "Đi xem phim đi. (lược を)"]], "n": "Chỉ lược trợ từ khi nói thân mật; trong văn viết, bài thi và lối nói lịch sự phải giữ đủ trợ từ."}, {"ex": [["わたしは音楽が好きです。", "Tôi thích âm nhạc."], ["田中さんは歌が上手です。", "Anh Tanaka hát giỏi."], ["わたしは野菜がきらいです。", "Tôi ghét rau."], ["兄は料理が上手です。", "Anh trai tôi nấu ăn giỏi."], ["妹は絵が下手です。", "Em gái tôi vẽ kém."]], "m": "Đối tượng của cảm xúc hoặc khả năng được đánh dấu bằng が, không dùng を: thích (好き), giỏi (上手), ghét (きらい), kém (下手) đều đi với が.", "n": "Phủ định của 好きです là 好きじゃありません, của 上手です là 上手じゃありません. Mức độ thường thêm とても／あまり ở phía trước.", "p": "N が 好きです／上手です", "s": "[N] が 好きです／上手です／きらいです／下手です。"}, {"ex": [["わたしは日本語がわかります。", "Tôi hiểu tiếng Nhật."], ["兄は英語がわかります。", "Anh trai tôi biết tiếng Anh."], ["この漢字がわかりません。", "Tôi không hiểu chữ Hán này."], ["田中さんは中国語がよくわかります。", "Anh Tanaka rất rành tiếng Trung."], ["わたしは少しだけわかります。", "Tôi chỉ hiểu một chút thôi."]], "m": "わかります (hiểu, biết) lấy đối tượng bằng が: ngôn ngữ, chữ viết, nội dung nào đó mà mình hiểu được.", "n": "Không nói 日本語をわかります. わかります chỉ khả năng hiểu tự nhiên, không phải hành động tác động trực tiếp lên đối tượng.", "p": "N が わかります", "s": "[N] が わかります。"}, {"ex": [["どんなスポーツが好きですか。", "Bạn thích môn thể thao nào?"], ["どんな映画を見たいですか。", "Bạn muốn xem loại phim nào?"], ["あの店はどんな店ですか。", "Cửa hàng kia là cửa hàng như thế nào?"], ["どんな飲み物がいいですか。", "Đồ uống loại nào thì được?"], ["田中さんはどんな人ですか。", "Anh Tanaka là người như thế nào?"]], "m": "どんな hỏi về loại, kiểu, tính chất của danh từ theo sau: “loại N nào, N như thế nào”. Trả lời bằng cách nêu loại cụ thể hoặc mô tả tính chất.", "n": "どんな luôn đứng trước danh từ; hỏi về vật cụ thể trong tầm mắt thì dùng どれ／どの chứ không dùng どんな.", "p": "どんな N", "s": "どんな + [N]"}, {"ex": [["日本語がよくわかります。", "Tôi hiểu rõ tiếng Nhật."], ["漢字を少し覚えました。", "Tôi đã nhớ được một ít chữ Hán."], ["お金がたくさんあります。", "Tôi có nhiều tiền."], ["わたしは肉をあまり食べません。", "Tôi không ăn thịt lắm."], ["その映画は全然面白くないです。", "Bộ phim đó chẳng thú vị chút nào."]], "m": "Phó từ chỉ mức độ và số lượng đứng ngay trước động từ hoặc tính từ để bổ nghĩa: よく (rõ, nhiều), だいたい (đại khái), 少し (một chút), たくさん (nhiều). Đi với câu phủ định thường dùng あまり (không … lắm) và 全然 (hoàn toàn không).", "n": "あまり và 全然 luôn đi với thể phủ định; không dùng chúng với câu khẳng định để diễn tả “không … lắm”.", "p": "Phó từ mức độ・số lượng: よく・だいたい・少し", "s": "よく／だいたい／少し／たくさん／あまり／全然 + V・A"}, {"ex": [["時間がありませんから、タクシーで行きます。", "Vì không có thời gian nên tôi đi bằng taxi."], ["明日は試験ですから、今晩勉強します。", "Vì ngày mai có kỳ thi nên tối nay tôi học."], ["頭が痛いですから、早く帰ります。", "Vì đau đầu nên tôi về sớm."], ["雨が降っていますから、出かけません。", "Vì trời đang mưa nên tôi không ra ngoài."], ["お金がありませんから、買いません。", "Vì không có tiền nên tôi không mua."]], "m": "から đặt ở cuối mệnh đề chỉ lý do, nghĩa là “vì … nên …”. Mệnh đề lý do đứng trước, kết quả đứng sau.", "n": "Khi trả lời câu hỏi どうして, chỉ cần nói mệnh đề lý do + から ở cuối, có thể lược phần kết quả nếu ngữ cảnh đã rõ.", "p": "～から、～（lý do）", "s": "[Câu 1] から、[Câu 2]。"}, {"ex": [["どうして昨日休みましたか。", "Tại sao hôm qua bạn nghỉ?"], ["どうして日本語を勉強しますか。", "Tại sao bạn học tiếng Nhật?"], ["どうして食べませんか。", "Tại sao bạn không ăn?"], ["どうして早く帰りましたか。", "Tại sao bạn về sớm?"], ["どうしてこの本を買いましたか。", "Tại sao bạn mua cuốn sách này?"]], "m": "どうして là từ để hỏi lý do: “tại sao, vì sao”. Câu trả lời thường kết thúc bằng ～から.", "n": "どうしてですか dùng một mình khi muốn hỏi “Sao vậy?” về điều người kia vừa nói.", "p": "どうして", "s": "どうして + [Câu] か。"}, {"ex": [["りんごを三つください。", "Cho tôi ba quả táo."], ["教室に学生が五人います。", "Trong lớp có năm học sinh."], ["駐車場に車が二台あります。", "Ở bãi đỗ xe có hai chiếc ô tô."], ["切手を四枚買いました。", "Tôi đã mua bốn con tem."], ["紙を十枚ください。", "Cho tôi mười tờ giấy."]], "m": "Số lượng trong tiếng Nhật đi kèm lượng từ (trợ số từ) tùy loại vật: vật nói chung đếm bằng ～つ, người bằng ～人, máy móc và xe bằng ～台, vật mỏng phẳng bằng ～枚, vật dài bằng ～本, sách vở bằng ～冊.", "n": "～つ đếm từ 1 đến 10: 一つ（ひとつ）、二つ（ふたつ）、三つ（みっつ)、四つ（よっつ)、五つ（いつつ)、六つ（むっつ)、七つ（ななつ)、八つ（やっつ)、九つ（ここのつ)、十（とお). Đếm người: 一人（ひとり)、二人（ふたり) là trường hợp đặc biệt.", "p": "Lượng từ: ～つ・～人・～台・～枚", "s": "［Số］+ つ／人／台／枚／本／冊…"}, {"ex": [["りんごを三つ買いました。", "Tôi đã mua ba quả táo."], ["ビールを二本飲みました。", "Tôi đã uống hai chai bia."], ["教室に椅子が六つあります。", "Trong phòng học có sáu cái ghế."], ["手紙を二枚書きました。", "Tôi đã viết hai lá thư."], ["本を三冊読みました。", "Tôi đã đọc ba cuốn sách."]], "m": "Khi nói số lượng của sự vật trong câu, cụm số lượng (số + lượng từ) thường đứng ngay trước động từ: “mua 3 quả táo”, “có 6 cái ghế”.", "n": "Số lượng không đứng ngay sau danh từ như tiếng Việt; vị trí tự nhiên là ngay trước động từ.", "p": "N を số lượng V", "s": "[N] を／が + ［số lượng］+ [V]"}, {"ex": [["昨日三時間勉強しました。", "Hôm qua tôi đã học ba tiếng."], ["駅から家まで三十分かかります。", "Từ ga đến nhà mất ba mươi phút."], ["休みは三日です。", "Kỳ nghỉ là ba ngày."], ["毎日二時間日本語を練習します。", "Mỗi ngày tôi luyện tiếng Nhật hai tiếng."], ["会議は一時間でした。", "Cuộc họp kéo dài một tiếng."]], "m": "Độ dài của khoảng thời gian nói bằng số + đơn vị thời gian: ～時間 (… tiếng), ～日 (… ngày), ～週間 (… tuần), ～か月 (… tháng), ～年 (… năm). Cụm này cho biết hành động kéo dài bao lâu.", "n": "Phân biệt thời điểm và khoảng thời gian: 3時 là thời điểm “3 giờ”, còn 3時間 là độ dài “3 tiếng”. Đếm ngày: 一日（いちにち）、二日（ふつか）、三日（みっか）。", "p": "Khoảng thời gian: ～時間・～日", "s": "［Số］+ 時間／日／週間／か月／年"}, {"ex": [["家から駅までどのくらいかかりますか。", "Từ nhà đến ga mất khoảng bao lâu?"], ["日本語をどのくらい勉強しましたか。", "Bạn đã học tiếng Nhật bao lâu rồi?"], ["東京まで三時間ぐらいかかります。", "Đến Tokyo mất khoảng ba tiếng."], ["学生は二十人ぐらいいます。", "Có khoảng hai mươi học sinh."], ["この辞書は三千円ぐらいです。", "Cuốn từ điển này khoảng ba nghìn yên."]], "m": "どのくらい dùng để hỏi độ dài thời gian, số lượng hoặc giá cả nói chung: “khoảng bao lâu, khoảng bao nhiêu”. Khi trả lời ước lượng, thêm ぐらい sau số lượng: “khoảng …”.", "n": "どのくらい hỏi chung chung; hỏi giá tiền cụ thể dùng いくら, hỏi số đếm cụ thể dùng từ để hỏi của lượng từ tương ứng (何台、何枚…).", "p": "どのくらい・～ぐらい", "s": "どのくらい + [Câu] か ／ ［số lượng］ぐらい"}, {"ex": [["一週間に二回映画を見ます。", "Tôi xem phim hai lần một tuần."], ["一日に三回薬を飲みます。", "Tôi uống thuốc ba lần một ngày."], ["一か月に一回家族に電話します。", "Tôi gọi điện cho gia đình một lần một tháng."], ["一年に四回旅行します。", "Tôi đi du lịch bốn lần một năm."], ["一週間に何回日本語を勉強しますか。", "Bạn học tiếng Nhật mấy lần một tuần?"]], "m": "Tần suất “mấy lần trong một khoảng thời gian” nói bằng: khoảng thời gian + に + số lần (回) + động từ.", "n": "回 đếm số lần: 一回（いっかい）、二回（にかい）、三回（さんかい）; từ để hỏi là 何回（なんかい）。", "p": "［Khoảng thời gian］に ～回 V", "s": "［Khoảng thời gian］に ［số］回 + [V]"}, {"ex": [["一人だけ来ました。", "Chỉ có một người đến."], ["お金が少しだけあります。", "Tôi chỉ có một ít tiền."], ["三日だけ休みます。", "Tôi chỉ nghỉ ba ngày."], ["わたしは野菜だけ食べます。", "Tôi chỉ ăn rau."], ["今日だけ忙しいです。", "Chỉ hôm nay là bận."]], "m": "だけ nghĩa là “chỉ”: giới hạn ở đúng cái đó, số đó, không hơn. だけ đứng sau danh từ hoặc sau cụm số lượng.", "n": "だけ đi trong câu còn mang nghĩa giới hạn loại trừ: 日本語だけわかります là “chỉ hiểu tiếng Nhật (ngoài ra không)”.", "p": "N／số lượng だけ", "s": "[N／số lượng] + だけ"}, {"ex": [["田中さんは結婚しています。", "Anh Tanaka đã kết hôn."], ["姉は東京に住んでいます。", "Chị gái tôi đang sống ở Tokyo."], ["母は眼鏡をかけています。", "Mẹ tôi đang đeo kính."], ["兄は車を持っています。", "Anh trai tôi có (sở hữu) một chiếc ô tô."], ["妹は赤い服を着ています。", "Em gái tôi đang mặc bộ đồ màu đỏ."]], "m": "Vて います diễn tả trạng thái là kết quả của một hành động đã xảy ra và còn kéo dài đến hiện tại: đã kết hôn, đang sống ở đâu, đang mang/đeo/cầm thứ gì, đang mặc gì.", "n": "Các động từ hay dùng ở nghĩa trạng thái: 結婚しています (đã kết hôn), 住んでいます (đang sống, nơi ở đi với に), 持っています (đang cầm / sở hữu), 着ています (đang mặc), かけています (đang đeo kính). Nghĩa “công việc, thói quen” xem mẫu Vて います còn lại của bài này.", "p": "Vて います（trạng thái）", "s": "V (thể て) + います"}, {"ex": [["田中さんの電話番号を知っていますか。", "Bạn có biết số điện thoại của anh Tanaka không?"], ["わたしはあの人を知りません。", "Tôi không biết người kia."], ["この漢字の読み方を知っています。", "Tôi biết cách đọc chữ Hán này."], ["妹は先生の住所を知っています。", "Em gái tôi biết địa chỉ của thầy."], ["駅への行き方を知りません。", "Tôi không biết đường đi đến ga."]], "m": "Biết một thông tin hay một người nào đó nói bằng 知っています; không biết nói 知りません. Động từ gốc 知ります nghĩa là “trở nên biết”, nên trạng thái “đang biết” luôn dùng thể て います.", "n": "Không nói 知ります với nghĩa “tôi biết” ở hiện tại, cũng không nói 知っていません; phủ định đúng là 知りません.", "p": "知っています／知りません", "s": "知っています ／ 知りません"}, {"ex": [["父は銀行に勤めています。", "Bố tôi làm việc ở ngân hàng."], ["姉は小学校で英語を教えています。", "Chị gái tôi dạy tiếng Anh ở trường tiểu học."], ["兄は毎朝走っています。", "Anh trai tôi chạy bộ mỗi sáng."], ["わたしは今、日本語を研究しています。", "Hiện tôi đang nghiên cứu tiếng Nhật."], ["妹はピアノを習っています。", "Em gái tôi đang học piano."]], "m": "Vて います còn diễn tả công việc đang làm thường xuyên hoặc thói quen lặp lại ở hiện tại: làm việc ở đâu, dạy môn gì, mỗi ngày làm gì.", "n": "Nơi làm việc đi với に khi dùng 勤めています (会社に勤めています). Cùng một mẫu て います nhưng nghĩa trạng thái hay thói quen là do động từ và ngữ cảnh quyết định.", "p": "Vて います（công việc・thói quen）", "s": "V (thể て) + います"}, {"ex": [["兄はお酒を飲まない。", "Anh trai tôi không uống rượu."], ["わたしは明日学校へ行かない。", "Ngày mai tôi không đi học."], ["妹は肉を食べない。", "Em gái tôi không ăn thịt."], ["今日は電車に乗らない。", "Hôm nay tôi không đi tàu điện."], ["父は新聞を読まない。", "Bố tôi không đọc báo."]], "m": "Thể ない là thể phủ định thường (không lịch sự) của động từ, là nền tảng của nhiều mẫu ở bài này. Cách chia: nhóm Ⅰ đổi âm cuối của thể ます sang hàng あ rồi thêm ない; nhóm Ⅱ bỏ る thêm ない; nhóm Ⅲ: 来ない（こない）、しない.", "n": "Đặc biệt: あります → ない (không có dạng ありない). Động từ nhóm Ⅰ tận cùng bằng う chia thành わない: 買います → 買わない.", "p": "Vない（thể ない）", "s": "V (thể ない): nhóm Ⅰ hàng あ + ない ／ nhóm Ⅱ bỏ る + ない ／ 来ない・しない"}, {"ex": [["ここでタバコを吸わないでください。", "Xin đừng hút thuốc ở đây."], ["写真を撮らないでください。", "Xin đừng chụp ảnh."], ["忘れないでください。", "Xin đừng quên."], ["一人で行かないでください。", "Xin đừng đi một mình."], ["心配しないでください。", "Xin đừng lo lắng."]], "m": "“Xin đừng làm V” — yêu cầu, nhờ ai đó không làm một việc gì, là lời yêu cầu trực tiếp và mềm hơn câu cấm đoán theo quy định.", "n": "Mạnh hơn và mang tính quy định là Vてはいけません (Bài 14); ないでください là lời yêu cầu trực tiếp với người nghe.", "p": "Vないでください", "s": "V (thể ない) + でください"}, {"ex": [["薬を飲まなければなりません。", "Tôi phải uống thuốc."], ["明日早く起きなければなりません。", "Ngày mai tôi phải dậy sớm."], ["レポートを出さなければなりません。", "Tôi phải nộp báo cáo."], ["病院へ行かなければなりません。", "Tôi phải đi bệnh viện."], ["宿題をしなければなりません。", "Tôi phải làm bài tập."]], "m": "“Phải làm V” — diễn tả nghĩa vụ, việc bắt buộc phải làm. Cách tạo: lấy thể ない, bỏ い ở cuối, thêm ければなりません.", "n": "Trong hội thoại thân mật hay nói tắt thành ～なきゃ hoặc ～ないと (xem Bài 21).", "p": "Vなければなりません", "s": "V (thể ない, bỏ い) + ければなりません"}, {"ex": [["明日来なくてもいいです。", "Ngày mai bạn không đến cũng được."], ["宿題は今日しなくてもいいです。", "Bài tập hôm nay không làm cũng được."], ["お金は払わなくてもいいです。", "Bạn không cần trả tiền đâu."], ["全部食べなくてもいいです。", "Bạn không cần ăn hết đâu."], ["名前を書かなくてもいいです。", "Bạn không cần viết tên đâu."]], "m": "“Không cần làm V cũng được” — việc đó không bắt buộc, làm hay không đều được. Đây là mẫu đối ngược với なければなりません.", "n": "Đừng nhầm với Vてもいいです (được phép làm): なくてもいい là “không làm cũng được”.", "p": "Vなくてもいいです", "s": "V (thể ない, bỏ い) + くてもいいです"}, {"ex": [["五時までに帰らなければなりません。", "Tôi phải về trước 5 giờ."], ["明日までにレポートを出してください。", "Xin hãy nộp báo cáo trước ngày mai."], ["来週までに本を読みます。", "Tôi sẽ đọc xong sách trước tuần sau."], ["土曜日までに電話してください。", "Xin hãy gọi điện trước thứ Bảy."], ["九時までに会社へ行きます。", "Tôi đi đến công ty trước 9 giờ."]], "m": "までに chỉ hạn chót: việc phải hoàn thành trước hoặc đúng tại thời điểm đó, “trước …, chậm nhất là …”.", "n": "Phân biệt まで (làm liên tục cho đến …) với までに (hoàn thành trước hạn …): 五時まで働きます là “làm việc đến 5 giờ”, khác với 五時までに帰ります là “về trước 5 giờ”.", "p": "［Thời gian］までに", "s": "［Thời gian］までに + [V]"}, {"ex": [["「書きます」の辞書形は「書く」です。", "Thể từ điển của “kakimasu” là “kaku”."], ["「食べます」の辞書形は「食べる」です。", "Thể từ điển của “tabemasu” là “taberu”."], ["「見ます」の辞書形は「見る」です。", "Thể từ điển của “mimasu” là “miru”."], ["「来ます」の辞書形は「来る」です。", "Thể từ điển của “kimasu” là “kuru”."], ["「勉強します」の辞書形は「勉強する」です。", "Thể từ điển của “benkyō shimasu” là “benkyō suru”."]], "m": "Thể từ điển là dạng cơ bản của động từ, là dạng ghi trong từ điển. Cách chia từ thể ます: nhóm Ⅰ đổi âm cuối sang hàng う; nhóm Ⅱ bỏ ます thêm る; nhóm Ⅲ: 来る（くる）、する. Nhiều mẫu ngữ pháp gắn trực tiếp vào thể này.", "n": "Thể từ điển cũng chính là thể thường ở hiện tại khẳng định (xem Bài 20).", "p": "V thể từ điển", "s": "V (thể từ điển): nhóm Ⅰ hàng う ／ nhóm Ⅱ bỏ ます + る ／ 来る・する"}, {"ex": [["わたしは日本語を話すことができます。", "Tôi có thể nói tiếng Nhật."], ["兄は車を運転することができます。", "Anh trai tôi có thể lái ô tô."], ["田中さんはピアノができます。", "Anh Tanaka biết chơi piano."], ["ここで写真を撮ることができますか。", "Ở đây có chụp ảnh được không?"], ["妹は漢字を読むことができません。", "Em gái tôi không đọc được chữ Hán."]], "m": "“Có thể, biết làm” — できます diễn tả khả năng. Danh từ chỉ môn học, kỹ năng đi với が できます; hành động thì dùng động từ thể từ điển + ことが できます.", "n": "Không nói するができます; phải nói することができます hoặc dùng danh từ + ができます.", "p": "N／Vことができます", "s": "[N] が できます ／ V (thể từ điển) + ことができます"}, {"ex": [["わたしの趣味は音楽を聞くことです。", "Sở thích của tôi là nghe nhạc."], ["兄の趣味はサッカーをすることです。", "Sở thích của anh trai tôi là chơi bóng đá."], ["趣味は旅行です。", "Sở thích của tôi là du lịch."], ["妹の趣味は本を読むことです。", "Sở thích của em gái tôi là đọc sách."], ["田中さんの趣味は写真を撮ることです。", "Sở thích của anh Tanaka là chụp ảnh."]], "m": "Khi sở thích là một hành động, dùng động từ thể từ điển + こと để biến hành động thành danh từ: “Sở thích của tôi là …”.", "n": "こと ở đây danh từ hóa động từ; khi sở thích là hành động, không đặt động từ nguyên dạng ngay trước です.", "p": "趣味は N／Vことです", "s": "趣味は [N] です ／ 趣味は V (thể từ điển) + ことです"}, {"ex": [["寝る前に、歯を磨きます。", "Trước khi ngủ, tôi đánh răng."], ["食事の前に、手を洗います。", "Trước bữa ăn, tôi rửa tay."], ["日本へ来る前に、日本語を勉強しました。", "Trước khi đến Nhật, tôi đã học tiếng Nhật."], ["出かける前に、天気を調べます。", "Trước khi ra ngoài, tôi kiểm tra thời tiết."], ["会議の前に、資料を読みます。", "Trước cuộc họp, tôi đọc tài liệu."]], "m": "“Trước khi làm V / trước N thì làm …” — mệnh đề chính xảy ra trước hành động ở 前に. Động từ trước 前に luôn ở thể từ điển, dù mệnh đề chính ở quá khứ.", "n": "Động từ trước 前に không chia quá khứ (không nói 寝た前に). Mẫu đối ngược là Vてから “sau khi làm xong”.", "p": "V／Nの 前に", "s": "V (thể từ điển) + 前に、～ ／ [N] の 前に、～"}, {"ex": [["三年前に日本へ来ました。", "Tôi đã đến Nhật cách đây ba năm."], ["一週間前にこの本を買いました。", "Tôi đã mua cuốn sách này một tuần trước."], ["三十年前にこの学校ができました。", "Trường này được xây cách đây ba mươi năm."], ["二か月前に結婚しました。", "Tôi đã kết hôn hai tháng trước."], ["五分前に田中さんは帰りました。", "Anh Tanaka đã về năm phút trước."]], "m": "“… trước, cách đây …” — khoảng thời gian + 前に đặt trong câu quá khứ để nói một việc đã xảy ra bao lâu về trước.", "n": "Phân biệt với mẫu V／Nの前に (trước khi …): khi có số lượng thời gian đứng trước 前に thì nghĩa là “cách đây”.", "p": "［Khoảng thời gian］前に", "s": "［Khoảng thời gian］+ 前に + [Câu quá khứ]"}, {"ex": [["バスがなかなか来ません。", "Xe buýt mãi không đến."], ["日本の生活になかなか慣れません。", "Tôi mãi không quen được cuộc sống ở Nhật."], ["荷物がなかなか着きません。", "Bưu phẩm mãi không tới."], ["彼はなかなか起きません。", "Anh ấy mãi không chịu dậy."], ["雨がなかなか止みません。", "Mưa mãi không tạnh."]], "m": "なかなか đi với câu phủ định diễn tả một việc mãi không xảy ra, khó mà xảy ra dù đã chờ đợi hoặc cố gắng: “mãi không …, khó …”.", "n": "なかなか còn có nghĩa khen “khá, rất” khi đi với câu khẳng định của tính từ (日本語がなかなか上手です) — dựa vào khẳng định/phủ định của câu để phân biệt hai nghĩa.", "p": "なかなか + phủ định", "s": "なかなか + [Câu phủ định]"}, {"ex": [["ぜひ日本へ行きたいです。", "Tôi rất muốn đi Nhật bằng được."], ["ぜひ遊びに来てください。", "Nhất định hãy đến chơi nhé."], ["ぜひこの映画を見てください。", "Bạn nhất định hãy xem bộ phim này."], ["明日はぜひ来てくださいね。", "Ngày mai nhất định đến nhé."], ["ぜひ食べてください。", "Nhất định hãy ăn nhé."]], "m": "ぜひ nhấn mạnh mong muốn mạnh mẽ: “nhất định, bằng mọi giá, rất mong”. ぜひ thường đi cùng mẫu muốn làm, lời mời hoặc lời đề nghị.", "n": "ぜひ không đứng một mình ở cuối câu; luôn đi kèm nguyện vọng, lời mời hoặc đề nghị ở phía sau.", "p": "ぜひ", "s": "ぜひ + [Vたい／Vてください／Vませんか]"}, {"ex": [["昨日映画を見た。", "Hôm qua tôi đã xem phim."], ["朝ごはんを食べた。", "Tôi đã ăn sáng."], ["友達に会った。", "Tôi đã gặp bạn."], ["本を読んだ。", "Tôi đã đọc sách."], ["日本へ行った。", "Tôi đã đi Nhật."]], "m": "Thể た là thể quá khứ thường (không lịch sự) của động từ. Cách chia giống hệt thể て, chỉ thay て bằng た, で bằng だ. Đây là nền tảng của các mẫu ことがあります、たり và ～たら.", "n": "Nhóm Ⅰ: 書いて → 書いた, 飲んで → 飲んだ; nhóm Ⅱ: 食べて → 食べた; nhóm Ⅲ: して → した, 来て（きて）→ 来た（きた). Riêng 行って → 行った.", "p": "Vた（thể た）", "s": "V (thể た): chia như thể て, đổi て → た、で → だ"}, {"ex": [["日本へ行ったことがあります。", "Tôi đã từng đi Nhật."], ["馬に乗ったことがあります。", "Tôi đã từng cưỡi ngựa."], ["その映画を見たことがありません。", "Tôi chưa từng xem bộ phim đó."], ["寿司を食べたことがありますか。", "Bạn đã từng ăn sushi chưa?"], ["富士山に登ったことがあります。", "Tôi đã từng leo núi Phú Sĩ."]], "m": "“Đã từng làm V” — diễn tả kinh nghiệm tính đến hiện tại. “Chưa từng” nói bằng Vたことがありません hoặc Vないことがあります.", "n": "Đừng nhầm với もう Vました (đã làm rồi — một việc cụ thể vừa hoàn thành): ことがあります nói về kinh nghiệm.", "p": "Vた ことが あります", "s": "V (thể た) + ことがあります"}, {"ex": [["日曜日は本を読んだり、音楽を聞いたりします。", "Chủ nhật tôi khi thì đọc sách, khi thì nghe nhạc."], ["休みの日は掃除したり、買い物したりします。", "Ngày nghỉ tôi khi thì dọn dẹp, khi thì mua sắm."], ["昨日は友達と話したり、映画を見たりしました。", "Hôm qua tôi khi thì nói chuyện với bạn, khi thì xem phim."], ["公園で走ったり、歩いたりします。", "Tôi khi thì chạy, khi thì đi bộ ở công viên."], ["夜はテレビを見たり、勉強したりします。", "Buổi tối tôi khi thì xem ti vi, khi thì học bài."]], "m": "Liệt kê một vài hành động tiêu biểu trong số nhiều hành động: “làm việc này, làm việc kia (chứ không chỉ có thế)”. Các động từ đều chia thể た + り, cuối câu kết bằng します.", "n": "Thì của câu do します ở cuối quyết định (します／しました); phần たり giữ nguyên không đổi thì.", "p": "Vたり、Vたり します", "s": "V1 (thể た) + り、V2 (thể た) + り します"}, {"ex": [["寒くなりました。", "Trời đã trở lạnh."], ["部屋が明るくなりました。", "Căn phòng đã sáng lên."], ["町が静かになりました。", "Thị trấn đã trở nên yên tĩnh."], ["日本語が上手になりたいです。", "Tôi muốn trở nên giỏi tiếng Nhật."], ["妹は先生になりました。", "Em gái tôi đã trở thành giáo viên."]], "m": "“Trở nên, trở thành” — diễn tả sự thay đổi trạng thái: tính từ い bỏ い thêm く, tính từ な và danh từ thêm に, rồi cộng なります.", "n": "Đây là thay đổi tự diễn ra; muốn nói chủ động “làm cho nó trở nên …” thì dùng します thay なります.", "p": "～く／～に なります", "s": "Aい (bỏ い) + く なります ／ Aな + に なります ／ [N] + に なります"}, {"ex": [["明日東京へ行く。", "Mai tôi đi Tokyo."], ["今日は忙しいから行かない。", "Hôm nay bận nên tôi không đi."], ["昨日友達に会った。", "Hôm qua tôi đã gặp bạn."], ["彼は来なかった。", "Anh ấy đã không đến."], ["うん、わかった。", "Ừ, hiểu rồi."]], "m": "Tiếng Nhật có hai văn phong: thể lịch sự (丁寧体, dùng ます／です) và thể thường (普通体). Thể thường dùng khi nói với bạn bè, người thân, người nhỏ tuổi hơn, và bắt buộc dùng trong các mệnh đề phụ. Bốn dạng của động từ: hiện tại khẳng định = thể từ điển, phủ định = thể ない, quá khứ = thể た, quá khứ phủ định = thể ない bỏ い + かった.", "n": "Câu hỏi thể thường bỏ か, chỉ lên giọng ở cuối câu: 行く？ Trả lời “ừ / không” thân mật là うん／ううん. Vて います nói tắt thành Vてる trong hội thoại thân mật (何してる？). Lược trợ từ は・を・へ khi nghĩa đã rõ đã học ở mẫu Lược trợ từ (Bài 7). Trước と思います、とき、前に… luôn dùng thể thường dù cả câu là lịch sự; các mẫu ～たい、～ている、～ことがある khi nằm trong mệnh đề phụ cũng chia theo thể thường.", "p": "Thể thường của động từ", "s": "普通体（động từ）: 行く・行かない・行った・行かなかった"}, {"ex": [["この本、高かった？", "Cuốn sách này đắt hả?"], ["今日は寒くない。", "Hôm nay không lạnh."], ["昨日は暇だった。", "Hôm qua tôi rảnh."], ["彼は学生じゃない。", "Anh ấy không phải học sinh."], ["あの町は静かじゃなかった。", "Thị trấn đó đã không yên tĩnh."]], "m": "Thể thường của tính từ い: giữ nguyên い (khẳng định), くない (phủ định), かった (quá khứ), くなかった (quá khứ phủ định). Thể thường của tính từ な và danh từ dùng だ thay です: だ／じゃない／だった／じゃなかった.", "n": "Khi nói lịch sự, thêm です sau các dạng thường của tính từ い (高かったです); với tính từ な và danh từ, だ đổi thành です, だった đổi thành でした.", "p": "Thể thường của tính từ・danh từ", "s": "普通体（tính từ・danh từ）: 高い・高くない・高かった・高くなかった ／ 静かだ・静かじゃない・静かだった・静かじゃなかった"}, {"ex": [["行きたいけど、時間がない。", "Tôi muốn đi nhưng không có thời gian."], ["この本は面白いけど、難しい。", "Cuốn sách này thú vị nhưng khó."], ["雨だけど、出かけます。", "Trời mưa nhưng tôi vẫn ra ngoài."], ["高いけど、買います。", "Đắt nhưng tôi vẫn mua."], ["彼は学生だけど、よく働きます。", "Anh ấy là học sinh nhưng làm việc chăm chỉ."]], "m": "けど là cách nói thân mật của が (nhưng), nối hai mệnh đề trái ngược hoặc dùng để mở đầu câu nói cho mềm. けど đứng sau thể thường của động từ, tính từ và danh từ.", "n": "けど còn dùng để mở đầu khi đề nghị cho nhẹ nhàng: すみませんけど… Văn phong trang trọng hơn dùng が hoặc けれども.", "p": "～けど、～", "s": "[Câu thể thường] + けど、[Câu]"}, {"ex": [["明日は雨が降ると思います。", "Tôi nghĩ ngày mai trời sẽ mưa."], ["田中さんはもう帰ったと思います。", "Tôi nghĩ anh Tanaka đã về rồi."], ["この本は面白いと思います。", "Tôi nghĩ cuốn sách này thú vị."], ["彼は来ないと思います。", "Tôi nghĩ anh ấy sẽ không đến."], ["日本の食べ物についてどう思いますか。", "Bạn nghĩ thế nào về đồ ăn Nhật Bản?"]], "m": "“Tôi nghĩ rằng …” — nêu phán đoán, ý kiến của người nói về một việc. Nội dung trước と phải ở thể thường.", "n": "Hỏi ý kiến người khác về một chủ đề: [N] について どう思いますか, trả lời bằng ～と思います. Nội dung phủ định thì phủ định nằm trước と: 来ないと思います (nghĩ là sẽ không đến), không phủ định ở 思います.", "p": "～と 思います", "s": "[Câu thể thường] + と 思います"}, {"ex": [["先生は「明日は休みです」と言いました。", "Thầy đã nói: “Ngày mai nghỉ”."], ["彼は明日来ると言いました。", "Anh ấy đã nói là ngày mai sẽ đến."], ["田中さんは忙しいと言いました。", "Anh Tanaka đã nói là anh ấy bận."], ["寝る前に「おやすみなさい」と言います。", "Trước khi ngủ, tôi nói “Chúc ngủ ngon”."], ["母は早く帰ると言いました。", "Mẹ tôi đã nói là sẽ về sớm."]], "m": "“Nói rằng …” — thuật lại lời nói của ai đó. Trích nguyên văn thì để trong 「」và giữ nguyên dạng câu gốc; thuật gián tiếp thì đổi nội dung sang thể thường trước と.", "n": "Thì của mệnh đề trích dẫn không phụ thuộc thì của câu chính: hôm qua nói về ngày mai thì vẫn giữ 来る.", "p": "～と 言います", "s": "「[Câu]」と 言います ／ [Câu thể thường] + と 言います"}, {"ex": [["明日は休みでしょう？", "Ngày mai là ngày nghỉ đúng không?"], ["この本は高いでしょう？", "Cuốn sách này đắt đúng không?"], ["田中さんは学生でしょう？", "Anh Tanaka là học sinh đúng không?"], ["昨日は寒かったでしょう？", "Hôm qua trời lạnh phải không?"], ["あの人は先生でしょう？", "Người kia là giáo viên đúng không?"]], "m": "でしょう lên giọng ở cuối câu dùng để xác nhận điều người nói tin là đúng và mong người nghe đồng ý: “… đúng không, … phải không”.", "n": "Trước でしょう dùng thể thường: bỏ です／ます (休みでしょう, không nói 休みですでしょう). でしょう còn dùng để phỏng đoán “chắc là” khi không lên giọng hỏi.", "p": "～でしょう？", "s": "[Câu thể thường] + でしょう？"}, {"ex": [["公園で祭りがあります。", "Ở công viên có lễ hội (được tổ chức)."], ["学校で試験があります。", "Ở trường có kỳ thi."], ["東京で会議があります。", "Ở Tokyo có cuộc họp."], ["明日、体育館で試合があります。", "Ngày mai ở nhà thi đấu có trận đấu."], ["近くのホールでコンサートがあります。", "Ở hội trường gần đây có buổi hòa nhạc."]], "m": "Khi あります nghĩa là “được tổ chức, diễn ra” với các sự kiện (lễ hội, trận đấu, buổi hòa nhạc, cuộc họp), địa điểm diễn ra sự kiện được đánh dấu bằng で, không dùng に.", "n": "Phân biệt: vật tồn tại ở đâu dùng に (机は部屋にあります); sự kiện diễn ra ở đâu dùng で.", "p": "N で N が あります（sự kiện）", "s": "[Nơi] で [Sự kiện] が あります"}, {"ex": [["お茶でも飲みませんか。", "Hay là uống gì đó như trà chẳng hạn nhé?"], ["映画でも見に行きましょう。", "Hay là đi xem phim chẳng hạn đi."], ["日曜日は散歩でもしたいです。", "Chủ nhật tôi muốn làm gì đó như đi dạo chẳng hạn."], ["コーヒーでもいかがですか。", "Một ly cà phê chẳng hạn thì sao ạ?"], ["休みの日は読書でもします。", "Ngày nghỉ tôi làm việc gì đó như đọc sách chẳng hạn."]], "m": "でも ở mẫu này nghĩa là “chẳng hạn như, hay là … chẳng hạn” — nêu một ví dụ tiêu biểu khi đề nghị hoặc nói mong muốn, hàm ý cái khác cũng được.", "n": "Đừng nhầm でも này (đi sau danh từ) với でも ở đầu câu nghĩa là “nhưng” (でも、高いです).", "p": "N でも", "s": "[N] + でも + [Câu đề nghị／nguyện vọng]"}, {"ex": [["もう帰らないと。", "Tôi phải về rồi."], ["薬を飲まないといけない。", "Tôi phải uống thuốc."], ["明日早く起きないと。", "Mai phải dậy sớm đấy."], ["宿題をしないとだめだよ。", "Không làm bài tập là không được đâu."], ["お金を払わないといけません。", "Tôi phải trả tiền."]], "m": "“Phải làm V” trong lời nói thân mật — dạng rút gọn của なければなりません (Bài 17). Thường chỉ nói ～ないと và lược phần いけない／だめ ở phía sau.", "n": "Dạng đầy đủ là ないといけない／ないとだめ; chỉ dùng trong văn phong thân mật, khi nói và viết lịch sự dùng なければなりません.", "p": "Vないと…", "s": "V (thể ない) + と（いけない／だめ）"}, {"ex": [["わたしが昨日買った本は日本語の本です。", "Cuốn sách tôi mua hôm qua là sách tiếng Nhật."], ["これは友達が撮った写真です。", "Đây là bức ảnh bạn tôi đã chụp."], ["母が作る料理はおいしいです。", "Món ăn mẹ tôi nấu rất ngon."], ["電話をかけている人は兄です。", "Người đang gọi điện thoại là anh trai tôi."], ["赤い靴をはいている人はだれですか。", "Người đang mang giày đỏ là ai vậy?"]], "m": "Một mệnh đề ở thể thường có thể đứng ngay trước danh từ để bổ nghĩa cho danh từ đó, giống mệnh đề quan hệ trong tiếng Việt: “cuốn sách [mà] tôi mua hôm qua”. Mệnh đề bổ nghĩa luôn đứng trước danh từ được bổ nghĩa.", "n": "Chủ ngữ bên trong mệnh đề bổ nghĩa dùng が, không dùng は (わたしが買った本). Danh từ được bổ nghĩa có thể làm chủ ngữ (は), tân ngữ (を) hoặc đi với が／に／へ trong câu chính tùy vai trò của nó. Cụm Vて いる + 人 hay dùng để chỉ người đang làm gì hoặc đang mặc gì.", "p": "Mệnh đề + N（bổ nghĩa cho danh từ）", "s": "[Mệnh đề thể thường] + [N]"}, {"ex": [["本を読む時間がありません。", "Tôi không có thời gian đọc sách."], ["友達と会う約束があります。", "Tôi có hẹn gặp bạn."], ["銀行へ行く用事があります。", "Tôi có việc phải đi ngân hàng."], ["勉強する時間を作りたいです。", "Tôi muốn tạo thời gian để học."], ["明日は彼と食事する約束です。", "Ngày mai tôi có hẹn ăn với anh ấy."]], "m": "Động từ thể từ điển đứng trước 時間 (thời gian), 約束 (cuộc hẹn, lời hứa), 用事 (việc bận) tạo thành cụm danh từ: “thời gian để làm V”, “cuộc hẹn làm V”, “việc phải làm V” — một ứng dụng của mệnh đề bổ nghĩa cho danh từ.", "n": "Đây chính là mẫu Mệnh đề + N của bài này áp dụng cho ba danh từ đặc biệt hay gặp: 時間・約束・用事.", "p": "V thể từ điển + 時間／約束／用事", "s": "V (thể từ điển) + 時間／約束／用事 + があります"}, {"ex": [["荷物を持ちましょうか。", "Để tôi cầm hành lý giúp nhé?"], ["タクシーを呼びましょうか。", "Để tôi gọi taxi giúp nhé?"], ["窓を開けましょうか。", "Để tôi mở cửa sổ nhé?"], ["駅まで送りましょうか。", "Để tôi đưa bạn ra ga nhé?"], ["手伝いましょうか。", "Để tôi giúp nhé?"]], "m": "Người nói chủ động đề nghị làm một việc gì đó cho người nghe: “Để tôi … nhé?”, “Tôi … giúp bạn nhé?”. Khác với ましょう (cùng nhau làm), ましょうか ở đây là đề nghị giúp đỡ.", "n": "Nhận lời: はい、お願いします; từ chối khéo: いいえ、けっこうです.", "p": "Vましょうか", "s": "V (bỏ ます) + ましょうか"}, {"ex": [["家へ帰るとき、パンを買いました。", "Khi về nhà (trên đường về), tôi đã mua bánh mì."], ["家へ帰ったとき、「ただいま」と言います。", "Khi đã về đến nhà, tôi nói “Con đã về”."], ["子どものとき、よく公園で遊びました。", "Hồi còn nhỏ, tôi thường chơi ở công viên."], ["暇なとき、映画を見ます。", "Khi rảnh, tôi xem phim."], ["頭が痛いとき、この薬を飲みます。", "Khi đau đầu, tôi uống thuốc này."]], "m": "“Khi, lúc …” — とき nối mệnh đề chỉ thời điểm với mệnh đề chính. Dùng thể từ điển (Vる) khi hành động ở とき chưa xảy ra tại thời điểm của mệnh đề chính; dùng thể た (Vた) khi hành động đó đã hoàn thành trước.", "n": "Phân biệt: 帰るとき là khi đang trên đường về, chưa về tới; 帰ったとき là khi đã về tới. Tính từ な thêm な (暇なとき), danh từ thêm の (子どものとき).", "p": "～とき、～", "s": "Vる／Vた + とき、～ ／ Aい + とき ／ Aな + な + とき ／ [N] + の + とき"}, {"ex": [["このボタンを押すと、切符が出ます。", "Cứ bấm nút này thì vé sẽ ra."], ["あの角を右へ曲がると、駅があります。", "Rẽ phải ở góc kia thì sẽ thấy ga."], ["春になると、花が咲きます。", "Cứ đến mùa xuân là hoa nở."], ["このつまみを回すと、音が大きくなります。", "Vặn núm này thì âm thanh sẽ to lên."], ["まっすぐ行くと、左に銀行があります。", "Đi thẳng thì ngân hàng ở bên trái."]], "m": "“Cứ làm V thì (chắc chắn) sẽ …” — と diễn tả kết quả tất yếu, hiển nhiên xảy ra sau một điều kiện; hay dùng khi chỉ đường và giải thích cách vận hành máy móc.", "n": "Mệnh đề sau と không dùng để diễn tả ý chí, yêu cầu hay rủ rê; những trường hợp đó dùng たら (Bài 25).", "p": "V thể từ điển と、～", "s": "V (thể từ điển) + と、～"}, {"ex": [["公園を散歩します。", "Tôi đi dạo trong công viên."], ["道を渡ります。", "Tôi băng qua đường."], ["橋を渡ると、右に店があります。", "Qua cầu thì cửa hàng ở bên phải."], ["バスを降ります。", "Tôi xuống xe buýt."], ["部屋を出ます。", "Tôi ra khỏi phòng."]], "m": "を còn đánh dấu không gian mà hành động di chuyển đi qua, băng qua, hoặc điểm xuất phát rời đi: đi qua công viên, băng qua đường, xuống tàu, ra khỏi phòng.", "n": "を ở mẫu này không phải tân ngữ chịu tác động; nó đi với các động từ di chuyển như 歩きます、散歩します、渡ります、出ます、降ります.", "p": "N を V（di chuyển）", "s": "[Nơi／đường] を + V di chuyển"}, {"ex": [["佐藤さんはわたしに花をくれました。", "Chị Sato đã tặng hoa cho tôi."], ["母がセーターをくれました。", "Mẹ đã cho tôi chiếc áo len."], ["友達が本をくれました。", "Bạn đã tặng sách cho tôi."], ["先生は妹に辞書をくれました。", "Thầy đã cho em gái tôi cuốn từ điển."], ["兄が時計をくれて、うれしかったです。", "Anh trai tặng đồng hồ cho tôi, tôi rất vui."]], "m": "くれます dùng khi người khác cho, tặng một vật cho mình hoặc người nhà của mình. Không dùng あげます trong trường hợp này, vì あげます chỉ dùng khi người cho không phải là phía người khác cho mình.", "n": "Ba động từ cho — nhận với vật: あげます (mình cho người khác), もらいます (mình nhận từ người khác), くれます (người khác cho mình). Bài 7 đã học hai động từ đầu, bài này hoàn thiện với くれます.", "p": "N を くれます", "s": "[Người] は [tôi／người nhà] に [N] を くれます"}, {"ex": [["わたしはおばあさんに荷物を運んであげました。", "Tôi đã mang hành lý giúp bà."], ["母に料理を作ってあげます。", "Tôi nấu ăn cho mẹ."], ["友達に日本語を教えてあげました。", "Tôi đã dạy tiếng Nhật cho bạn."], ["子どもに本を読んであげます。", "Tôi đọc sách cho em bé nghe."], ["妹を駅まで送ってあげました。", "Tôi đã đưa em gái ra ga."]], "m": "Mình làm một hành động nào đó cho người khác (mang tính giúp đỡ, làm ơn cho họ). Người nhận hành động đi với に khi họ là đích của hành động.", "n": "Không dùng Vてあげます khi người khác làm cho mình; trường hợp đó dùng てもらいます／てくれます.", "p": "Vてあげます", "s": "V (thể て) + あげます"}, {"ex": [["わたしは友達に写真を撮ってもらいました。", "Tôi được bạn chụp ảnh cho."], ["先生に漢字を教えてもらいました。", "Tôi được thầy dạy chữ Hán cho."], ["姉に車で送ってもらいました。", "Tôi được chị gái đưa đi bằng ô tô."], ["店の人に道を教えてもらいました。", "Tôi được nhân viên cửa hàng chỉ đường cho."], ["母にセーターを送ってもらいました。", "Tôi được mẹ gửi áo len cho."]], "m": "Mình nhận được một hành động giúp đỡ từ người khác: “được ai đó làm V cho”. Chủ ngữ là người nhận sự giúp đỡ, người làm giúp đi với に.", "n": "てもらいます hàm ý biết ơn và thường là phía mình nhờ hoặc nhận chủ động; so sánh với てくれます ở mẫu sau.", "p": "Vてもらいます", "s": "V (thể て) + もらいます"}, {"ex": [["友達が傘を貸してくれました。", "Bạn đã cho tôi mượn ô."], ["母が弁当を作ってくれます。", "Mẹ làm cơm hộp cho tôi."], ["先生が辞書を見せてくれました。", "Thầy đã cho tôi xem từ điển."], ["姉が駅まで迎えに来てくれました。", "Chị gái đã ra ga đón tôi."], ["兄が写真を送ってくれました。", "Anh trai đã gửi ảnh cho tôi."]], "m": "Người khác (tự nguyện, tử tế) làm một hành động cho mình hoặc người nhà mình. Chủ ngữ là người làm giúp; phía mình thường được lược bỏ vì ngữ cảnh đã rõ.", "n": "Phân biệt: てもらいます đặt trọng tâm ở phía người nhận (mình), てくれます đặt trọng tâm ở phía người làm giúp và tấm lòng của họ. Cả hai chỉ dùng khi phía nhận là mình hoặc người nhà mình.", "p": "Vてくれます", "s": "V (thể て) + くれます"}, {"ex": [["お金があったら、旅行したいです。", "Nếu có tiền, tôi muốn đi du lịch."], ["もし暇だったら、手伝ってください。", "Nếu rảnh, xin hãy giúp tôi."], ["家へ帰ったら、すぐ寝ます。", "Về đến nhà là tôi đi ngủ ngay."], ["安かったら、買います。", "Nếu rẻ thì tôi mua."], ["雨が降ったら、出かけません。", "Nếu trời mưa thì tôi không ra ngoài."]], "m": "たら tạo mệnh đề điều kiện “nếu …, khi …” bằng cách lấy thể quá khứ thường (Vた, Aかった, Aな/N だった) thêm ら. Dùng cho giả định, điều kiện và cả “khi/sau khi việc trước xong thì …”. Hay đi với もし ở đầu câu để nhấn mạnh giả định.", "n": "Cách chia giống nhau cho mọi loại từ: Vた + ら, Aい → Aかった + ら, Aな/N → だった + ら. Khác với と (Bài 23), sau たら có thể dùng ý chí, yêu cầu, rủ rê (手伝ってください).", "p": "～たら", "s": "[Câu thể thường quá khứ] + ら、～"}, {"ex": [["雨が降っても、試合があります。", "Dù trời mưa, trận đấu vẫn diễn ra."], ["高くても、買いたいです。", "Dù đắt, tôi vẫn muốn mua."], ["日曜日でも、働きます。", "Dù là Chủ nhật, tôi vẫn làm việc."], ["忙しくても、電話します。", "Dù bận, tôi vẫn gọi điện."], ["いくら考えても、わかりません。", "Dù nghĩ thế nào tôi cũng không hiểu."]], "m": "“Dù …, cho dù … thì (kết quả vẫn không đổi)” — mệnh đề nhượng bộ: điều kiện ở phía trước dù thế nào cũng không làm thay đổi mệnh đề chính.", "n": "Cách chia: động từ thể て + も, tính từ い bỏ い + くても, tính từ な và danh từ + でも. Hay đi với いくら ở đầu để nhấn mạnh “dù có … đến mấy”.", "p": "～ても／～でも", "s": "Vて／Aくて + も、～ ／ Aな・[N] + でも、～"}, {"ex": [["友達が来る前に、部屋を掃除します。", "Trước khi bạn đến, tôi dọn phòng."], ["妻が病気のとき、会社を休みます。", "Khi vợ bị ốm, tôi nghỉ làm."], ["彼が来なかったら、始めましょう。", "Nếu anh ấy không đến thì chúng ta bắt đầu thôi."], ["子どもが寝たとき、静かにしてください。", "Khi em bé đã ngủ, xin hãy giữ yên lặng."], ["電車が着いたら、電話してください。", "Khi tàu đến, hãy gọi điện cho tôi nhé."]], "m": "Khi mệnh đề phụ (～たら, ～ても, ～とき, ～前に, ～と, ～てから) có chủ ngữ khác với chủ ngữ của mệnh đề chính, chủ ngữ của mệnh đề phụ được đánh dấu bằng が, không dùng は.", "n": "Quy tắc này áp dụng cho mọi mệnh đề phụ đã học: ～てから、～とき、～と、～前に、～たら、～ても. Nếu hai mệnh đề cùng chủ ngữ thì thường lược chủ ngữ của mệnh đề phụ.", "p": "Chủ ngữ mệnh đề phụ dùng が", "s": "[Chủ ngữ] が + …たら／ても／とき／前に／と、～"}], "N4": [{"p": "V-る/ない + んです", "s": "[Câu thường] + んです。/ んですが、〜", "m": "Dùng khi giải thích tình huống, lý do; hoặc khi muốn hỏi/đưa ra lý do một cách mềm mỏng. Văn phong thân mật: んだ.", "ex": [["明日は早く起きなければならないんです。", "Ngày mai tôi phải dậy sớm (nên là…)."], ["頭が痛いんです。", "Tôi bị đau đầu (chuyện là…)."], ["日本語が難しいんです。だから、毎日たくさん勉強しています。", "Tiếng Nhật khó quá (nên là…). Vì vậy, ngày nào tôi cũng học rất nhiều."], ["明日テストがあるんですが、まだぜんぜん勉強していません。", "Ngày mai có bài kiểm tra (chuyện là…), mà tôi vẫn chưa học gì cả."]], "n": "Câu hỏi với んですか thường mang sắc thái muốn được giải thích, không dùng để hỏi thông tin trung tính.", "lesson": 26}, {"p": "V-て いただけませんか", "s": "V-て + いただけませんか", "m": "Cách nhờ vả lịch sự hơn 〜てください: “anh/chị có thể … giúp tôi được không?”", "ex": [["すみませんが、この書類をコピーしていただけませんか。", "Xin lỗi, anh/chị có thể photo giúp tôi tài liệu này không?"], ["窓を開けていただけませんか。", "Anh/chị mở giúp tôi cửa sổ được không?"], ["すみませんが、もう一度ゆっくり話していただけませんか。よく分かりませんでした。", "Xin lỗi, anh/chị có thể nói lại chậm một lần nữa giúp tôi được không? Tôi chưa nghe rõ."], ["この漢字の読み方を教えていただけませんか。辞書で調べても分かりませんでした。", "Anh/chị chỉ giúp tôi cách đọc chữ Hán này được không? Tôi tra từ điển mà vẫn không hiểu."]], "n": "いただく là khiêm nhường ngữ của もらう.", "lesson": 26}, {"p": "Động từ thể khả năng (V-れる/られる)", "s": "N が V-khả năng", "m": "Động từ thể khả năng: nhóm 1 đổi -i thành -e + る; nhóm 2 bỏ る + られる; する→できる、来る→来られる. Đối tượng của khả năng dùng が.", "ex": [["日本語を話すことができます。→ 日本語が話せます。", "Có thể nói tiếng Nhật."], ["ピアノが弾けます。", "Tôi có thể chơi piano."], ["私の友達が日本語を話せます。彼は東京に住んでいます。", "Bạn tôi có thể nói tiếng Nhật. Anh ấy sống ở Tokyo."], ["妹はピアノが弾けます。毎日2時間練習しています。", "Em gái tôi có thể chơi piano. Ngày nào em cũng luyện tập 2 tiếng."]], "n": "られる của nhóm 2 còn dùng cho bị động và ý tôn kính — phân biệt theo ngữ cảnh.", "lesson": 27}, {"p": "N が 見えます / 聞こえます", "s": "N が 見えます / 聞こえます", "m": "Chỉ việc tự nhiên nhìn/nghe thấy được, không cần nỗ lực. Khác với 見られます/聞けます (khả năng có chủ đích).", "ex": [["窓から海が見えます。", "Từ cửa sổ nhìn thấy biển."], ["鳥の声が聞こえます。", "Nghe thấy tiếng chim hót."], ["部屋の窓から富士山が見えます。景色がとてもきれいです。", "Từ cửa sổ phòng nhìn thấy núi Phú Sĩ. Cảnh đẹp lắm."], ["夜になると、虫の声が聞こえます。静かな夏の夜です。", "Khi đêm xuống, nghe thấy tiếng côn trùng kêu. Đó là một đêm hè yên tĩnh."]], "n": "見えます ≠ 見られます: “nhìn thấy được (tự nhiên)” ≠ “có thể xem”.", "lesson": 27}, {"p": "〜しか + phủ định", "s": "N + しか + V-ない", "m": "“Chỉ … thôi mà không hơn” — luôn đi với thể phủ định, mang sắc thái thiếu/không đủ.", "ex": [["今日はバスでしか行けません。", "Hôm nay chỉ có thể đi bằng xe buýt thôi."], ["わたしはひらがなしか読めません。", "Tôi chỉ đọc được hiragana thôi."], ["今日は1000円しか持っていません。だから、高いものは買えません。", "Hôm nay tôi chỉ mang theo 1000 yên thôi. Vì vậy không mua được đồ đắt."], ["彼は日本語しか話せません。英語はぜんぜん分かりません。", "Anh ấy chỉ nói được tiếng Nhật thôi. Tiếng Anh thì hoàn toàn không biết."]], "n": "しか không dùng với thể khẳng định.", "lesson": 27}, {"p": "は (đối比)", "s": "N1 は …, N2 は …", "m": "は đặt sau danh từ thứ hai để đối比 hai vế: “còn … thì …”.", "ex": [["漢字は難しいですが、ひらがなは簡単です。", "Chữ Hán thì khó, còn hiragana thì dễ."], ["兄は背が高いですが、私は低いです。", "Anh trai thì cao, còn tôi thì thấp."], ["東京は大きいですが、大阪はもっとにぎやかです。", "Tokyo thì lớn, còn Osaka thì náo nhiệt hơn."], ["冬は寒いですが、夏は暑いです。", "Mùa đông thì lạnh, còn mùa hè thì nóng."]], "n": "は trong trường hợp này đọc là “wa” như trợ từ chủ đề.", "lesson": 27}, {"p": "V-ます + ながら", "s": "V1-ます + ながら、V2", "m": "Hai hành động diễn ra đồng thời, hành động sau ながら là hành động chính.", "ex": [["音楽を聞きながら勉強します。", "Tôi vừa nghe nhạc vừa học."], ["歌いながら歩きます。", "Vừa hát vừa đi bộ."], ["毎朝、歩きながら音楽を聞きます。とても気持ちがいいです。", "Mỗi sáng, tôi vừa đi bộ vừa nghe nhạc. Cảm giác rất dễ chịu."], ["テレビを見ながらご飯を食べます。家族と話す時間も大切です。", "Tôi vừa xem TV vừa ăn cơm. Thời gian trò chuyện với gia đình cũng rất quý."]], "n": "Chủ ngữ của hai hành động phải là cùng một người.", "lesson": 28}, {"p": "V-て います (thói quen)", "s": "V-て います", "m": "Ngoài nghĩa “đang”, ています còn diễn tả hành động lặp lại thành thói quen, hoặc nghề nghiệp/trạng thái đang theo.", "ex": [["彼はテレビを見ています。", "Anh ấy đang xem TV (thói quen hằng ngày)."], ["毎朝ジョギングをしています。", "Mỗi sáng tôi chạy bộ."], ["父は毎朝6時に起きています。健康のために運動もしています。", "Bố tôi dậy lúc 6 giờ mỗi sáng. Bố cũng tập thể dục vì sức khỏe."], ["彼女は今、東京の会社で働いています。来年大阪へ行くそうです。", "Cô ấy hiện đang làm việc ở một công ty tại Tokyo. Nghe nói sang năm cô ấy sẽ chuyển đến Osaka."]], "n": "Phân biệt với ています chỉ tiến hành thuần túy ở N5 theo ngữ cảnh có từ chỉ tần suất.", "lesson": 28}, {"p": "〜し、〜し", "s": "[Câu thường] し、[Câu thường] し", "m": "Liệt kê nhiều lý do song song, hàm ý “và còn nhiều lý do nữa”.", "ex": [["彼は若いし、元気だし、いい人です。", "Anh ấy vừa trẻ, vừa khoẻ, lại là người tốt."], ["忙しいし、疲れたし、早く帰りたいです。", "Vừa bận, vừa mệt, nên tôi muốn về sớm."], ["この店は安いし、おいしいし、よく行きます。", "Quán này vừa rẻ, vừa ngon, nên tôi hay đến."], ["彼は優しいし、面白いし、みんなに人気があります。", "Anh ấy vừa hiền, vừa hài hước, nên được mọi người yêu mến."]], "n": "し nối các mệnh đề có cùng tính chất (cùng khẳng định hoặc cùng phủ định).", "lesson": 28}, {"p": "Tự động từ + て います (trạng thái)", "s": "N が V-tự động từ-て います", "m": "Tự động từ + ています diễn tả trạng thái kết quả còn duy trì: cửa mở, đèn sáng, cửa kính vỡ…", "ex": [["ドアが開いています。", "Cửa đang mở (trạng thái)."], ["電気がついています。", "Đèn đang bật."], ["窓が開いています。外から鳥の声が聞こえます。", "Cửa sổ đang mở. Từ ngoài nghe thấy tiếng chim hót."], ["カーテンが開いています。外がよく見えます。", "Rèm đang mở. Nhìn ra ngoài rất rõ."]], "n": "Tự động từ là động từ chỉ sự việc tự xảy ra, không có tác nhân trực tiếp.", "lesson": 29}, {"p": "Tự động từ chỉ kết quả (割れる・壊れる…)", "s": "N が V-て います", "m": "Tự động từ nhóm kết quả: 割れます、止まります、壊れます、汚れます… dùng với ています để tả trạng thái sau khi sự việc xảy ra.", "ex": [["窓が割れています。", "Cửa kính bị vỡ."], ["時計が止まっています。", "Đồng hồ đã dừng."], ["この時計が壊れています。新しい時計を買わなければなりません。", "Chiếc đồng hồ này đã hỏng. Tôi phải mua đồng hồ mới."], ["壁が汚れています。週末に掃除をしようと思っています。", "Tường đã bị bẩn. Tôi định cuối tuần sẽ dọn dẹp."]], "n": "Không dùng を với tự động từ; chủ thể đi với が.", "lesson": 29}, {"p": "V-て おきます", "s": "V-て おきます", "m": "Làm sẵn một việc để chuẩn bị cho sau này. Dạng nói tắt: 〜とく / 〜どく.", "ex": [["予約をしておきます。", "Tôi sẽ đặt trước (để chuẩn bị)."], ["旅行の前に、ホテルをとっておきます。", "Trước chuyến đi, tôi đặt khách sạn trước."], ["明日の旅行のために、今日荷物を作っておきます。朝早く出発しますから。", "Để chuẩn bị cho chuyến đi ngày mai, hôm nay tôi sẽ soạn đồ trước. Vì sáng mai sẽ xuất phát sớm."], ["来客のために、部屋を掃除しておきます。お茶も用意しておきます。", "Vì có khách đến, tôi sẽ dọn phòng trước. Tôi cũng sẽ chuẩn bị sẵn trà."]], "n": "ておきます khác てあります: ておく nhấn vào hành động chuẩn bị, てある nhấn vào trạng thái sẵn sàng.", "lesson": 30}, {"p": "Tha động từ + て あります", "s": "N が V-tha động từ-て あります", "m": "Tha động từ + てあります: ai đó đã làm sẵn và kết quả đang ở trạng thái sẵn sàng dùng.", "ex": [["窓が開けてあります。", "Cửa sổ đã được mở sẵn."], ["机の上に資料が置いてあります。", "Tài liệu đã được để sẵn trên bàn."], ["壁にカレンダーがかけてあります。毎朝予定を確認します。", "Trên tường đã treo sẵn lịch. Mỗi sáng tôi xem lịch để kiểm tra kế hoạch."], ["冷蔵庫に牛乳が入れてあります。朝ご飯に飲みます。", "Trong tủ lạnh đã để sẵn sữa. Tôi sẽ uống vào bữa sáng."]], "n": "Đối tượng của tha động từ khi dùng てあります thường chuyển thành が.", "lesson": 30}, {"p": "V-ý chí + と 思っています", "s": "V-ý chí + と 思っています", "m": "Diễn tả dự định đã quyết từ trước và vẫn đang giữ: “định sẽ…”.", "ex": [["来年日本へ留学しようと思っています。", "Tôi định năm sau đi du học Nhật."], ["週末は映画を見ようと思っています。", "Cuối tuần tôi định xem phim."], ["来年、北海道へ旅行しようと思っています。雪祭りを見たいです。", "Tôi định sang năm sẽ đi du lịch Hokkaido. Tôi muốn xem lễ hội tuyết."], ["将来、日本で日本語の先生になろうと思っています。今から一生懸命勉強しています。", "Tôi định sau này sẽ trở thành giáo viên tiếng Nhật ở Nhật. Từ bây giờ tôi đang học rất chăm chỉ."]], "n": "よう là thể ý chí （意向形）: nhóm 1 đổi -u → -ō; nhóm 2 bỏ る + よう; する→しよう、来る→来よう. Khác ようと思います (ý định vừa quyết ngay lúc nói).", "lesson": 31}, {"p": "V-る/ない + つもりです", "s": "V-る / V-ない + つもりです", "m": "Dự định chắc chắn của người nói. Phủ định: V-ない + つもりです (định không làm) hoặc V-る + つもりはありません (không có ý định).", "ex": [["明日からたばこをやめるつもりです。", "Từ ngày mai tôi định bỏ thuốc lá."], ["週末、友達と買い物に行くつもりです。", "Cuối tuần tôi định đi mua sắm với bạn."], ["今度の休みに山へ登るつもりです。友達と一緒に登ります。", "Kỳ nghỉ tới tôi định leo núi. Tôi sẽ leo cùng bạn."], ["今日は早く寝るつもりです。明日は朝6時に起きます。", "Hôm nay tôi định đi ngủ sớm. Ngày mai tôi sẽ dậy lúc 6 giờ sáng."]], "n": "つもり chỉ dùng cho dự định của chính người nói (ngôi thứ nhất), ngôi thứ ba thêm はず/そうです khi thuật lại.", "lesson": 31}, {"p": "まだ + V-て いません", "s": "まだ V-て いません", "m": "“Vẫn chưa …” — trả lời cho câu hỏi もう〜ましたか. Đi với まだです khi trả lời ngắn.", "ex": [["レポートはまだ書いていません。", "Tôi vẫn chưa viết báo cáo."], ["宿題はもう終わりましたか。— いいえ、まだです。", "Bài tập xong chưa? — Chưa."], ["宿題はまだ終わっていません。あと少しで終わります。", "Bài tập tôi vẫn chưa làm xong. Chỉ còn một chút nữa là xong."], ["昼ご飯はまだ食べていません。おなかがすきました。", "Tôi vẫn chưa ăn trưa. Tôi đói bụng rồi."]], "n": "まだ + phủ định = vẫn chưa; まだ + khẳng định = vẫn còn.", "lesson": 31}, {"p": "V-た/ない + ほうが いいです", "s": "V-た + ほうがいいです / V-ない + ほうがいいです", "m": "Khuyên ai đó nên / không nên làm gì — lời khuyên mang tính nhắc nhở, có thể hơi nặng.", "ex": [["もっと野菜を食べたほうがいいです。", "Bạn nên ăn nhiều rau hơn."], ["無理をしないほうがいいです。", "Bạn không nên gắng sức quá."], ["風邪をひいたら、早く病院へ行ったほうがいいです。無理をしないでください。", "Nếu bị cảm, bạn nên đi bệnh viện sớm. Đừng cố gắng quá sức."], ["分からないことは、先生に聞いたほうがいいです。自分で考えることも大切ですが。", "Chỗ nào không hiểu thì nên hỏi thầy cô. Tự suy nghĩ cũng quan trọng, nhưng (hỏi thì tốt hơn)."]], "n": "Nguyên tắc: khẳng định dùng V-た, phủ định dùng V-ない + ほうがいい.", "lesson": 32}, {"p": "〜でしょう (phỏng đoán)", "s": "[Câu thường] + でしょう", "m": "Phỏng đoán “chắc là…”. Dạng thường: だろう. Văn thân mật nam giới hay dùng だろう.", "ex": [["明日は雨が降るでしょう。", "Ngày mai chắc trời sẽ mưa."], ["彼はもうすぐ来るでしょう。", "Chắc anh ấy sắp đến rồi."], ["明日は晴れるでしょう。洗濯物を干すことができます。", "Ngày mai chắc trời sẽ nắng. Có thể phơi đồ giặt được."], ["彼はもうすぐ着くでしょう。もう少し待ちましょう。", "Chắc anh ấy sắp đến rồi. Chúng ta đợi thêm một chút nhé."]], "n": "でしょう còn dùng khi xác nhận lại thông tin với người nghe (giọng lên cuối câu).", "lesson": 32}, {"p": "〜かもしれません", "s": "[Câu thường] + かもしれません", "m": "“Có thể là…” — mức chắc chắn thấp hơn でしょう.", "ex": [["電車が遅れるかもしれません。", "Tàu có thể sẽ đến muộn."], ["彼は知らないかもしれません。", "Có thể anh ấy không biết."], ["今夜は雪が降るかもしれません。暖かい服を着てください。", "Tối nay có thể sẽ có tuyết rơi. Hãy mặc áo ấm nhé."], ["田中さんは今日休むかもしれません。昨日体調が悪かったそうです。", "Có thể hôm nay anh Tanaka sẽ nghỉ. Nghe nói hôm qua anh ấy không được khỏe."]], "n": "Dạng thường: かもしれない; thân mật: かも.", "lesson": 32}, {"p": "Động từ thể mệnh lệnh (命令形)", "s": "V-mệnh lệnh", "m": "Mệnh lệnh mạnh, dùng trong khẩu hiệu, hướng dẫn khẩn cấp, lời nói của cấp trên/nam giới thân mật. Nhóm 1: -u → -e; nhóm 2: る → ろ; する→しろ、来る→来い（こい).", "ex": [["早く起きろ。", "Dậy mau lên!"], ["静かにしろ。", "Im lặng đi!"], ["早く寝ろ。明日は朝早いんだよ。", "Đi ngủ nhanh lên! Ngày mai dậy sớm đấy."], ["早く座れ。授業が始まるよ。", "Ngồi xuống nhanh lên! Buổi học sắp bắt đầu rồi."]], "n": "Không dùng với người trên hoặc người lạ — dễ gây mất lịch sự.", "lesson": 33}, {"p": "Động từ thể cấm đoán (禁止形)", "s": "V-る + な", "m": "Cấm đoán mạnh: V-る nguyên dạng + な. Thường thấy trên biển báo.", "ex": [["ここに入るな。", "Cấm vào đây!"], ["たばこを吸うな。", "Đừng hút thuốc!"], ["ここで写真を撮るな。美術館の中は撮影禁止だよ。", "Đừng chụp ảnh ở đây! Trong bảo tàng cấm chụp ảnh đấy."], ["この川で泳ぐな。とても危ないよ。", "Đừng bơi ở con sông này! Nguy hiểm lắm đấy."]], "n": "Đối tác lịch sự vẫn là 〜ないでください.", "lesson": 33}, {"p": "〜と 書いてあります / 〜という 意味です", "s": "「…」と 書いてあります / N は「…」という意味です", "m": "Dùng khi giải thích ý nghĩa của từ/hình ảnh, hoặc trích nội dung được viết ở đâu đó.", "ex": [["この漢字は「やま」という意味です。", "Chữ Hán này có nghĩa là 'núi'."], ["標識に「止まれ」と書いてあります。", "Trên biển báo có viết là 'Dừng lại'."], ["入口のドアに「押す」と書いてあります。引かないでください。", "Trên cửa ra vào có viết là 'Đẩy'. Đừng kéo nhé."], ["この本に「ありがとう」という意味だと書いてあります。タイ語では「コップンカー」と言います。", "Trong quyển sách này có viết rằng từ này có nghĩa là 'cảm ơn'. Trong tiếng Thái người ta nói là 'khop khun kha'."]], "n": "と trước 書いてあります/言います là trợ từ trích dẫn.", "lesson": 33}, {"p": "[Câu thường] + と 言っていました", "s": "[Câu thường] と 言っていました", "m": "Thuật lại lời người khác đã nói. Trước と dùng thể thường (普通形).", "ex": [["田中さんは明日来ると言っていました。", "Anh Tanaka đã nói là ngày mai sẽ đến."], ["彼は忙しいと言っていました。", "Anh ấy nói là bận."], ["山田さんは来週大阪へ行くと言っていました。仕事で行くそうです。", "Anh Yamada đã nói là tuần sau sẽ đi Osaka. Nghe nói anh ấy đi vì công việc."], ["先生は明日テストがあると言っていました。よく復習してください。", "Thầy đã nói là ngày mai có bài kiểm tra. Các em hãy ôn tập kỹ nhé."]], "n": "言っていました khác 言いました: nhấn việc người đó đã nói (và người nghe nên biết).", "lesson": 33}, {"p": "V-たり、V-たり します", "s": "V1-たり、V2-たり します", "m": "Liệt kê một vài hành động tiêu biểu trong số nhiều hành động; thì của câu nằm ở します cuối câu.", "ex": [["休みの日は掃除をしたり、買い物をしたりします。", "Ngày nghỉ tôi khi thì dọn dẹp, khi thì đi mua sắm."], ["本を読んだり、音楽を聞いたりします。", "Tôi khi đọc sách, khi nghe nhạc."], ["日曜日は掃除をしたり、洗濯をしたりします。忙しい一日です。", "Chủ nhật tôi khi thì dọn dẹp, khi thì giặt giũ. Đó là một ngày bận rộn."], ["夏休みは海へ行ったり、山へ行ったりします。とても楽しみです。", "Nghỉ hè tôi khi thì đi biển, khi thì đi núi. Tôi rất mong chờ."]], "n": "たり có thể lặp lại cho tính từ và danh từ: 安かったり、高かったり.", "lesson": 34}, {"p": "V-た ことが あります", "s": "V-た + ことがあります", "m": "Diễn tả kinh nghiệm đã từng làm gì trong quá khứ. Khác quá khứ thông thường ở sắc thái “đã từng (ít nhất một lần)”.", "ex": [["富士山に登ったことがあります。", "Tôi đã từng leo núi Phú Sĩ."], ["納豆を食べたことがありますか。", "Bạn đã từng ăn natto chưa?"], ["私は京都へ行ったことがあります。とてもきれいな町でした。", "Tôi đã từng đi Kyoto. Đó là một thành phố rất đẹp."], ["彼はすしを食べたことがあります。おいしかったと言っていました。", "Anh ấy đã từng ăn sushi. Anh ấy nói là rất ngon."]], "n": "Chưa từng: V-たことがありません.", "lesson": 34}, {"p": "N や N", "s": "N1 や N2 (など)", "m": "Liệt kê một phần, hàm ý “và những thứ tương tự nữa”. Khác と (liệt kê toàn bộ).", "ex": [["テーブルに本やノートがあります。", "Trên bàn có sách, vở (và các thứ khác)."], ["果物や野菜を買いました。", "Tôi mua trái cây, rau củ (chẳng hạn)."], ["机の上にペンやノートがあります。勉強の道具がそろっています。", "Trên bàn có bút, vở (và các thứ khác). Đồ dùng học tập đã đầy đủ."], ["スーパーでパンや牛乳を買いました。明日の朝ご飯のためです。", "Tôi đã mua bánh mì, sữa (chẳng hạn) ở siêu thị. Để dành cho bữa sáng ngày mai."]], "n": "や chỉ nối danh từ; thứ tự や không mang nghĩa thứ tự.", "lesson": 34}, {"p": "Thể điều kiện ば (条件形)", "s": "V-ば / A-ければ / Aな・N なら", "m": "Điều kiện giả định “nếu… thì…”. Động từ: -u → -e + ば; tính từ -い → ければ; tính từ -な/N → なら? (điều kiện danh từ dùng なら — xem mẫu riêng); phủ định: V-なければ.", "ex": [["安ければ、買います。", "Nếu rẻ thì tôi mua."], ["雨が降れば、試合は中止です。", "Nếu trời mưa thì trận đấu bị hoãn."], ["時間があれば、静かな公園で本を読みます。とても気持ちがいいです。", "Nếu có thời gian, tôi sẽ đọc sách ở công viên yên tĩnh. Cảm giác rất dễ chịu."], ["お金があれば、有名なレストランへ行きます。友達と一緒に食事をします。", "Nếu có tiền, tôi sẽ đi nhà hàng nổi tiếng. Tôi sẽ ăn cùng bạn bè."]], "n": "Vế sau ば không dùng thể ý chí/mệnh lệnh trực tiếp trong văn chuẩn (hạn chế).", "lesson": 35}, {"p": "V-ても / A-くても / でも", "s": "V-て も / A-い→くて も / Aな・N + でも", "m": "“Dù … thì vẫn …” — kết quả không đổi bất kể điều kiện. V-ても、A-くても、Aなでも、Nでも.", "ex": [["雨が降っても、サッカーをします。", "Dù trời mưa tôi vẫn chơi bóng đá."], ["高くても、買いたいです。", "Dù đắt tôi vẫn muốn mua."], ["寒くても、毎朝ジョギングをします。体が丈夫になります。", "Dù lạnh, tôi vẫn chạy bộ mỗi sáng. Cơ thể sẽ trở nên khỏe mạnh."], ["忙しくても、毎日日本語を勉強します。試験に合格したいです。", "Dù bận, tôi vẫn học tiếng Nhật mỗi ngày. Tôi muốn đỗ kỳ thi."]], "n": "ても dùng cả cho điều kiện có thật và giả định trái thực tế.", "lesson": 35}, {"p": "N / V-る + なら", "s": "N + なら / [Câu thường] + なら", "m": "なら đặt điều kiện theo chủ đề người nghe vừa nêu: “nếu nói về…/nếu là… thì…”, thường kèm gợi ý/khuyên.", "ex": [["週末なら、時間があります。", "Nếu là cuối tuần thì tôi có thời gian."], ["日本へ行くなら、秋がいいです。", "Nếu đi Nhật thì mùa thu là đẹp nhất."], ["電車で行くなら、9時の電車がいいです。早く着きますから。", "Nếu đi bằng tàu điện thì chuyến 9 giờ là tốt nhất. Vì sẽ đến sớm."], ["日本語を勉強するなら、毎日少しずつ勉強するのがいいです。続けやすいですよ。", "Nếu học tiếng Nhật thì nên học một chút mỗi ngày. Như vậy dễ duy trì hơn."]], "n": "なら khác ば ở chỗ không dùng cho điều kiện tự nhiên/quy luật.", "lesson": 35}, {"p": "V-る/ない + ように、〜", "s": "V + ように、[mệnh đề chính]", "m": "Mục đích “để (cho) …” với động từ khả năng/phủ định/tự động từ ở vế ように.", "ex": [["忘れないように、メモします。", "Tôi ghi chú lại để không quên."], ["聞こえるように、大きい声で話してください。", "Hãy nói to để mọi người nghe được."], ["忘れないように、ノートにメモをします。あとで見直すこともできます。", "Để không quên, tôi ghi chú vào sổ. Sau này còn có thể xem lại."], ["遅れないように、早く家を出ます。電車が混んでいるかもしれませんから。", "Để không bị muộn, tôi ra khỏi nhà sớm. Vì tàu có thể sẽ đông."]], "n": "Nếu vế trước là động từ ý chí có chủ đích thì dùng ために (Bài 42).", "lesson": 36}, {"p": "V-る + ように なります", "s": "V + ように なります", "m": "Thay đổi trạng thái: từ không thể → có thể, từ chưa → đã.", "ex": [["自転車に乗れるようになりました。", "Tôi đã biết đi xe đạp (trước đây chưa biết)."], ["日本語が話せるようになりました。", "Tôi đã nói được tiếng Nhật."], ["練習すれば、泳げるようになります。毎日頑張っています。", "Nếu luyện tập, tôi sẽ biết bơi. Ngày nào tôi cũng cố gắng."], ["毎日練習して、漢字が書けるようになりました。まだ難しい漢字もありますが。", "Nhờ luyện tập mỗi ngày, tôi đã viết được chữ Hán. Tuy vẫn còn những chữ khó."]], "n": "ようになります nhấn quá trình thay đổi tự nhiên theo thời gian.", "lesson": 36}, {"p": "V-る/ない + ように します", "s": "V + ように します", "m": "Chủ động nỗ lực duy trì một thói quen tốt.", "ex": [["毎日運動するようにしています。", "Tôi cố gắng vận động mỗi ngày."], ["野菜を食べるようにしています。", "Tôi chú ý ăn rau (tạo thói quen)."], ["健康のために、毎朝野菜を食べるようにしています。体調がよくなりました。", "Vì sức khỏe, tôi chú ý ăn rau mỗi sáng. Sức khỏe đã tốt lên."], ["忘れ物をしないように、前の日に準備するようにします。毎晩チェックしています。", "Để không quên đồ, tôi chuẩn bị từ hôm trước. Tối nào tôi cũng kiểm tra."]], "n": "ようにしています ≠ ように なります (nỗ lực chủ quan vs thay đổi tự nhiên).", "lesson": 36}, {"p": "Động từ thể bị động (受身形)", "s": "N(chủ thể) は N(tác nhân) に V-bị động", "m": "Thể bị động: nhóm 1 -u → -a + れる; nhóm 2 る → られる; する→される、来る→来られる. Người thực hiện hành động đi với に.", "ex": [["先生に褒められました。", "Tôi được thầy khen."], ["泥棒に財布を盗まれました。", "Tôi bị kẻ trộm lấy mất ví."], ["母に叱られました。宿題をしなかったからです。反省しています。", "Tôi bị mẹ mắng. Vì tôi đã không làm bài tập. Tôi đang tự kiểm điểm."], ["弟にケーキを食べられました。私の分がなくなってしまいました。", "Tôi bị em trai ăn mất bánh. Phần của tôi đã hết mất rồi."]], "n": "Nhật dùng bị động cả khi không có sắc thái xấu (được khen, được mời).", "lesson": 37}, {"p": "Bị động gián tiếp (chịu ảnh hưởng)", "s": "N は N に N を V-bị động", "m": "Bị động gián tiếp: người nói bị ảnh hưởng (thường là thiệt thòi) bởi hành động của người khác, dù không phải đối tượng trực tiếp.", "ex": [["会議で社長に紹介されました。", "Tôi được giám đốc giới thiệu trong cuộc họp."], ["友達にパソコンを壊されました。", "Tôi bị bạn làm hỏng máy tính."], ["会議で部長に名前を呼ばれました。びっくりしましたが、うれしかったです。", "Trong cuộc họp, tôi được trưởng phòng gọi tên. Tôi đã bất ngờ nhưng rất vui."], ["妹に部屋のカギをなくされました。とても困りました。", "Tôi bị em gái làm mất chìa khóa phòng. Tôi rất lúng túng."]], "n": "Mẫu này còn gọi là 迷惑の受身 (bị động chịu phiền).", "lesson": 37}, {"p": "Bị động với hiện tượng tự nhiên", "s": "N は N( hiện tượng) に V-bị động", "m": "Hiện tượng tự nhiên hoặc hành động không có chủ đích cũng có thể là “tác nhân” gây phiền cho người nói.", "ex": [["雨に降られて、困りました。", "Tôi bị mưa làm ướt, khổ quá."], ["子どもに泣かれて、寝られませんでした。", "Bị con khóc, tôi không ngủ được."], ["雪に降られて、電車が止まってしまいました。会社へ行けませんでした。", "Tôi bị tuyết rơi làm ướt, tàu đã dừng. Tôi đã không thể đến công ty."], ["大雨に降られて、靴がびしょびしょになりました。家に帰ってすぐお風呂に入りました。", "Tôi bị mưa lớn làm ướt, giày ướt sũng. Về đến nhà tôi đã tắm ngay."]], "n": "降られる・死なれる là tự động từ nhưng vẫn chia bị động theo cách này.", "lesson": 37}, {"p": "Động từ thể sai khiến (使役形)", "s": "N(tác nhân) は N(bị sai khiến) を/に V-sai khiến", "m": "Thể sai khiến: nhóm 1 -u → -a + せる; nhóm 2 る → させる; する→させる、来る→来させる. Nghĩa: bắt làm hoặc cho phép làm.", "ex": [["部長は部下を出張させます。", "Trưởng phòng cho cấp dưới đi công tác."], ["子どもに野菜を食べさせます。", "Tôi cho con ăn rau (bắt ăn)."], ["母は私に部屋を掃除させます。毎週土曜日の朝です。", "Mẹ bắt tôi dọn phòng. Vào sáng thứ Bảy hàng tuần."], ["父は私に車を洗わせました。週末の仕事です。", "Bố đã bắt tôi rửa xe. Đó là việc vào cuối tuần."]], "n": "Tự động từ sai khiến: người bị sai khiến đi với を; tha động từ: người bị sai khiến đi với に.", "lesson": 38}, {"p": "V-させて ください", "s": "V-sai khiến-て + ください", "m": "Xin phép lịch sự: “xin hãy cho tôi làm…”.", "ex": [["私に説明させてください。", "Xin hãy cho tôi giải thích."], ["ここで写真を撮らせてください。", "Cho tôi chụp ảnh ở đây nhé."], ["私に手伝わせてください。力仕事は得意です。", "Xin hãy cho tôi giúp. Tôi giỏi việc nặng."], ["ちょっと休ませてください。疲れてしまいました。", "Cho tôi nghỉ một lát nhé. Tôi mệt rồi."]], "n": "させてください khác てください: thêm nghĩa xin phép cho bản thân làm.", "lesson": 38}, {"p": "Thể sai khiến bị động (使役受身)", "s": "V-sai khiến + れる/られる (〜される)", "m": "Thể sai khiến bị động rút gọn: nhóm 1 -a + される (nói/viết tắt của させられる）, diễn tả bị ép làm điều không muốn.", "ex": [["写真をコピーさせられました。", "Tôi bị bắt photo tài liệu."], ["弟は毎日勉強させられています。", "Em trai tôi ngày nào cũng bị bắt học."], ["私は毎日母に買い物へ行かされるのが嫌です。重い荷物を持つのは大変です。", "Tôi ghét việc ngày nào cũng bị mẹ bắt đi mua sắm. Mang đồ nặng rất vất vả."], ["子どもは毎日野菜を食べさせられるのが嫌です。いつも残してしまいます。", "Đứa trẻ ghét việc ngày nào cũng bị bắt ăn rau. Lúc nào cũng bỏ thừa."]], "n": "行く→行かされる, 買う→買わされる; nhóm 2 giữ dạng させられる.", "lesson": 38}, {"p": "V-て / V-なくて (nguyên nhân)", "s": "V-て/なくて、[kết quả]", "m": "て形 ở đầu câu có thể chỉ nguyên nhân/lý do cho cảm xúc hoặc sự việc ở vế sau.", "ex": [["遅れて、すみません。", "Xin lỗi vì tôi đến muộn."], ["ニュースを聞いて、びっくりしました。", "Nghe tin đó, tôi rất bất ngờ."], ["雨が降らなくて、運動会ができました。子どもたちはとても喜んでいました。", "Nhờ trời không mưa mà hội thao đã tổ chức được. Bọn trẻ rất vui."], ["電車が遅れなくて、約束の時間に着きました。ほっとしました。", "Nhờ tàu không bị trễ mà tôi đã đến đúng giờ hẹn. Tôi đã thở phào nhẹ nhõm."]], "n": "Nguyên nhân bằng て形 không dùng khi vế sau là mệnh lệnh/yêu cầu.", "lesson": 39}, {"p": "N + で (nguyên nhân)", "s": "N(sự cố) で、[kết quả]", "m": "で sau danh từ sự cố/thiên tai chỉ nguyên nhân khách quan.", "ex": [["事故で電車が止まりました。", "Vì tai nạn nên tàu dừng."], ["地震でビルが倒れました。", "Tòa nhà đổ vì động đất."], ["台風で電車が止まりました。会社へ行けませんでした。", "Vì bão nên tàu đã dừng. Tôi đã không thể đến công ty."], ["大雪で学校が休みになりました。家で勉強をしていました。", "Vì tuyết lớn nên trường đã nghỉ học. Tôi đã học ở nhà."]], "n": "Khác で chỉ phương tiện/địa điểm — phân biệt bằng loại danh từ (sự việc).", "lesson": 39}, {"p": "〜途中で", "s": "N の途中で / V-る 途中で", "m": "“Đang trong quá trình… thì…” — một việc xen vào giữa hành động đang diễn ra.", "ex": [["途中で友達に会いました。", "Giữa đường tôi gặp bạn."], ["会議の途中で電話が鳴りました。", "Đang họp thì điện thoại reo."], ["帰る途中で、友達に会いました。少し話をしてから帰りました。", "Trên đường về tôi đã gặp bạn. Tôi nói chuyện một lát rồi mới về."], ["映画を見る途中で、電話がかかってきました。あとでかけ直しました。", "Đang xem phim thì có điện thoại gọi đến. Tôi đã gọi lại sau."]], "n": "途中 đọc là とちゅう; với động từ: V-る途中で.", "lesson": 39}, {"p": "[Câu thường] か / かどうか", "s": "[Câu thường] か(どうか)、〜", "m": "Lồng câu hỏi vào trong câu: có thật hay không dùng かどうか; có nội dung dùng か.", "ex": [["彼は来るかどうか、分かりません。", "Tôi không biết anh ấy có đến hay không."], ["この料理に砂糖が入っているか、教えてください。", "Hãy cho tôi biết món này có đường không."], ["この薬を飲んでもいいかどうか、医者に聞いてください。勝手に飲むのは危ないです。", "Hãy hỏi bác sĩ xem có được uống thuốc này không. Tự ý uống thì nguy hiểm đấy."], ["明日雨が降るかどうか、分かりません。天気予報を見てください。", "Tôi không biết ngày mai trời có mưa không. Hãy xem dự báo thời tiết nhé."]], "n": "Trước か/かどうか luôn dùng thể thường.", "lesson": 40}, {"p": "V-て みます", "s": "V-て みます / みてください", "m": "“Làm thử xem sao” — thử một hành động để biết kết quả/cảm giác.", "ex": [["新しい靴を履いてみます。", "Tôi đi thử đôi giày mới."], ["この料理を食べてみてください。", "Bạn ăn thử món này đi."], ["この新しい店へ行ってみます。友達がおいしいと言っていました。", "Tôi sẽ thử đến quán mới này. Bạn tôi nói là ngon lắm."], ["このシャツを着てみてください。サイズが合うかどうか分かりますよ。", "Bạn hãy mặc thử chiếc áo này đi. Sẽ biết có vừa cỡ không."]], "n": "てみます lịch sự hơn khi đề nghị người khác: 〜てみてください.", "lesson": 40}, {"p": "Từ nghi vấn + でも", "s": "誰/何/いつ/どこ + でも + khẳng định", "m": "Từ nghi vấn + でも + khẳng định = “bất cứ… cũng”: 誰でも、何でも、どこでも、いつでも.", "ex": [["誰でも参加できます。", "Ai cũng có thể tham gia."], ["いつでもいいです。", "Lúc nào cũng được."], ["この店はいつでも開いています。夜遅くまで買い物ができます。", "Cửa hàng này lúc nào cũng mở cửa. Có thể mua sắm đến khuya."], ["この図書館では、どこでも本を読むことができます。静かにしてくださいね。", "Ở thư viện này, chỗ nào cũng có thể đọc sách được. Nhớ giữ yên lặng nhé."]], "n": "Không nhầm với でも ở đầu câu nghĩa “nhưng”.", "lesson": 40}, {"p": "V-て あげます", "s": "N(người nhận) に V-て あげます", "m": "Người nói làm việc gì đó vì lợi ích của người khác. Lịch sự hơn trong giao tiếp thường là tránh dùng thẳng với người trên.", "ex": [["友達に本を貸してあげました。", "Tôi cho bạn mượn sách (làm giúp bạn)."], ["弟に自転車を直してあげました。", "Tôi sửa xe đạp giúp em trai."], ["友達に日本語を教えてあげます。彼はとても喜んでいます。", "Tôi dạy tiếng Nhật cho bạn. Anh ấy rất vui."], ["妹に新しいかばんを買ってあげます。誕生日のプレゼントです。", "Tôi sẽ mua cặp mới cho em gái. Đó là quà sinh nhật."]], "n": "Với người trên, dùng さしあげます hoặc tránh mẫu này để khỏi mang sắc thái ban ơn.", "lesson": 41}, {"p": "V-て もらいます", "s": "N(người làm giúp) に V-て もらいます", "m": "Người nói nhận được việc làm từ người khác, mang sắc thái nhờ vả/biết ơn. Người làm giúp đi với に.", "ex": [["先生に作文を直してもらいました。", "Tôi nhờ thầy sửa bài văn (và được thầy sửa cho)."], ["友達に写真を撮ってもらいました。", "Tôi nhờ bạn chụp ảnh giúp."], ["母に新しい服を買ってもらいます。とても楽しみです。", "Tôi sẽ nhờ mẹ mua quần áo mới cho. Tôi rất mong chờ."], ["先輩に駅まで送ってもらいます。雨の日は助かります。", "Tôi sẽ nhờ anh khóa trên đưa đến ga. Những ngày mưa thì thật là may."]], "n": "Lịch sự: ていただきました.", "lesson": 41}, {"p": "V-て くれます", "s": "N(người làm) が V-て くれます", "m": "Người khác chủ động làm việc có lợi cho người nói (hoặc người thân của người nói).", "ex": [["母が駅まで迎えに来てくれました。", "Mẹ đã đến đón tôi ở ga."], ["友達が引越しを手伝ってくれました。", "Bạn đã giúp tôi chuyển nhà."], ["友達が宿題を手伝ってくれます。いつも助かっています。", "Bạn giúp tôi làm bài tập. Lúc nào tôi cũng được giúp đỡ."], ["先生が分からないところを教えてくれます。テストの前によく聞きに行きます。", "Thầy chỉ cho tôi chỗ không hiểu. Trước kỳ thi tôi hay đến hỏi thầy."]], "n": "Câu hỏi てくれますか là cách nhờ vả thân mật.", "lesson": 41}, {"p": "V-て ほしいです", "s": "N に V-て/ないで ほしいです", "m": "Mong muốn người khác làm gì đó cho mình / theo ý mình.", "ex": [["あなたにこれを食べてほしいです。", "Tôi muốn bạn ăn cái này."], ["早く元気になってほしいです。", "Tôi mong bạn sớm khỏe lại."], ["子どもたちに元気に育ってほしいです。毎日ご飯をしっかり食べさせています。", "Tôi mong các con lớn lên khỏe mạnh. Ngày nào tôi cũng cho con ăn uống đầy đủ."], ["あなたに早く日本語が上手になってほしいです。いっしょに勉強しましょう。", "Tôi mong bạn sớm giỏi tiếng Nhật. Chúng ta cùng học nhé."]], "n": "Người được mong muốn đi với に; không dùng để ra lệnh với người trên.", "lesson": 41}, {"p": "V-る + ために、〜", "s": "V-る + ために、[hành động]", "m": "Mục đích có chủ đích rõ ràng: “để…”. Vế trước ために phải là động từ ý chí.", "ex": [["日本で働くために、日本語を勉強しています。", "Để làm việc ở Nhật, tôi đang học tiếng Nhật."], ["家を買うために、貯金しています。", "Để mua nhà, tôi đang tiết kiệm tiền."], ["日本語を勉強するために、毎日単語を覚えています。来年試験を受けます。", "Để học tiếng Nhật, ngày nào tôi cũng học thuộc từ vựng. Sang năm tôi sẽ thi."], ["大学に入るために、一生懸命勉強しています。毎日遅くまで勉強しています。", "Để vào đại học, tôi đang học rất chăm chỉ. Ngày nào tôi cũng học đến khuya."]], "n": "Phân biệt ように (Bài 36) dùng khi vế mục đích là khả năng/phủ định/không chủ đích.", "lesson": 42}, {"p": "N + の ために", "s": "N のために、〜", "m": "“Vì (lợi ích của)…” — người/vật được hưởng lợi đi trước のために.", "ex": [["家族のために働いています。", "Tôi làm việc vì gia đình."], ["健康のために、運動します。", "Vì sức khỏe, tôi tập thể dục."], ["子どものために、毎日早く起きてお弁当を作っています。栄養のバランスも考えています。", "Vì con, ngày nào tôi cũng dậy sớm làm cơm hộp. Tôi cũng chú ý đến cân bằng dinh dưỡng."], ["健康のために、野菜をたくさん食べるようにしています。お酒もあまり飲みません。", "Vì sức khỏe, tôi chú ý ăn nhiều rau. Tôi cũng ít uống rượu."]], "n": "ために ở đây khác ために chỉ mục đích ở chỗ danh từ chỉ người/sự trừu tượng.", "lesson": 42}, {"p": "Lượng từ + に (theo đơn vị)", "s": "[khoảng] に [số lần/số tiền]", "m": "に sau lượng từ chỉ tần suất/giá theo một đơn vị: 1 ngày 2 lần、1 người 1000 yên…", "ex": [["一週間に二回、映画を見ます。", "Một tuần tôi xem phim hai lần."], ["部屋代は一か月に六万円かかります。", "Tiền phòng là 60.000 yên cho một tháng."], ["一週間に三回、プールへ行きます。健康のためです。", "Một tuần tôi đi bơi ba lần. Vì sức khỏe."], ["一か月に二万円、貯金しています。来年旅行に行くためです。", "Một tháng tôi tiết kiệm 20.000 yên. Để sang năm đi du lịch."]], "n": "Không dùng に khi chỉ nói số lượng đơn thuần không gắn đơn vị thời gian/giá.", "lesson": 42}, {"p": "〜そうです (vẻ bề ngoài)", "s": "V-ます + そうです / A + そうです", "m": "Nhận xét qua vẻ bề ngoài: “trông có vẻ…”. Động từ: V-ます + そうです; tính từ い bỏ い + そうです; tính từ な + そうです.", "ex": [["このケーキはおいしそうです。", "Bánh này trông ngon quá."], ["雨が降りそうです。", "Trời có vẻ sắp mưa."], ["このりんごは甘そうです。食べてみましょう。", "Quả táo này trông có vẻ ngọt. Chúng ta ăn thử nhé."], ["彼は眠そうです。早く寝たほうがいいです。", "Trông anh ấy có vẻ buồn ngủ. Nên đi ngủ sớm thì tốt hơn."]], "n": "いい → よさそうです (dạng đặc biệt). Khác そうです truyền văn (Bài 47).", "lesson": 43}, {"p": "V-て きます (đi rồi quay lại)", "s": "V-て きます", "m": "Đi làm việc gì đó rồi quay lại chỗ hiện tại — mẫu chào quen thuộc: 行ってきます.", "ex": [["ちょっと買い物に行ってきます。", "Tôi đi mua đồ một lát rồi về."], ["タクシーを呼んできます。", "Tôi đi gọi taxi rồi quay lại ngay."], ["ちょっとコンビニへ行ってきます。牛乳を買ってきます。", "Tôi đi cửa hàng tiện lợi một lát rồi về. Tôi sẽ mua sữa về."], ["忘れ物を取りに行ってきます。すぐ戻ります。", "Tôi đi lấy đồ bỏ quên rồi về ngay. Tôi sẽ quay lại ngay."]], "n": "てくる mang hướng về phía người nói/nơi xuất phát.", "lesson": 43}, {"p": "V-て きました (thay đổi đang tới)", "s": "V-て きました", "m": "Một thay đổi bắt đầu xuất hiện và đang tiếp diễn đến hiện tại.", "ex": [["だんだん寒くなってきました。", "Trời bắt đầu lạnh dần."], ["日本語が少し分かるようになってきました。", "Tôi bắt đầu hiểu được tiếng Nhật một chút."], ["最近、暖かくなってきました。桜が咲きそうです。", "Gần đây trời bắt đầu ấm dần. Hoa anh đào sắp nở rồi."], ["子どもがだんだん大きくなってきました。もうすぐ小学生になります。", "Đứa trẻ bắt đầu lớn dần. Sắp vào tiểu học rồi."]], "n": "Đối lại, thay đổi tiếp diễn về tương lai dùng ていきます.", "lesson": 43}, {"p": "〜すぎます", "s": "V-ます + すぎます / A + すぎます", "m": "Quá mức cần thiết: V-ます + すぎます; A-い/な bỏ đuôi + すぎます.", "ex": [["食べすぎました。", "Tôi ăn nhiều quá."], ["この本は難しすぎます。", "Quyển sách này khó quá mức."], ["この料理は辛すぎます。あまり食べられません。", "Món này cay quá. Tôi không ăn được nhiều."], ["この問題は難しすぎます。先生に聞いてみましょう。", "Bài này khó quá mức. Chúng ta hỏi thầy nhé."]], "n": "すぎる cũng đứng độc lập làm động từ nhóm 2.", "lesson": 44}, {"p": "V-ます + やすい / にくい", "s": "V-ます + やすい / にくい", "m": "V-ます + やすい (dễ làm) / にくい (khó làm) — đánh giá về độ dễ thực hiện hành động.", "ex": [["この薬は飲みにくいです。", "Thuốc này khó uống."], ["このペンは書きやすいです。", "Cây bút này dễ viết."], ["この本は読みやすいです。字が大きくて、絵も多いです。", "Quyển sách này dễ đọc. Chữ to và có nhiều hình."], ["この道は歩きにくいです。石がたくさんあって、危ないです。", "Con đường này khó đi. Có nhiều đá, nguy hiểm lắm."]], "n": "やすい/にくい chia như tính từ -い.", "lesson": 44}, {"p": "A-く / A-に + します", "s": "Aい→く + します / Aな→に + します", "m": "Chủ động làm cho trạng thái thay đổi: tính từ い → く + します; tính từな → に + します.", "ex": [["音を大きくしてください。", "Hãy vặn âm thanh to lên."], ["部屋をきれいにしました。", "Tôi dọn phòng sạch sẽ (làm cho sạch)."], ["声を大きくします。後ろの人にも聞こえるようにします。", "Tôi sẽ nói to lên. Để người ngồi sau cũng nghe được."], ["荷物を軽くします。重いものは別の箱に入れます。", "Tôi sẽ làm cho hành lý nhẹ đi. Đồ nặng tôi sẽ cho vào thùng khác."]], "n": "Khác なります (thay đổi tự nhiên): します = có tác nhân.", "lesson": 44}, {"p": "〜場合は", "s": "[Câu thường] 場合は、〜", "m": "“Trong trường hợp…” — dùng trong hướng dẫn, tình huống giả định trang trọng. 場合 đọc là ばあい.", "ex": [["遅れる場合は、電話してください。", "Nếu (trường hợp) đến muộn, hãy gọi điện."], ["火事の場合は、このボタンを押してください。", "Trường hợp có cháy, hãy bấm nút này."], ["雨の場合は、試合は中止です。来週に延期になります。", "Trong trường hợp trời mưa, trận đấu sẽ bị hủy. Sẽ dời sang tuần sau."], ["熱がある場合は、学校を休んでください。無理をしないでください。", "Trường hợp bị sốt, hãy nghỉ học. Đừng cố gắng quá sức."]], "n": "場合は thường đi với chỉ thị/hướng dẫn phía sau.", "lesson": 45}, {"p": "〜のに", "s": "[Câu thường] のに、[kết quả ngoài ý muốn]", "m": "“Vậy mà / mặc dù…” — kết quả trái với kỳ vọng, mang sắc thái tiếc nuối/trách móc nhẹ.", "ex": [["約束したのに、彼は来ませんでした。", "Đã hứa vậy mà anh ấy không đến."], ["一生懸命勉強したのに、落ちました。", "Học chăm chỉ thế mà vẫn trượt."], ["たくさん勉強したのに、試験に合格できませんでした。とても残念でした。", "Đã học rất nhiều vậy mà vẫn không đỗ kỳ thi. Tôi rất tiếc."], ["早く起きたのに、電車に乗り遅れました。とても急いでいました。", "Đã dậy sớm vậy mà vẫn lỡ tàu. Tôi đã rất vội."]], "n": "Trước のに dùng thể thường; danh từ/tính từな nối bằng な: 静かなのに.", "lesson": 45}, {"p": "V + ところです (3 giai đoạn)", "s": "V-る/ている/た + ところです", "m": "ところ đánh dấu giai đoạn của hành động: V-る ところ = sắp làm; V-て いる ところ = đang làm dở; V-た ところ = vừa làm xong.", "ex": [["今、出かけるところです。", "Tôi sắp ra ngoài đây."], ["今、食べているところです。", "Tôi đang ăn dở."], ["今、着いたところです。", "Tôi vừa mới đến nơi."], ["今、ご飯を作っているところです。もう少し待ってください。", "Tôi đang nấu cơm dở. Hãy đợi thêm một chút."], ["今、家を出るところです。5分後に駅に着きます。", "Tôi sắp ra khỏi nhà đây. 5 phút nữa sẽ đến ga."]], "n": "ところ ở đây mang nghĩa trừu tượng (thời điểm/giai đoạn), không phải địa điểm.", "lesson": 46}, {"p": "〜た ばかりです / 〜て ばかり", "s": "V-た + ばかりです / V-て + ばかりいます", "m": "Hai nghĩa: (1) vừa mới làm xong (V-た ばかり） — cảm giác chủ quan của người nói; (2) chỉ toàn làm một việc (V-て ばかり).", "ex": [["さっき昼ご飯を食べたばかりです。", "Tôi vừa mới ăn trưa xong."], ["彼は遊んでばかりいます。", "Anh ta chỉ toàn chơi thôi."], ["今、日本へ来たばかりです。まだ日本語がよく分かりません。", "Tôi vừa mới đến Nhật. Tôi vẫn chưa hiểu rõ tiếng Nhật."], ["彼女は携帯を見てばかりいます。ご飯の時も見ています。", "Cô ấy chỉ toàn xem điện thoại. Ngay cả lúc ăn cơm cũng xem."]], "n": "たばかり khác たところ: ところ khách quan về thời gian, ばかり nhấn cảm nhận “mới đây thôi”.", "lesson": 46}, {"p": "〜はずです", "s": "[Câu thường] + はずです", "m": "Tin chắc dựa trên cơ sở/lịch trình: “nhất định là / theo đúng thì…”. Phủ định: はずがありません.", "ex": [["電車は九時に着くはずです。", "Tàu chắc chắn 9 giờ sẽ đến."], ["彼は約束を守るはずです。", "Anh ấy nhất định sẽ giữ lời hứa."], ["彼は今日来るはずです。昨日電話で約束しましたから。", "Chắc chắn hôm nay anh ấy sẽ đến. Vì hôm qua đã hẹn qua điện thoại rồi."], ["この店は9時に開くはずです。もうすぐ開きますよ。", "Cửa hàng này theo đúng thì 9 giờ sẽ mở. Sắp mở rồi đấy."]], "n": "はずです khác でしょう: はず có căn cứ rõ ràng hơn.", "lesson": 46}, {"p": "〜そうです (truyền văn)", "s": "[Câu thường] + そうです", "m": "Truyền đạt thông tin nghe được từ nguồn khác: “nghe nói là…”. Trước そうです dùng thể thường nguyên dạng.", "ex": [["天気予報によると、明日は雨だそうです。", "Theo dự báo thời tiết, ngày mai trời mưa."], ["彼は来年結婚するそうです。", "Nghe nói sang năm anh ấy kết hôn."], ["天気予報によると、明日は晴れるそうです。洗濯をするといいですよ。", "Theo dự báo thời tiết, nghe nói ngày mai trời nắng. Nên giặt đồ đấy."], ["山田さんは来月結婚するそうです。みんなでお祝いしましょう。", "Nghe nói tháng sau anh Yamada sẽ kết hôn. Chúng ta cùng chúc mừng nhé."]], "n": "Khác そうです vẻ bề ngoài (Bài 43): truyền văn dùng [câu thường] + そうです, vẻ bề ngoài dùng V-ます/A + そうです.", "lesson": 47}, {"p": "〜ようです", "s": "[Câu thường] + ようです (N の / Aな の ようです)", "m": "Suy đoán dựa trên căn cứ cảm nhận được (nhìn, nghe, chạm…): “có vẻ như…”.", "ex": [["熱があるようです。", "Hình như (anh ấy) bị sốt."], ["彼は忙しいようです。", "Trông anh ấy có vẻ bận."], ["彼は疲れているようです。早く休んだほうがいいです。", "Trông anh ấy có vẻ mệt. Nên nghỉ sớm thì tốt hơn."], ["外は寒いようです。コートを着て出かけてください。", "Bên ngoài có vẻ lạnh. Hãy mặc áo khoác rồi ra ngoài nhé."]], "n": "ような + N / ように + V/A để bổ nghĩa: 子どものような人.", "lesson": 47}, {"p": "N + らしいです", "s": "N + らしいです", "m": "“Đúng kiểu / đúng chất …” — danh từ + らしい diễn tả tính chất tiêu biểu. Cũng dùng để suy đoán nhẹ: 彼は来ないらしい.", "ex": [["今日は春らしい天気です。", "Hôm nay thời tiết đúng chất mùa xuân."], ["彼は男らしい人です。", "Anh ấy là người rất đàn ông (đúng chất nam nhi)."], ["今日は秋らしいです。涼しくて、気持ちがいい天気です。", "Hôm nay đúng chất mùa thu. Thời tiết mát mẻ, dễ chịu."], ["彼女はとても女性らしいです。優しくて、きれいです。", "Cô ấy rất nữ tính. Vừa dịu dàng, vừa xinh đẹp."]], "n": "らしい khi làm suy đoán đứng cuối câu sau thể thường.", "lesson": 47}, {"p": "Động từ tôn kính đặc biệt (尊敬語)", "s": "いらっしゃいます / おっしゃいます / なさいます / ご覧になります / 召し上がります", "m": "Động từ tôn kính đặc biệt: いる→いらっしゃる、言う→おっしゃる、する→なさる、見る→ご覧になる、食べる/飲む→召し上がる、来る/行く→いらっしゃる.", "ex": [["先生はもうお帰りになりましたか。— いえ、まだいらっしゃいます。", "Thầy về chưa? — Chưa, thầy vẫn còn ở đây."], ["社長がおっしゃいました。", "Giám đốc đã nói (tôn kính)."], ["先生はもういらっしゃいます。会議室でお待ちになっています。", "Thầy đã đến rồi ạ. Thầy đang đợi ở phòng họp."], ["お客様はコーヒーを召し上がりますか。紅茶もありますよ。", "Quý khách có dùng cà phê không ạ? Chúng tôi cũng có trà."]], "n": "Dùng cho hành động của người trên — tuyệt đối không dùng cho bản thân.", "lesson": 48}, {"p": "お + V-ます + に なります", "s": "お + V-ます + になります", "m": "Công thức tôn kính thông thường khi không có động từ đặc biệt: お + V-ます + になります.", "ex": [["先生はもう本をお読みになりました。", "Thầy đã đọc sách rồi."], ["お客様はお帰りになりました。", "Khách đã về rồi."], ["先生は毎日新聞をお読みになります。朝の習慣だそうです。", "Thầy đọc báo mỗi ngày. Nghe nói đó là thói quen buổi sáng của thầy."], ["社長は来週大阪へお越しになります。会議に出席するそうです。", "Giám đốc sẽ đến Osaka vào tuần sau. Nghe nói ngài sẽ tham dự cuộc họp."]], "n": "Động từ 1 âm tiết （見ます、寝ます) không dùng mẫu này — dùng động từ đặc biệt.", "lesson": 48}, {"p": "お + V-ます + ください", "s": "お + V-ます + ください / ご + N + ください", "m": "Yêu cầu/đề nghị lịch sự nâng cao: お + V-ます + ください, trang trọng hơn 〜てください.", "ex": [["少々お待ちください。", "Xin vui lòng đợi một chút."], ["こちらにお座りください。", "Xin mời ngồi ở đây."], ["こちらでお待ちください。すぐご案内します。", "Xin vui lòng đợi ở đây. Tôi sẽ hướng dẫn ngay."], ["お名前をお書きください。受付でお願いします。", "Xin vui lòng viết tên của quý khách. Xin làm ở quầy lễ tân."]], "n": "ご + N(onyomi) + ください cho danh từ hành động: ご覧ください、ご注意ください.", "lesson": 48}, {"p": "Động từ khiêm nhường đặc biệt (謙譲語)", "s": "申します / おります / まいります / いたします / 存じます / 拝見します / 伺います", "m": "Động từ khiêm nhường đặc biệt: 言う→申す/申し上げる、いる→おる、来る・行く→参る、する→いたす、知っている→存じている、見る→拝見する、聞く/行く（thăm hỏi)→伺う.", "ex": [["私は田中と申します。", "Tôi tên là Tanaka (khiêm nhường)."], ["明日、伺います。", "Ngày mai tôi sẽ đến (thăm) — khiêm nhường."], ["私は佐藤と申します。営業部の者です。", "Tôi tên là Sato (khiêm nhường). Tôi là người của phòng kinh doanh."], ["来週、東京の本社へ伺います。部長にごあいさつします。", "Tuần sau, tôi sẽ đến thăm trụ sở chính ở Tokyo. Tôi sẽ chào hỏi trưởng phòng."]], "n": "Khiêm nhường = hạ thấp bản thân để nâng người nghe lên — đối ngược tôn kính nhưng mục đích giống nhau.", "lesson": 49}, {"p": "お + V-ます + します", "s": "お + V-ます + します", "m": "Công thức khiêm nhường thông thường: お + V-ます + します — hành động của người nói hướng tới người trên.", "ex": [["お荷物をお持ちします。", "Để tôi mang hành lý giúp (khiêm nhường)."], ["後でお電話します。", "Lát nữa tôi sẽ gọi điện (cho quý khách)."], ["お茶をお持ちします。少々お待ちください。", "Để tôi mang trà đến (khiêm nhường). Xin vui lòng đợi một chút."], ["明日の会議の資料をお送りします。メールで送りますので、ご確認ください。", "Tôi sẽ gửi tài liệu họp ngày mai (khiêm nhường). Tôi sẽ gửi qua email, xin quý vị kiểm tra giúp."]], "n": "Chỉ dùng khi hành động liên quan/hướng đến đối phương; không dùng cho việc riêng không liên quan.", "lesson": 49}, {"p": "ご + N + いたします / お聞かせください", "s": "ご + N + いたします", "m": "Các mẫu khiêm nhường trang trọng thường gặp trong dịch vụ/kinh doanh: お聞かせください、ご〜いたします.", "ex": [["ご意見をお聞かせください。", "Xin cho tôi nghe ý kiến của quý vị."], ["ご案内いたします。", "Để tôi hướng dẫn quý vị."], ["後ほどご連絡いたします。お待ちください。", "Lát nữa tôi sẽ liên lạc lại (trang trọng). Xin vui lòng đợi."], ["明日の朝、ご報告いたします。よろしくお願いします。", "Sáng mai tôi sẽ báo cáo lại (trang trọng). Mong được giúp đỡ."]], "n": "ご + N + いたします: ご連絡いたします、ご説明いたします.", "lesson": 49}, {"p": "〜で ございます / ございます", "s": "N でございます / N にございます", "m": "Dạng cực kỳ lịch sự của です → でございます, あります → ございます. Hay nghe trong thông báo, dịch vụ khách hàng.", "ex": [["こちらは受付でございます。", "Đây là quầy lễ tân (cách nói rất lịch sự)."], ["お手洗いは二階にございます。", "Nhà vệ sinh ở tầng hai."], ["こちらは会議室でございます。どうぞお入りください。", "Đây là phòng họp (cách nói rất lịch sự). Xin mời vào."], ["駐車場は建物の裏にございます。こちらから行けます。", "Bãi đỗ xe ở phía sau tòa nhà (rất lịch sự). Có thể đi từ đây."]], "n": "ございます không đổi nghĩa, chỉ tăng mức trang trọng.", "lesson": 50}, {"p": "お目にかかります / 存じております", "s": "お目にかかります / 存じております", "m": "Nhóm khiêm nhường rất trang trọng dùng trong kinh doanh: 会う→お目にかかる、知っている→存じておる、言う→申し上げる.", "ex": [["明日、十時にお目にかかります。", "Ngày mai 10 giờ tôi xin được gặp (ngài)."], ["その件は存じております。", "Việc đó tôi đã biết rồi (khiêm nhường, trang trọng)."], ["来週の月曜日にお目にかかります。楽しみにしています。", "Thứ Hai tuần sau tôi xin được gặp (ngài). Tôi rất mong chờ."], ["田中様のご住所は存じております。すぐお送りします。", "Địa chỉ của ngài Tanaka tôi đã biết rồi (khiêm nhường, trang trọng). Tôi sẽ gửi ngay."]], "n": "存じております = 存じている + おります (cộng hai lớp khiêm nhường).", "lesson": 50}, {"p": "Nguyên tắc chọn kính ngữ", "s": "Người trên → 尊敬語 / Mình → 謙譲語 / Chung → 丁寧語", "m": "Nguyên tắc dùng kính ngữ: hành động của người trên → tôn kính ngữ; hành động của mình hướng tới người trên → khiêm nhường ngữ; sự vật/lời nói trung tính → thể lịch sự です・ます.", "ex": [["部長は明日来られると聞きました。", "Tôi nghe nói ngày mai trưởng phòng sẽ đến (tôn kính)."], ["私がご説明いたします。", "Để tôi xin giải thích (khiêm nhường)."], ["部長は明日お越しになります。私はご案内いたします。会議室でお待ちしております。", "Ngày mai trưởng phòng sẽ đến (tôn kính). Tôi sẽ hướng dẫn (khiêm nhường). Tôi xin đợi ở phòng họp."], ["先生がご覧になりました。私は資料をお持ちしました。後でご説明いたします。", "Thầy đã xem (tôn kính). Tôi đã mang tài liệu đến (khiêm nhường). Lát nữa tôi xin giải thích."]], "n": "Lỗi thường gặp: dùng tôn kính ngữ cho chính mình. Luôn kiểm tra “chủ ngữ là ai” trước khi chọn.", "lesson": 50}], "N3": [{"p": "〜うちに", "s": "V-る / V-ない / A-い / N の + うちに", "m": "Làm việc gì đó trong khoảng thời gian một trạng thái còn duy trì (trước khi nó thay đổi).", "ex": [["元気なうちに、たくさん旅行したいです。", "Trong lúc còn khỏe, tôi muốn đi du lịch nhiều."], ["忘れないうちに、メモしておきます。", "Trong lúc chưa quên, tôi ghi chú lại."]], "n": "うちに nhấn 'tranh thủ trước khi quá muộn', khác あいだに (trong suốt khoảng).", "group": "Thời gian & trình tự"}, {"p": "〜あいだ（に）", "s": "V-て いる + あいだ（に）", "m": "Trong suốt khoảng thời gian một hành động/trạng thái đang diễn ra, một việc khác xảy ra.", "ex": [["寝ているあいだに、雪が降りました。", "Trong lúc tôi ngủ, tuyết đã rơi."], ["留守のあいだに、泥棒が入りました。", "Trong lúc vắng nhà, trộm đã vào."]], "n": "あいだ（suốt khoảng) khác あいだに ở sắc thái: あいだに = tại một thời điểm trong khoảng.", "group": "Thời gian & trình tự"}, {"p": "〜たびに", "s": "V-る / N の + たびに", "m": "Mỗi lần làm X thì luôn xảy ra Y.", "ex": [["日本へ行くたびに、お土産を買います。", "Mỗi lần đi Nhật, tôi đều mua quà."], ["この写真を見るたびに、学生時代を思い出します。", "Mỗi lần xem bức ảnh này, tôi lại nhớ thời sinh viên."]], "n": "たびに đi với động từ nguyên dạng hoặc N のたびに.", "group": "Thời gian & trình tự"}, {"p": "V-た とたん（に）", "s": "V-た + とたん（に）", "m": "Ngay khoảnh khắc vừa làm xong việc trước, việc sau bất ngờ xảy ra.", "ex": [["家に帰ったとたん、雨が降り出しました。", "Vừa về đến nhà thì trời đổ mưa."], ["ドアを開けたとたん、猫が飛び出しました。", "Vừa mở cửa thì con mèo phóng ra."]], "n": "Vế sau とたん không dùng ý chí/dự định của người nói.", "group": "Thời gian & trình tự"}, {"p": "〜最中に", "s": "V-て いる / N の + 最中に", "m": "Ngay giữa lúc đang làm gì đó (có việc khác xen vào). 最中 đọc là さいちゅう.", "ex": [["会議の最中に、電話が鳴りました。", "Đang giữa cuộc họp thì điện thoại reo."], ["話している最中に、彼は寝てしまいました。", "Đang nói chuyện thì anh ta ngủ mất."]], "n": "最中に mang sắc thái việc xen vào gây gián đoạn.", "group": "Thời gian & trình tự"}, {"p": "V-ます + 次第", "s": "V-ます + 次第、〜", "m": "Ngay sau khi việc trước hoàn thành thì làm việc sau ngay — hay dùng trong công việc/thư từ.", "ex": [["届き次第、ご連絡します。", "Ngay khi (hàng) đến nơi, tôi sẽ liên lạc."], ["分かり次第、教えてください。", "Ngay khi biết, hãy cho tôi hay."]], "n": "次第 đứng sau gốc động từ (V-ます).", "group": "Thời gian & trình tự"}, {"p": "V-た まま", "s": "V-た / A-い / N の + まま", "m": "Giữ nguyên trạng thái sau hành động, không thay đổi/hoàn tác.", "ex": [["窓を開けたまま、出かけました。", "Tôi ra ngoài mà vẫn để cửa sổ mở."], ["テレビをつけたまま、寝てしまいました。", "Tôi ngủ quên mà TV vẫn bật."]], "n": "まま còn dùng cho trạng thái giả định: 思ったままを言う (nói đúng như nghĩ).", "group": "Thời gian & trình tự"}, {"p": "〜ついでに", "s": "V-る / N の + ついでに", "m": "Nhân tiện làm việc chính, làm luôn việc phụ trên đường.", "ex": [["駅へ行くついでに、郵便局に寄ります。", "Nhân tiện đi ra ga, tôi ghé bưu điện."], ["買い物のついでに、本屋にも行きました。", "Nhân tiện đi mua sắm, tôi cũng ghé hiệu sách."]], "n": "ついでに không dùng khi việc phụ quan trọng hơn việc chính.", "group": "Thời gian & trình tự"}, {"p": "V-ます + つつある", "s": "V-ます + つつある", "m": "Một sự thay đổi đang diễn tiến dần dần (văn viết/trang trọng của てきています).", "ex": [["日本語が上手になりつつあります。", "Tiếng Nhật của tôi đang dần tiến bộ."], ["景気が回復しつつあります。", "Kinh tế đang dần hồi phục."]], "n": "つつ đứng sau gốc động từ (V-ます), chỉ dùng trong văn viết, tin tức.", "group": "Thời gian & trình tự"}, {"p": "V-る が 早いか", "s": "V-る + が 早いか、〜", "m": "Vừa làm X xong thì Y xảy ra gần như đồng thời — nhấn tốc độ tức thì.", "ex": [["席に着くが早いか、彼は話し始めました。", "Vừa ngồi xuống ghế là anh ta bắt đầu nói ngay."], ["ベルが鳴るが早いか、生徒たちは教室を出ました。", "Chuông vừa reo là học sinh ùa ra khỏi lớp."]], "n": "Mẫu văn viết, ít dùng trong hội thoại thường ngày.", "group": "Thời gian & trình tự"}, {"p": "〜際（に）", "s": "V-る / N の + 際（に）", "m": "“Khi / vào dịp” — cách nói trang trọng của とき, dùng trong hướng dẫn, thông báo.", "ex": [["出発の際に、パスポートを確認してください。", "Khi xuất phát, hãy kiểm tra hộ chiếu."], ["申し込みの際は、この用紙が必要です。", "Khi đăng ký, cần tờ giấy này."]], "n": "際 đọc là さい; V-る際（に）/ N の際（に）.", "group": "Thời gian & trình tự"}, {"p": "V-て 初めて", "s": "V-て + 初めて、〜", "m": "Chỉ sau khi trải qua việc trước mới nhận ra/hiểu được việc sau.", "ex": [["日本で生活して初めて、日本人の優しさが分かりました。", "Chỉ sau khi sống ở Nhật, tôi mới hiểu sự tử tế của người Nhật."], ["自分でやってみて初めて、その大変さが分かりました。", "Chỉ khi tự làm thử, tôi mới hiểu độ vất vả của nó."]], "n": "初めて ở đây là trạng thái 'lần đầu tiên nhận ra', không phải lần đầu làm.", "group": "Thời gian & trình tự"}, {"p": "〜せいで", "s": "[Câu thường] / N の + せいで", "m": "Nguyên nhân gây ra kết quả xấu — mang sắc thái đổ lỗi.", "ex": [["雨のせいで、試合が中止になりました。", "Vì mưa nên trận đấu bị hoãn."], ["寝不足のせいで、頭が痛いです。", "Vì thiếu ngủ nên tôi đau đầu."]], "n": "Đối lại おかげで dùng cho kết quả tốt.", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜おかげで", "s": "[Câu thường] / N の + おかげで", "m": "Nhờ có X mà đạt được kết quả tốt — mang sắc thái biết ơn.", "ex": [["先生のおかげで、合格できました。", "Nhờ thầy mà tôi đỗ được."], ["薬のおかげで、早く治りました。", "Nhờ thuốc mà tôi nhanh khỏi."]], "n": "Dùng mỉa mai khi kết quả xấu: あなたのおかげで失敗した (đều tại anh).", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜ものだから", "s": "[Câu thường] + ものだから", "m": "Nêu lý do để tự bào chữa/giải thích cảm thông — 'vì là… mà'.", "ex": [["彼は若いものだから、失敗しても仕方ありません。", "Vì cậu ấy còn trẻ nên lỡ thất bại cũng đành chịu."], ["初めての国だものだから、緊張しました。", "Vì là lần đầu ra nước ngoài nên tôi hồi hộp."]], "n": "ものだから trang trọng hơn もの nên; hay đứng sau です/だ.", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜ことから", "s": "[Câu thường] + ことから", "m": "Căn cứ/neuồn gốc dẫn đến một sự thật hoặc tên gọi: 'từ việc… mà…'.", "ex": [["形がおもしろいことから、この商品は人気があります。", "Vì hình dáng thú vị nên sản phẩm này được ưa chuộng."], ["声が大きいことから、「スピーカー」というあだ名がつきました。", "Vì giọng to nên bị đặt biệt danh là 'cái loa'."]], "n": "ことから hay dùng khi giải thích nguồn gốc tên gọi, đánh giá.", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜からといって", "s": "[Câu thường] + からといって、〜ない", "m": "Không thể lấy lý do đó ra biện minh: 'dù là… thì cũng không hẳn…'.", "ex": [["忙しいからといって、挨拶をしないのはよくありません。", "Dù bận cũng không nên không chào hỏi."], ["日本人だからといって、みんな寿司が好きなわけではありません。", "Không phải cứ là người Nhật thì ai cũng thích sushi."]], "n": "Vế sau thường phủ định hoặc mang sắc thái phản bác.", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜くせに", "s": "[Câu thường] + くせに (N な / Aな な)", "m": "Giống のに nhưng mạnh sắc thái chê trách: '...vậy mà lại...'.", "ex": [["約束したくせに、彼は来ませんでした。", "Đã hứa vậy mà anh ta không đến (trách móc)."], ["知っているくせに、教えてくれません。", "Biết vậy mà không chịu nói cho tôi."]], "n": "くせに chỉ dùng với sắc thái tiêu cực/phê phán, không dùng cho sự việc trung tính.", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜わりには", "s": "[Câu thường] / N の + わりには", "m": "So với mức kỳ vọng từ vế trước thì vế sau không tương xứng.", "ex": [["このホテルは高いわりには、サービスがよくありません。", "Khách sạn này giá cao vậy mà dịch vụ không tốt."], ["彼は若いわりには、考え方が古いです。", "Anh ta còn trẻ vậy mà suy nghĩ cũ kỹ."]], "n": "わりには nhấn sự không tương xứng, khác のに (chỉ trái kỳ vọng chung).", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜反面", "s": "[Câu thường] / N の + 反面", "m": "Hai mặt đối lập của cùng một sự việc: 'mặt khác / ngược lại'.", "ex": [["田舎は静かな反面、生活が不便です。", "Quê yên tĩnh, mặt khác sống cũng bất tiện."], ["この仕事は給料が高い反面、忙しいです。", "Công việc này lương cao, mặt khác lại bận rộn."]], "n": "反面 đọc はんめん; hai vế phải nói về cùng một chủ thể.", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜一方（で）", "s": "V-る + 一方で / V-る + 一方だ", "m": "(1) Đồng thời làm hai việc; (2) xu hướng một chiều không đổi: V-る一方だ (cứ ngày càng…).", "ex": [["兄は大学で勉強する一方で、アルバイトもしています。", "Anh tôi vừa học đại học, đồng thời cũng làm thêm."], ["この町は人口が増える一方です。", "Dân số thị trấn này cứ tăng mãi một chiều."]], "n": "Phân biệt hai nghĩa bằng dạng theo sau: 一方で (đồng thời) / 一方だ (xu hướng).", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜に対して", "s": "N + に対して", "m": "'Đối với / hướng tới' — đối tượng của thái độ, phản ứng, hoặc sự tương phản.", "ex": [["子どもの意見に対して、大人は反対しました。", "Đối với ý kiến của trẻ em, người lớn phản đối."], ["質問に対して、丁寧に答えました。", "Anh ấy trả lời lịch sự trước câu hỏi (đối đáp)."]], "n": "に対して còn dùng nối hai vế tương phản: 兄に対して、弟は…", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜によって", "s": "N + によって", "m": "によって có nhiều nghĩa theo ngữ cảnh: (1) tác nhân bị động 'bởi', (2) nguyên nhân, (3) phương tiện/căn cứ, (4) 'tùy theo' (人によって違う).", "ex": [["この橋は有名な建築家によって設計されました。", "Cây cầu này được thiết kế bởi kiến trúc sư nổi tiếng."], ["台風によって、電車が止まりました。", "Vì bão nên tàu dừng."]], "n": "人によって違います = tùy người mà khác — nghĩa 'tùy theo' rất hay gặp trong đề thi.", "group": "Nguyên nhân & góc nhìn"}, {"p": "N の あまり", "s": "N(cảm xúc) + のあまり、〜", "m": "Vì cảm xúc/x trạng thái quá mức nên dẫn đến kết quả ngoài kiểm soát.", "ex": [["うれしさのあまり、涙が出ました。", "Vì quá vui nên nước mắt trào ra."], ["心配のあまり、眠れませんでした。", "Vì quá lo lắng nên không ngủ được."]], "n": "あまり đứng sau danh từ chỉ cảm xúc/tình trạng: 驚きのあまり、緊張のあまり.", "group": "Nguyên nhân & góc nhìn"}, {"p": "〜ほど", "s": "V / A + ほど", "m": "ほど chỉ mức độ: 'đến mức…', thường đi với ví dụ cực đoan hoặc kết quả cụ thể.", "ex": [["眠れないほど疲れています。", "Tôi mệt đến mức không ngủ được."], ["彼は死ぬほど忙しいです。", "Anh ta bận đến chết đi được (bận cực độ)."]], "n": "Càng… càng…: V-ば + V-るほど (xem mẫu riêng).", "group": "Mức độ & giới hạn"}, {"p": "〜ば〜ほど", "s": "V-ば + V-るほど / A-ければ + A-いほど", "m": "Quan hệ tỉ lệ thuận: 'càng… càng…'.", "ex": [["考えれば考えるほど、分からなくなります。", "Càng nghĩ càng không hiểu."], ["日本語は勉強すればするほど、おもしろくなります。", "Tiếng Nhật càng học càng hay."]], "n": "Động từ/Tính từ lặp lại hai lần: 読めば読むほど、安ければ安いほど.", "group": "Mức độ & giới hạn"}, {"p": "〜くらい（ぐらい）", "s": "V / A + くらい（ぐらい)", "m": "くらい/ぐらい chỉ mức độ so sánh bằng ví dụ: 'đến mức như…'.", "ex": [["リュックに入らないくらい、たくさん買いました。", "Tôi mua nhiều đến mức balo không chứa hết."], ["泣きたいくらい悔しいです。", "Tôi tiếc đến mức muốn khóc."]], "n": "くらい còn dùng cho mức tối thiểu khiêm tốn: これくらい (ít nhất chừng này).", "group": "Mức độ & giới hạn"}, {"p": "できるだけ", "s": "できるだけ + V / A", "m": "'Hết mức có thể' — giới hạn tối đa trong khả năng.", "ex": [["時間があれば、できるだけ早く行きます。", "Nếu có thời gian, tôi sẽ đi càng sớm càng tốt."], ["できるだけ無駄をなくしましょう。", "Hãy giảm lãng phí hết mức có thể."]], "n": "できるだけ đứng độc lập trước động từ/tính từ cần nhấn.", "group": "Mức độ & giới hạn"}, {"p": "V-た きり", "s": "V-た + きり、〜ない", "m": "Sau sự việc đó thì trạng thái giữ nguyên, không có gì tiếp theo (thường là không quay lại/không liên lạc).", "ex": [["傘を持っていったきり、彼は帰ってきません。", "Anh ta cầm ô đi rồi không thấy quay lại nữa."], ["彼女とは卒業したきり、会っていません。", "Từ khi tốt nghiệp, tôi không gặp lại cô ấy nữa."]], "n": "Đọc きり; dạng viết trang trọng hơn: 〜きりだ.", "group": "Mức độ & giới hạn"}, {"p": "V-ます + っぱなし", "s": "V-ます + っぱなし", "m": "Để nguyên một trạng thái (thường là không nên) mà không xử lý — sắc thái cẩu thả.", "ex": [["窓を開けっぱなしで出かけました。", "Tôi ra ngoài mà cửa sổ vẫn mở toang (cẩu thả)."], ["電気をつけっぱなしにしないでください。", "Đừng để đèn bật mãi vậy."]], "n": "っぱなし nối sau gốc động từ: 置きっぱなし、出しっぱなし.", "group": "Mức độ & giới hạn"}, {"p": "〜気味", "s": "V-ます / N + 気味", "m": "気味 chỉ xu hướng/cảm giác nhẹ theo chiều hướng xấu là chủ yếu: 太り気味、遅れ気味.", "ex": [["最近、疲れ気味です。", "Dạo này tôi hơi mệt (có chiều hướng mệt)."], ["風邪気味なので、早く寝ます。", "Tôi hơi có triệu chứng cảm nên đi ngủ sớm."]], "n": "気味 đọc ぎみ khi ghép sau danh từ/động từ.", "group": "Mức độ & giới hạn"}, {"p": "V-ます + がち", "s": "V-ます + がち", "m": "がち chỉ thói quen/xu hướng hay xảy ra những điều không tốt.", "ex": [["彼は忘れがちです。", "Anh ta hay quên (có xu hướng quên)."], ["冬は風邪を引きがちです。", "Mùa đông dễ bị cảm."]], "n": "がち dùng cho việc tiêu cực hoặc không mong muốn; việc tốt dùng やすい.", "group": "Mức độ & giới hạn"}, {"p": "〜っぽい", "s": "N / A + っぽい", "m": "っぽい: 'có vẻ như / mang tính…' — giống bề ngoài hoặc tính chất tiêu biểu, thường hơi tiêu cực.", "ex": [["彼女は子どもっぽい話し方をします。", "Cô ấy nói chuyện kiểu trẻ con."], ["今日は夏っぽい天気です。", "Hôm nay thời tiết kiểu mùa hè."]], "n": "っぽい biến danh từ/tính từ thành tính từ -い.", "group": "Mức độ & giới hạn"}, {"p": "〜げ（な）", "s": "A(gốc) + げな / げに", "m": "〜げ diễn tả vẻ bề ngoài gợi cảm xúc của người khác nhìn vào: 'trông có vẻ…'.", "ex": [["彼女は悲しげな顔をしていました。", "Cô ấy có vẻ mặt buồn (đượm buồn)."], ["彼は不安げに周りを見ました。", "Anh ta nhìn quanh với vẻ bất an."]], "n": "げ đi với gốc tính từ: 悲しげ、嬉しげ、不安げ、満足げ.", "group": "Mức độ & giới hạn"}, {"p": "あり得る / あり得ない", "s": "あり得る / あり得ない", "m": "あり得る/あり得ない: 'có thể xảy ra / không thể nào' — khả năng về mặt logic.", "ex": [["努力しなければ、成功はあり得ない。", "Không nỗ lực thì không thể thành công."], ["そんなことがあり得ますか。", "Chuyện như thế có thể xảy ra sao?"]], "n": "得る đọc える trong mẫu này; phủ định ありえない rất hay dùng.", "group": "Mức độ & giới hạn"}, {"p": "精一杯", "s": "V-るのが + 精一杯です", "m": "精一杯: 'hết sức / tối đa khả năng' — làm được đến đó là giới hạn rồi.", "ex": [["今の給料では、生活するのが精一杯です。", "Với mức lương hiện tại, lo ăn ở là hết sức rồi."], ["走るのが精一杯で、話す余裕はありません。", "Chạy đã hết sức, không còn hơi để nói."]], "n": "Đọc せいいっぱい; cũng dùng làm trạng từ: 精一杯頑張ります.", "group": "Mức độ & giới hạn"}, {"p": "V-る + べきだ", "s": "V-る + べきだ / べきではない", "m": "'Phải / nên làm' với sắc thái bổn phận, đạo lý — mạnh và trang trọng hơn ほうがいい.", "ex": [["学生は勉強するべきです。", "Học sinh thì nên học (đó là bổn phận)."], ["約束は守るべきです。", "Lời hứa thì phải giữ."]], "n": "する → すべき. べき không dùng áp đặt trực tiếp lên người trên.", "group": "Nghĩa vụ & suy đoán"}, {"p": "V-ない + ざるをえない", "s": "V-ない（bỏ い） + ざるをえない", "m": "'Không còn cách nào khác ngoài việc…' — buộc phải làm dù không muốn.", "ex": [["行きたくないけど、行かざるをえません。", "Dù không muốn nhưng đành phải đi."], ["彼の実力では、負けざるをえないでしょう。", "Với thực lực đó, anh ta đành chịu thua thôi."]], "n": "する → せざるをえない. 得る đọc えない trong mẫu này.", "group": "Nghĩa vụ & suy đoán"}, {"p": "V-ない わけにはいかない", "s": "V-ない + わけにはいかない", "m": "'Không thể không làm' — nghĩa vụ hai lớp phủ định, nhấn mạnh hơn なければならない.", "ex": [["熱があるので、学校を休まないわけにはいきません。", "Vì sốt nên không thể không nghỉ học."], ["借りたものは返さないわけにはいきません。", "Đồ đã mượn thì không thể không trả."]], "n": "Khác ないわけではない (không phải là không…).", "group": "Nghĩa vụ & suy đoán"}, {"p": "〜わけがない", "s": "[Câu thường] + わけがない", "m": "Phủ định mạnh mẽ một khả năng: 'không thể nào / đời nào'.", "ex": [["彼がそんなことをするわけがありません。", "Không đời nào anh ta làm chuyện đó."], ["こんな大雨では、試合ができるわけがありません。", "Mưa to thế này, không thể nào thi đấu được."]], "n": "Dạng thân mật: わけない.", "group": "Nghĩa vụ & suy đoán"}, {"p": "〜わけではない", "s": "[Câu thường] + わけではない", "m": "Phủ định một phần: 'không phải là không…' — nói giảm nói tránh.", "ex": [["全然勉強しないわけではありません。", "Không phải là tôi hoàn toàn không học."], ["嫌いなわけではありませんが、今は食べたくありません。", "Không phải tôi ghét, chỉ là giờ không muốn ăn."]], "n": "わけではない dùng để đính chính ấn tượng của người nghe.", "group": "Nghĩa vụ & suy đoán"}, {"p": "〜はずがない", "s": "[Câu thường] + はずがない", "m": "はずがない phủ định sự tin chắc: dựa trên căn cứ mà kết luận 'không thể nào'.", "ex": [["そんな高い物が売れるはずがありません。", "Đồ đắt thế này không đời nào bán chạy."], ["彼が嘘をつくはずがありません。", "Anh ấy không thể nào nói dối được."]], "n": "Gần nghĩa わけがない; はずがない nhấn căn cứ khách quan hơn.", "group": "Nghĩa vụ & suy đoán"}, {"p": "〜に違いない", "s": "[Câu thường] + に違いない", "m": "Kết luận chắc chắn từ căn cứ: 'chắc chắn là…' — mạnh hơn でしょう/はずです.", "ex": [["この字は彼が書いたに違いありません。", "Chữ này chắc chắn là anh ấy viết."], ["音がしたから、誰かいるに違いありません。", "Có tiếng động nên chắc chắn có ai đó."]], "n": "Đọc ちがいありません; văn nói hay rút: に違いない.", "group": "Nghĩa vụ & suy đoán"}, {"p": "V-る/ない + ことにする", "s": "V + ことにする / ことにしました", "m": "Quyết định chủ quan của người nói: 'quyết định sẽ…'.", "ex": [["明日から毎日運動することにしました。", "Tôi quyết định từ mai sẽ vận động mỗi ngày."], ["この仕事は私が担当することにしました。", "Tôi quyết định phụ trách công việc này."]], "n": "Đối lập ことになる (quyết định khách quan/bị ấn định).", "group": "Nghĩa vụ & suy đoán"}, {"p": "V-る/ない + ことになる", "s": "V + ことになる / ことになりました", "m": "Việc được quyết định bởi yếu tố bên ngoài (công ty, hoàn cảnh) — người nói chỉ nhận kết quả.", "ex": [["転勤で大阪に住むことになりました。", "Tôi được điều chuyển, sẽ sống ở Osaka."], ["会議は来週に延期することになりました。", "Cuộc họp đã được quyết định dời sang tuần sau."]], "n": "ことになりました là cách nói khiêm tốn khi thông báo quyết định có liên quan đến mình.", "group": "Nghĩa vụ & suy đoán"}, {"p": "〜ということだ", "s": "[Câu thường] + ということだ", "m": "Truyền đạt thông tin tổng hợp nghe được: 'theo thông tin thì… / tức là…'.", "ex": [["この辺りは昔、海だったということです。", "Nghe nói khu này ngày xưa là biển."], ["社長は明日出張だということです。", "Thông tin là ngày mai giám đốc đi công tác."]], "n": "ということだ cũng dùng để kết luận ý nghĩa: つまり〜ということだ.", "group": "Nghĩa vụ & suy đoán"}, {"p": "〜と言われている", "s": "[Câu thường] + と言われている", "m": "Ý kiến chung của mọi người/nguồn không xác định: 'được cho là / người ta nói là…'.", "ex": [["この橋は日本で一番長いと言われています。", "Cây cầu này được cho là dài nhất Nhật Bản."], ["彼は天才だと言われています。", "Anh ấy được mọi người gọi là thiên tài."]], "n": "Dạng bị động của 言う dùng để tránh nêu đích danh nguồn.", "group": "Nghĩa vụ & suy đoán"}, {"p": "V-ます + そうにない", "s": "V-ます + そうにない / そうもない", "m": "Phủ định của そうです (vẻ): 'có vẻ sẽ không…' — dựa trên tình hình trước mắt.", "ex": [["こんなに待っても、彼は来そうにありません。", "Đợi thế này mà anh ta có vẻ không đến đâu."], ["この仕事は今日中には終わりそうもありません。", "Việc này có vẻ không xong trong hôm nay được."]], "n": "そうにない / そうもない / そうにもない — mức nhấn tăng dần.", "group": "Nghĩa vụ & suy đoán"}, {"p": "たとえ〜ても", "s": "たとえ + [Câu] + ても", "m": "Giả định cực đoan: 'cho dù/dẫu cho…' — kết quả vẫn không đổi.", "ex": [["たとえ雨が降っても、試合は行います。", "Dù trời có mưa, trận đấu vẫn diễn ra."], ["たとえ反対されても、やってみます。", "Dù bị phản đối, tôi vẫn sẽ làm thử."]], "n": "たとえ luôn đi với ても/でも ở vế sau.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜にしても", "s": "V / N + にしても", "m": "'Dù là… đi nữa' — tạm chấp nhận một vế để nói tiếp, thường kèm điều kiện/kế hoạch.", "ex": [["行くにしても、行かないにしても、早く決めてください。", "Dù đi hay không thì cũng quyết sớm giúp tôi."], ["買うにしても、値段を見てからにします。", "Dù có mua thì tôi cũng xem giá trước đã."]], "n": "にしても dùng với cả khẳng định và phủ định đặt song song.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜からには", "s": "[Câu thường] + からには、〜", "m": "'Đã… thì phải…' — một khi điều kiện/việc đã xảy ra, hệ quả là tất yếu.", "ex": [["やると決めたからには、最後までやり抜きます。", "Đã quyết làm thì phải làm đến cùng."], ["約束したからには、守らなければなりません。", "Đã hứa thì phải giữ lời."]], "n": "からには mang sắc thái quyết tâm/trách nhiệm.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜以上（は）", "s": "[Câu thường] + 以上（は）、〜", "m": "Giống からには: 'một khi đã… thì đương nhiên phải…'.", "ex": [["留学する以上は、しっかり勉強しなければなりません。", "Đã đi du học thì phải học đàng hoàng."], ["引き受けた以上、途中でやめられません。", "Đã nhận việc thì không thể bỏ giữa chừng."]], "n": "以上 đọc いじょう; không dùng cho giả định chưa xảy ra.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜限り", "s": "[Câu thường] + 限り、〜", "m": "'Chừng nào/trong giới hạn mà…' — điều kiện duy trì trong suốt khoảng đó.", "ex": [["生きている限り、希望があります。", "Chừng nào còn sống thì còn hy vọng."], ["私がいる限り、安心してください。", "Chừng nào còn tôi ở đây, cứ yên tâm."]], "n": "限り khác だけ (mức độ): 限り nhấn phạm vi điều kiện thời gian/trạng thái.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜ない限り", "s": "V-ない + 限り、〜ない", "m": "Điều kiện phủ định bắt buộc: 'nếu không… thì (mãi) không…'.", "ex": [["あなたが謝らない限り、私は許しません。", "Chừng nào anh chưa xin lỗi, tôi chưa tha thứ."], ["免許がない限り、運転できません。", "Không có bằng thì không được lái xe."]], "n": "Vế sau ない限り luôn là phủ định hoặc hệ quả tiêu cực.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜さえ〜ば", "s": "N + さえ + V-ば、〜", "m": "さえ + điều kiện: 'chỉ cần… là đủ' — điều kiện duy nhất, tối thiểu.", "ex": [["君さえ来れば、計画は進みます。", "Chỉ cần cậu đến là kế hoạch tiến hành được."], ["お金さえあれば、幸せでしょうか。", "Chỉ cần có tiền là hạnh phúc sao?"]], "n": "さえ còn nhấn cực đoan: 子どもでさえ知っている (ngay cả trẻ con cũng biết).", "group": "Điều kiện & nhượng bộ"}, {"p": "〜によっては", "s": "N + によっては、〜", "m": "'Tùy theo…' thì kết quả khác nhau; 場合によっては = trong một số trường hợp thì.", "ex": [["人によって、考え方が違います。", "Tùy theo người mà cách nghĩ khác nhau."], ["場合によっては、延期になります。", "Tùy trường hợp mà (việc này) sẽ bị hoãn."]], "n": "によっては khác によって (bị động) — có は phía sau.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜次第で", "s": "N + 次第で、〜", "m": "'Tùy vào…' thì hành động/quyết định sẽ theo đó mà thay đổi.", "ex": [["結果次第で、計画が変わります。", "Tùy vào kết quả mà kế hoạch sẽ thay đổi."], ["天気次第で、出発時間が決まります。", "Giờ xuất phát sẽ được quyết định tùy theo thời tiết."]], "n": "次第で khác 次第 (ngay khi) — 次第で mang nghĩa tùy thuộc.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜を問わず", "s": "N + を問わず", "m": "'Bất kể / không phân biệt…' — hay dùng trong tuyển dụng, thông báo.", "ex": [["年齢を問わず、誰でも参加できます。", "Bất kể tuổi tác, ai cũng tham gia được."], ["経験を問わず、応募できます。", "Không yêu cầu kinh nghiệm, ai cũng ứng tuyển được."]], "n": "問わず đọc とわず; mẫu văn trang trọng.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜を除いて", "s": "N + を除いて", "m": "'Ngoại trừ / trừ…' — loại một trường hợp ra khỏi tổng thể.", "ex": [["私を除いて、全員合格しました。", "Trừ tôi ra, mọi người đều đỗ."], ["日曜日を除いて、毎日営業しています。", "Trừ Chủ nhật, quán mở cửa mỗi ngày."]], "n": "除いて đọc のぞいて; danh từ phía trước là ngoại lệ.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜を中心に", "s": "N + を中心に", "m": "'Lấy… làm trung tâm/trọng điểm' — sự việc diễn ra xoay quanh yếu tố đó.", "ex": [["東京を中心に、関東地方で雨が降るでしょう。", "Mưa sẽ rơi ở vùng Kanto, trọng tâm là Tokyo."], ["子どもを中心に、家族写真を撮りました。", "Cả nhà chụp ảnh, lấy em bé làm trung tâm."]], "n": "中心に đọc ちゅうしんに.", "group": "Điều kiện & nhượng bộ"}, {"p": "〜っけ", "s": "[Câu thường quá khứ] + っけ", "m": "Hồi tưởng, tự hỏi chính mình về ký ức không chắc chắn: '…phải không nhỉ?'.", "ex": [["昨日、先生に会ったっけ。", "Hôm qua tôi có gặp thầy không nhỉ?"], ["この店、前にも来たことがあったっけ。", "Quán này trước đây mình từng đến rồi nhỉ?"]], "n": "っけ đứng cuối câu thường, giọng văn thân mật/gợi nhớ.", "group": "Thái độ & biểu cảm"}, {"p": "〜ものか（もんか）", "s": "[Câu thường] + ものか", "m": "Phủ định quyết liệt, đầy cảm xúc: 'không đời nào…!'.", "ex": [["負けるものか。", "Tôi không đời nào thua!"], ["あんな人に頼むもんか。", "Tôi đời nào nhờ loại người đó."]], "n": "ものか viết thân mật là もんか; chỉ dùng trong lời nói/ý nghĩ mạnh.", "group": "Thái độ & biểu cảm"}, {"p": "V-て たまらない / しょうがない", "s": "V-て + たまらない / しょうがない / ならない", "m": "Cảm giác/trạng thái mãnh liệt không kìm được: '…đến mức không chịu nổi'.", "ex": [["暑くてたまりません。", "Nóng không chịu nổi."], ["子どものことが心配でてしょうがありません。", "Tôi lo cho con đến mức không yên."]], "n": "Cả ba dạng tương đương: てたまらない、てしょうがない、てならない.", "group": "Thái độ & biểu cảm"}, {"p": "〜ふりをする", "s": "V-た / [Câu thường] + ふりをする", "m": "Giả vờ làm ra vẻ… dù thực tế không phải vậy.", "ex": [["寝たふりをして、話を聞いていました。", "Tôi giả vờ ngủ để nghe chuyện."], ["知らないふりをしました。", "Tôi giả vờ như không biết."]], "n": "ふり nối với V-たふり / Aなふり / Nのふり.", "group": "Thái độ & biểu cảm"}, {"p": "〜こそ", "s": "N + こそ、〜", "m": "こそ nhấn mạnh độc nhất: 'chính… mới là…'.", "ex": [["あなたにこそ、感謝しています。", "Chính bạn mới là người tôi biết ơn."], ["健康こそ、一番大切です。", "Chính sức khỏe mới là quan trọng nhất."]], "n": "こそ thay cho は/が sau danh từ được nhấn.", "group": "Thái độ & biểu cảm"}, {"p": "〜というより", "s": "[A] というより、[B]", "m": "Đính chính cách gọi: 'nói là X thì đúng hơn là Y'.", "ex": [["これは贈り物というより、借りの返済です。", "Cái này nói là quà tặng thì đúng hơn là trả nợ."], ["彼は歌手というより、芸人です。", "Anh ấy nói là ca sĩ thì đúng hơn là nghệ sĩ hài."]], "n": "というより đứng giữa hai cách diễn đạt để chọn cách sau.", "group": "Thái độ & biểu cảm"}, {"p": "〜わけだ", "s": "[Câu thường] + わけだ", "m": "わけだ tổng kết một hệ quả tất yếu: 'hóa ra là / thế nên mới…', hoặc 'đương nhiên là…' khi đồng ý logic.", "ex": [["だから、彼は来なかったわけです。", "Thế nên anh ấy mới không đến (giờ thì hiểu rồi)."], ["電車が止まって、遅れたわけです。", "Hóa ra tàu dừng nên tôi mới đến muộn."]], "n": "Phân biệt わけではない・わけがない (nhóm Nghĩa vụ & suy đoán).", "group": "Thái độ & biểu cảm"}, {"p": "〜ものだ", "s": "[Câu thường] + ものだ", "m": "ものだ nêu chân lý/chuyện đương nhiên hoặc hồi tưởng chung chung ('vốn là…').", "ex": [["若いうちは、失敗するものです。", "Tuổi trẻ thì ai cũng có lúc thất bại (lẽ thường)."], ["人の心は変わるものです。", "Lòng người thì vốn thay đổi."]], "n": "ものだ còn dùng hồi tưởng: 子どものころ、よく遊んだものだ (ngày xưa hay chơi).", "group": "Thái độ & biểu cảm"}, {"p": "V-る/ない + ことだ", "s": "V + ことだ", "m": "ことだ đưa lời khuyên mang tính nguyên tắc: 'điều cần làm là…'.", "ex": [["困ったときは、周りの人に相談することです。", "Khi gặp khó khăn, điều nên làm là hỏi ý kiến mọi người xung quanh."], ["疲れたら、無理をしないことです。", "Mệt thì điều quan trọng là đừng gắng sức."]], "n": "Khác ことにする (quyết định) và ことになる (được ấn định).", "group": "Thái độ & biểu cảm"}, {"p": "〜に限る", "s": "N / V-る + に限る", "m": "に限る khẳng định lựa chọn tốt nhất theo kinh nghiệm: '… là nhất / không gì bằng'.", "ex": [["疲れたときは、温泉に限ります。", "Khi mệt, đi suối nước nóng là nhất."], ["夏は冷たいビールに限ります。", "Mùa hè thì bia lạnh là nhất rồi."]], "n": "限る đọc かぎる; mẫu cảm thán, không dùng trong văn trang trọng.", "group": "Thái độ & biểu cảm"}, {"p": "V-る ことはない", "s": "V-る + ことはない", "m": "'Không cần thiết phải…' — phủ định nhu cầu một cách nhẹ nhàng, an ủi.", "ex": [["そんなに心配することはありません。", "Không cần phải lo đến thế đâu."], ["わざわざ来ることはありません。", "Không cần mất công đến tận nơi đâu."]], "n": "ことはない trang trọng/dịu hơn なくてもいい.", "group": "Thái độ & biểu cảm"}, {"p": "V-ます + かねない", "s": "V-ます + かねない", "m": "かねない cảnh báo khả năng xấu có thể xảy ra: 'có nguy cơ…'.", "ex": [["油断すると、事故が起こりかねません。", "Lơ là là có thể xảy ra tai nạn đấy."], ["言い方によっては、相手を傷つけかねません。", "Tùy cách nói mà có thể làm tổn thương đối phương."]], "n": "Nối sau gốc động từ (V-ます + かねない); văn trang trọng, hay dùng trong cảnh báo.", "group": "Thái độ & biểu cảm"}], "N2": [{"p": "〜に先立って", "s": "N / V-る + に先立って", "m": "“Trước khi…” ở văn trang trọng, dùng trong chương trình, thông báo chính thức.", "ex": [["開会に先立って、注意事項を説明します。", "Trước khi khai mạc, tôi sẽ giải thích các lưu ý."], ["出発に先立って、持ち物を確認してください。", "Trước khi xuất phát, hãy kiểm tra đồ mang theo."]], "n": "先立って đọc さきだって; sau là danh từ sự kiện hoặc động từ.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜に際して", "s": "N / V-る + に際して", "m": "“Nhân dịp/khi…” trang trọng hơn 際に, dùng cho cột mốc quan trọng.", "ex": [["卒業に際して、先生から言葉をいただきました。", "Nhân dịp tốt nghiệp, tôi nhận lời chúc từ thầy."], ["申し込みに際しては、手数料がかかります。", "Khi đăng ký sẽ phát sinh phí."]], "n": "際して đọc さいして.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜にあたって", "s": "N / V-る + にあたって", "m": "“Khi bắt đầu một giai đoạn/việc quan trọng” — mang sắc thái hướng tới việc sắp làm.", "ex": [["入社にあたって、必要な書類を提出してください。", "Khi vào công ty, hãy nộp các giấy tờ cần thiết."], ["留学にあたって、目標を明確にすることが大切です。", "Khi đi du học, việc rõ mục tiêu là quan trọng."]], "n": "あたって nhấn tâm thế/chuẩn bị, 際して nhấn thời điểm.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜にわたって", "s": "N(khoảng) + にわたって", "m": "“Suốt/trên toàn…” — kéo dài trên một khoảng thời gian hoặc phạm vi rộng.", "ex": [["三年にわたって、研究を続けてきました。", "Tôi đã tiếp tục nghiên cứu suốt ba năm."], ["全国にわたって、雨が降るでしょう。", "Mưa sẽ rơi trên phạm vi cả nước."]], "n": "わたって đi sau danh từ chỉ khoảng: 期間・範囲・回数.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "V-て からでないと〜ない", "s": "V-て + からでないと〜ない", "m": "Điều kiện tiên quyết tuyệt đối: “phải làm X xong trước, nếu không thì…”.", "ex": [["免許を取ってからでないと、運転できません。", "Không lấy bằng trước thì không lái được."], ["確認してからでないと、送れません。", "Chưa kiểm tra xong thì không gửi được."]], "n": "Vế sau luôn là phủ định.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜かと思ったら", "s": "[Câu quá khứ] + かと思ったら、〜", "m": "Vừa tưởng/nghĩ là X thì ngay lập tức chuyện ngược lại xảy ra.", "ex": [["やっと終わったかと思ったら、また新しい仕事が来ました。", "Vừa tưởng xong việc thì lại có việc mới đến."], ["家に着いたかと思ったら、もう出かける時間でした。", "Vừa về đến nhà thì đã đến giờ phải đi tiếp."]], "n": "かと思ったら diễn tả sự bất ngờ nối tiếp rất nhanh.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜をきっかけに", "s": "N / V-ること + をきっかけに", "m": "“Nhân cơ hội/nhờ bước ngoặt…” — sự việc làm khởi điểm cho thay đổi.", "ex": [["留学をきっかけに、国際交流に興味を持ちました。", "Nhân cơ hội đi du học, tôi bắt đầu quan tâm giao lưu quốc tế."], ["その事故をきっかけに、法律が改正されました。", "Nhân vụ tai nạn đó, luật đã được sửa đổi."]], "n": "きっかけに khác ために: chỉ bước ngoặt, không chỉ mục đích.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜て以来", "s": "V-て + 以来、〜", "m": "“Kể từ khi…” đến nay trạng thái vẫn tiếp diễn.", "ex": [["日本に来て以来、ずっとこの町に住んでいます。", "Kể từ khi đến Nhật, tôi luôn sống ở thị trấn này."], ["卒業以来、彼とは会っていません。", "Từ khi tốt nghiệp, tôi chưa gặp lại anh ấy."]], "n": "以来 đọc いらい; mệnh đề chính thường dùng ている/ずっと.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜がてら", "s": "N / V-ます + がてら", "m": "“Nhân tiện…” — làm việc phụ trong lúc làm việc chính, nhẹ nhàng hơn ついでに trong văn viết.", "ex": [["散歩がてら、買い物に行きました。", "Nhân tiện đi dạo, tôi đi mua đồ luôn."], ["駅まで送りがてら、話を聞きました。", "Nhân tiện tiễn ra ga, tôi nghe anh ấy nói chuyện."]], "n": "がてら nối sau danh từ hành động hoặc gốc động từ.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜かたわら", "s": "N / V-る + かたわら", "m": "“Song song với công việc chính…” — hai hoạt động lâu dài cùng tồn tại (văn trang trọng).", "ex": [["彼は教師のかたわら、作家としても活動しています。", "Anh ấy vừa làm giáo viên, đồng thời hoạt động như nhà văn."], ["仕事のかたわら、ボランティアをしています。", "Song song với công việc, tôi làm tình nguyện."]], "n": "かたわら chỉ dùng cho hoạt động kéo dài, không dùng cho việc chốc lát.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜を皮切りに", "s": "N + を皮切りに", "m": "“Mở đầu bằng…” — sự việc đầu tiên kéo theo chuỗi sự việc tương tự.", "ex": [["東京を皮切りに、全国ツアーが始まります。", "Bắt đầu từ Tokyo, tour toàn quốc sẽ khởi động."], ["彼の発言を皮切りに、議論が活発になりました。", "Bắt đầu từ phát ngôn của anh ấy, cuộc thảo luận trở nên sôi nổi."]], "n": "皮切り đọc かわきり; mẫu văn viết/báo chí.", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜において", "s": "N + において", "m": "において là dạng trang trọng của で/に: “tại, trong (lĩnh vực/thời đại)…”.", "ex": [["教育の分野において、大きな変化が起きています。", "Trong lĩnh vực giáo dục đang có thay đổi lớn."], ["会議において、重要な決定がなされました。", "Tại cuộc họp, quyết định quan trọng đã được đưa ra."]], "n": "Dạng danh từ: N における + N (vấn đềにおける…).", "group": "Bối cảnh & trình tự trang trọng"}, {"p": "〜に基づいて", "s": "N + に基づいて / に基づく + N", "m": "“Dựa trên (dữ kiện đáng tin)…” làm căn cứ cho hành động/quyết định.", "ex": [["調査に基づいて、計画を立てました。", "Dựa trên khảo sát, chúng tôi lập kế hoạch."], ["事実に基づいて判断してください。", "Hãy phán đoán dựa trên sự thật."]], "n": "基づいて đọc もとづいて — nguồn phải là dữ kiện khách quan (số liệu, luật, điều tra).", "group": "Căn cứ & quan hệ"}, {"p": "〜をもとに（して）", "s": "N + をもとに（して）", "m": "“Lấy… làm nguyên liệu/nền” để tạo ra sản phẩm — khác に基づいて ở chỗ nguồn là素材 sáng tạo.", "ex": [["体験をもとに、小説を書きました。", "Dựa trên trải nghiệm, tôi viết tiểu thuyết."], ["資料をもとにして、発表します。", "Tôi thuyết trình dựa trên tài liệu này."]], "n": "もとに trang trọng; văn nói dùng をもとにして.", "group": "Căn cứ & quan hệ"}, {"p": "〜に応じて", "s": "N + に応じて", "m": "“Tùy theo…” tương ứng: yếu tố trước thay đổi thì việc sau thay đổi theo tương ứng.", "ex": [["経験に応じて、給料が決まります。", "Lương được quyết định tùy theo kinh nghiệm."], ["季節に応じて、メニューが変わります。", "Thực đơn thay đổi theo mùa."]], "n": "応じて đọc おうじて.", "group": "Căn cứ & quan hệ"}, {"p": "〜にしたがって", "s": "N / V-る + にしたがって", "m": "Hai nghĩa: (1) thay đổi dần theo sự biến đổi khác; (2) tuân theo chỉ thị/quy định.", "ex": [["社会の変化にしたがって、人々の考え方も変わりました。", "Theo sự thay đổi của xã hội, cách nghĩ của mọi người cũng đổi."], ["指示にしたがって、作業してください。", "Hãy làm việc theo chỉ thị."]], "n": "したがって cũng là liên từ đầu câu: 'vì vậy'.", "group": "Căn cứ & quan hệ"}, {"p": "〜につれて", "s": "V-る / N + につれて", "m": "Một thay đổi kéo theo thay đổi khác dần dần, cùng chiều theo thời gian.", "ex": [["年を取るにつれて、体力が落ちてきました。", "Càng có tuổi, thể lực càng giảm."], ["上手になるにつれて、勉強が楽しくなりました。", "Càng giỏi lên, việc học càng thú vị."]], "n": "つれて chỉ dùng khi cả hai bên cùng thay đổi dần; khác ば〜ほど (quan hệ tỉ lệ tức thời).", "group": "Căn cứ & quan hệ"}, {"p": "〜を通じて", "s": "N + を通じて", "m": "Hai nghĩa: (1) thông qua phương tiện/người trung gian; (2) suốt một khoảng thời gian.", "ex": [["インターネットを通じて、世界中の人とつながれます。", "Thông qua internet, ta kết nối được với mọi người khắp thế giới."], ["一年を通じて、温暖な気候です。", "Khí hậu ôn hòa quanh năm."]], "n": "じて đọc じて. Phân biệt nghĩa theo danh từ đi trước (phương tiện vs khoảng thời gian).", "group": "Căn cứ & quan hệ"}, {"p": "〜を介して", "s": "N + を介して", "m": "“Thông qua trung gian (người)” — văn trang trọng của を通じて cho trường hợp có người làm cầu nối.", "ex": [["友人を介して、彼女と知り合いました。", "Qua bạn bè giới thiệu, tôi quen cô ấy."], ["通訳を介して、話し合いました。", "Chúng tôi trao đổi qua phiên dịch viên."]], "n": "介して đọc かいして.", "group": "Căn cứ & quan hệ"}, {"p": "〜に沿って", "s": "N + に沿って", "m": "“Dọc theo…” cả nghĩa đen (đường, sông) và nghĩa bóng (theo đúng phương châm/kế hoạch).", "ex": [["川に沿って、桜が植えられています。", "Dọc theo bờ sông có trồng cây anh đào."], ["計画に沿って、進めてください。", "Hãy tiến hành dọc theo/theo đúng kế hoạch."]], "n": "沿って đọc そって.", "group": "Căn cứ & quan hệ"}, {"p": "〜に比べて", "s": "N + に比べて", "m": "Đặt hai thời điểm/đối tượng lên bàn cân: “so với…”.", "ex": [["去年に比べて、売り上げが増えました。", "So với năm ngoái, doanh số tăng."], ["昔に比べて、生活が便利になりました。", "So với xưa, cuộc sống tiện lợi hơn."]], "n": "比べて là dạng て của 比べる; cũng dùng 比べると.", "group": "Căn cứ & quan hệ"}, {"p": "〜に関して", "s": "N + に関して / に関する + N", "m": "“Về/liên quan đến…” — cách dẫn đề trang trọng (関する + N: に関する問題).", "ex": [["その件に関しては、後日説明します。", "Về việc đó, tôi sẽ giải thích sau."], ["環境問題に関して、多くの意見があります。", "Về vấn đề môi trường có nhiều ý kiến."]], "n": "関して đọc かんして.", "group": "Căn cứ & quan hệ"}, {"p": "〜をめぐって", "s": "N + をめぐって", "m": "“Xoay quanh (vấn đề tranh cãi)…” — các ý kiến/hành động đối lập nhau quanh một chủ đề.", "ex": [["領土問題をめぐって、両国が対立しています。", "Xoay quanh vấn đề lãnh thổ, hai nước đang đối lập."], ["その発言をめぐって、議論が起きました。", "Xung quanh phát ngôn đó đã nổ ra tranh luận."]], "n": "めぐって chỉ dùng cho chủ đề có tranh luận/đối lập.", "group": "Căn cứ & quan hệ"}, {"p": "〜における", "s": "N + における + N", "m": "Dạng bổ nghĩa của において: “trong/tại…” đứng trước danh từ.", "ex": [["仕事におけるストレスが問題になっています。", "Căng thẳng trong công việc đang thành vấn đề."], ["人生における選択は重要です。", "Những lựa chọn trong đời người rất quan trọng."]], "n": "における chỉ đứng trước danh từ, không đứng cuối câu.", "group": "Căn cứ & quan hệ"}, {"p": "〜ものの", "s": "[Câu thường] + ものの、〜", "m": "ものの là dạng văn viết của のに/けれど: kết quả trái kỳ vọng.", "ex": [["彼は努力したものの、結果は出ませんでした。", "Dù đã nỗ lực, kết quả vẫn không như ý."], ["買ったものの、一度も使っていません。", "Đã mua vậy mà chưa dùng lần nào."]], "n": "ものの thường đi với た/ている ở vế trước và kết quả chưa đạt ở vế sau.", "group": "Nhượng bộ & tương phản"}, {"p": "〜ながらも", "s": "V-る / A / N + ながらも", "m": "“Mặc dù…” nhưng vẫn duy trì việc sau — nhấn sự kiên trì/trái ngược nhẹ.", "ex": [["忙しいながらも、毎日勉強を続けています。", "Dù bận rộn, tôi vẫn tiếp tục học mỗi ngày."], ["体は小さいながらも、力は強いです。", "Người tuy nhỏ nhưng sức rất khỏe."]], "n": "ながらも nối động từ nguyên dạng/tính từ/danh từ + ながらも.", "group": "Nhượng bộ & tương phản"}, {"p": "〜とはいえ", "s": "[Câu thường] + とはいえ、〜", "m": "“Dù nói là… thì…” — thừa nhận một phần nhưng vẫn giữ ý chính phía sau.", "ex": [["高いとはいえ、品質はとてもいいです。", "Dù nói là đắt, chất lượng thật sự rất tốt."], ["子どもとはいえ、そんなことをしてはいけません。", "Dù là trẻ con cũng không được làm thế."]], "n": "とはいえ cũng đứng đầu câu độc lập: とはいえ、…", "group": "Nhượng bộ & tương phản"}, {"p": "〜といっても", "s": "[Câu thường] + といっても、〜", "m": "“Dù nói là…” — nhìn chung đúng nhưng không đến mức như tưởng tượng/kỳ vọng.", "ex": [["便利になったといっても、問題も増えました。", "Nói là tiện hơn thì cũng có vấn đề tăng theo."], ["日本は安全だといっても、注意は必要です。", "Nói Nhật an toàn thì an toàn, vẫn cần cẩn thận."]], "n": "といっても hay dùng để hạ thấp kỳ vọng: 大したことはない sắc thái.", "group": "Nhượng bộ & tương phản"}, {"p": "V-た ところで", "s": "V-た + ところで、〜ない", "m": "“Dù có làm X cũng vô ích” — kết quả xấu đã định, làm cũng không thay đổi.", "ex": [["今さら謝ったところで、許してもらえません。", "Giờ có xin lỗi cũng không được tha thứ đâu."], ["急いだところで、間に合いません。", "Có vội cũng không kịp đâu."]], "n": "ところで ở đây khác 'nhân tiện' — vế sau luôn phủ định/vô ích.", "group": "Nhượng bộ & tương phản"}, {"p": "〜どころか", "s": "[Câu thường] + どころか、〜", "m": "Phủ định mạnh kỳ vọng: “đâu chỉ… mà ngược lại còn…” — thực tế trái hẳn, mức cao hơn.", "ex": [["彼は若いどころか、もう四十歳です。", "Anh ta trẻ gì chứ, đã 40 tuổi rồi."], ["手伝うどころか、邪魔ばかりしています。", "Giúp gì chứ, chỉ toàn phá rối."]], "n": "どころか dùng khi sự thật khác xa và tệ/cao hơn hẳn so với nói ban đầu.", "group": "Nhượng bộ & tương phản"}, {"p": "N + にしては", "s": "N + にしては、〜", "m": "“So với (chuẩn của)…” thì vượt/trái mức thường: đánh giá theo vai trò, mùa, tuổi.", "ex": [["彼は高校生にしては、落ち着いています。", "Là học sinh cấp 3 mà chững chạc thế (hơn mức thường)."], ["今日は冬にしては暖かいです。", "Hôm nay là mùa đông mà ấm thế này."]], "n": "にしては đứng sau danh từ chỉ thân phận/thời điểm.", "group": "Nhượng bộ & tương phản"}, {"p": "〜からすれば", "s": "N + からすれば、〜", "m": "“Xét từ lập trường/quan điểm của…” — đánh giá dựa trên vị trí người nói tới.", "ex": [["私からすれば、彼の態度は失礼です。", "Theo tôi thấy, thái độ của anh ta là vô lễ."], ["親からすれば、心配なのは当然です。", "Đứng ở góc cha mẹ mà xét, lo lắng là đương nhiên."]], "n": "からすれば/からすると/から見れば gần nghĩa nhau; から見れば nhấn quan sát bề ngoài.", "group": "Nhượng bộ & tương phản"}, {"p": "〜から見れば", "s": "N + から見れば、〜", "m": "Phán đoán dựa trên góc nhìn/căn cứ được nêu: “nhìn từ… mà xét thì…”.", "ex": [["外から見れば、幸せな家庭です。", "Nhìn từ bên ngoài, đó là gia đình hạnh phúc."], ["結果から見れば、判断は正しかったです。", "Xét theo kết quả, phán đoán đó là đúng."]], "n": "から見れば dùng cho đánh giá dựa trên dấu hiệu quan sát được.", "group": "Nhượng bộ & tương phản"}, {"p": "〜にすれば", "s": "N(người) + にすれば、〜", "m": "Đặt mình vào vị trí của người khác: “về phía/đối với người đó thì…”.", "ex": [["子どもにすれば、難しい話だったでしょう。", "Đối với trẻ con, đó hẳn là chuyện khó hiểu."], ["彼にすれば、精一杯の努力だったのです。", "Về phía anh ấy, đó đã là nỗ lực hết sức rồi."]], "n": "にすれば chỉ dùng cho người (lập trường của một cá nhân cụ thể).", "group": "Nhượng bộ & tương phản"}, {"p": "〜にもかかわらず", "s": "[Câu thường] + にもかかわらず、〜", "m": "“Mặc dù/bất chấp…” — dạng trang trọng, mạnh hơn のに, dùng văn viết và thông báo.", "ex": [["努力したにもかかわらず、失敗しました。", "Mặc dù đã nỗ lực, vẫn thất bại."], ["雨にもかかわらず、多くの人が集まりました。", "Bất chấp trời mưa, nhiều người vẫn tập trung."]], "n": "かかわらず đọc かかわらず; cũng có nghĩa 'bất kể' với danh từ (年齢にかかわらず).", "group": "Nhượng bộ & tương phản"}, {"p": "〜をよそに", "s": "N + をよそに", "m": "Bỏ qua trở ngại/khác biệt để thực hiện: “gạt… sang một bên, vẫn…”.", "ex": [["周りの心配をよそに、彼は危険な旅に出ました。", "Bỏ ngoài tai sự lo lắng của mọi người, anh ấy lên đường đi chuyến nguy hiểm."], ["親の反対をよそに、二人は結婚しました。", "Bất chấp sự phản đối của cha mẹ, hai người đã kết hôn."]], "n": "をよそに dùng khi làm ngơ trước lo lắng/phản đối của người xung quanh.", "group": "Nhượng bộ & tương phản"}, {"p": "〜だけに", "s": "[Câu thường] / N + だけに", "m": "“Chính vì là… nên đương nhiên…” — kết quả tương xứng với danh tiếng/đặc điểm đã nêu.", "ex": [["有名な店だけに、値段も高いです。", "Đúng là quán nổi tiếng có khác, giá cũng cao."], ["経験が豊富なだけに、仕事が早いです。", "Đúng là nhiều kinh nghiệm có khác, làm việc nhanh hẳn."]], "n": "だけに còn dùng cho kết quả trái kỳ vọng gây tiếc nuối: 期待していただけに、がっかりした.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "〜だけあって", "s": "[Câu thường] / N + だけあって", "m": "“Đúng là… có khác” — khen kết quả xứng với danh xưng, gần nghĩa だけに nhưng luôn tích cực.", "ex": [["プロだけあって、腕前が違います。", "Đúng là dân chuyên nghiệp có khác, tay nghề khác hẳn."], ["老舗だけあって、味が落ち着いています。", "Đúng là quán lâu đời có khác, hương vị rất vững."]], "n": "だけあって chỉ dùng khi kết quả tốt/xứng đáng; kết quả xấu dùng だけに.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "〜ばかりに", "s": "V-た + ばかりに、〜", "m": "“Chỉ vì (một việc không đáng) mà…” — nguyên nhân nhỏ gây hậu quả đáng tiếc.", "ex": [["余計なことを言ったばかりに、怒らせてしまいました。", "Chỉ vì nói thừa một câu mà làm người ta giận."], ["急いだばかりに、書類を忘れました。", "Chỉ vì vội mà quên mất tài liệu."]], "n": "ばかりに luôn đi với kết quả tiêu cực, hối tiếc.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "〜からこそ", "s": "[Câu thường] + からこそ、〜", "m": "Nhấn mạnh lý do độc nhất: “chính vì… nên mới…”.", "ex": [["故郷だからこそ、守りたいと思います。", "Chính vì là quê hương nên mới muốn bảo vệ."], ["好きだからこそ、厳しく言うのです。", "Chính vì thương nên mới nói nghiêm khắc."]], "n": "こそ ở đây nhấn mạnh nguyên nhân, vế sau là hệ quả cảm xúc/hành động đặc biệt.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "N + につき", "s": "N + につき、〜", "m": "つき là dạng văn thông báo của ので/ため: “do…” — chỉ thấy trên biển báo, thông cáo.", "ex": [["台風接近につき、明日は休業いたします。", "Do bão đến gần, ngày mai cửa hàng nghỉ."], ["工事につき、通行止めとなります。", "Do đang thi công, đường sẽ bị cấm."]], "n": "につき đọc につき; không dùng trong hội thoại.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "〜とあって", "s": "[Câu thường] + とあって、〜", "m": "“Vì là (dịp/trường hợp đặc biệt)…” nên kết quả đặc biệt xảy ra là đương nhiên.", "ex": [["人気歌手の公演とあって、チケットは即完売でした。", "Vì là buổi diễn của ca sĩ nổi tiếng nên vé bán hết ngay."], ["連休とあって、高速道路は混んでいました。", "Vì là kỳ nghỉ dài nên cao tốc đông nghẹt."]], "n": "とあって dùng khi hoàn cảnh đặc biệt ai cũng nhận thấy.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "あまりにも〜", "s": "あまりにも + A / V", "m": "“Quá đỗi/quá mức đến nỗi…” — nhấn mạnh mức độ vượt ngưỡng bình thường.", "ex": [["あまりにもひどい態度でした。", "Thái độ quá đỗi tệ."], ["あまりにも急で、対応できませんでした。", "Quá đột ngột nên không ứng phó kịp."]], "n": "あまりにも đứng trước tính từ/động từ; khác N のあまり (chỉ nguyên nhân cảm xúc).", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "〜ゆえに", "s": "N / [Câu thường] + ゆえに", "m": "ゆえに là “vì thế/do đó” ở văn viết trang trọng, nặng tính văn chương.", "ex": [["若さゆえに、彼は無謀な行動をとりました。", "Vì tuổi trẻ nên anh ta hành động liều lĩnh."], ["貧しさゆえに、進学を諦めました。", "Vì nghèo nên đành bỏ việc học tiếp."]], "n": "ゆえに đọc ゆえに; danh từ + ゆえに/ゆえの + N.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "V-た 末に", "s": "V-た / N の + 末に", "m": "“Sau một quá trình dài/kỹ càng thì cuối cùng…” — kết quả đạt được sau nỗ lực kéo dài.", "ex": [["何日も考えた末に、転職を決めました。", "Sau nhiều ngày suy nghĩ, tôi quyết định đổi việc."], ["話し合った末に、結論が出ました。", "Sau khi bàn bạc (dài), cuối cùng cũng có kết luận."]], "n": "末に đọc すえに; quá trình phải là dài và có cân nhắc (suy nghĩ, bàn bạc, nỗ lực).", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "〜をもって", "s": "N + をもって", "m": "もって ở văn trang trọng có hai nghĩa: (1) mốc kết thúc “kể từ…”; (2) phương tiện chính thức “bằng/lấy… làm”.", "ex": [["本日をもって、営業を終了いたします。", "Kể từ hôm nay, chúng tôi chấm dứt hoạt động kinh doanh."], ["このメールをもって、報告といたします。", "Xin lấy email này làm báo cáo chính thức."]], "n": "をもって đọc をもって; chỉ gặp trong thông báo, thư từ trang trọng.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "〜にかかわる", "s": "N + にかかわる + N / かかわって", "m": "かかわる: “liên quan đến / ảnh hưởng đến” những việc hệ trọng (mạng sống, tương lai, danh dự).", "ex": [["命にかかわる問題です。", "Đây là vấn đề liên quan đến tính mạng."], ["将来にかかわる大切な決断です。", "Đây là quyết định quan trọng ảnh hưởng đến tương lai."]], "n": "かかわる đọc かかわる; cũng viết 関わる.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "N の もとで", "s": "N + のもとで、〜", "m": "“Dưới (sự hướng dẫn/điều kiện)…” — bối cảnh chi phối việc được thực hiện.", "ex": [["先生の指導のもとで、研究を進めています。", "Dưới sự hướng dẫn của thầy, tôi tiến hành nghiên cứu."], ["厳しい条件のもとで、実験が行われました。", "Thí nghiệm được thực hiện trong điều kiện khắt khe."]], "n": "もとで đọc もとで; dạng khác: N のもとに.", "group": "Nguyên nhân & kết quả trang trọng"}, {"p": "V-ます + かねる", "s": "V-ます + かねる", "m": "かねる: “khó mà…” — không làm được vì lý do tâm lý/lịch sự, hay dùng trong văn kinh doanh.", "ex": [["大切なことですから、口に出しては言いかねます。", "Vì là việc quan trọng nên tôi khó mở lời."], ["結果については、責任を負いかねます。", "Về kết quả, chúng tôi không thể chịu trách nhiệm."]], "n": "かねる nối sau gốc động từ; khác かねない (có nguy cơ xấu xảy ra).", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "V-ます + がたい", "s": "V-ます + がたい", "m": "がたい: “khó mà…” về mặt bản chất (tin, hiểu, tha thứ, tưởng tượng).", "ex": [["彼の嘘は信じがたいです。", "Lời nói dối của anh ta khó mà tin được."], ["想像しがたい困難がありました。", "Có những khó khăn khó hình dung nổi."]], "n": "がたい trang trọng hơn にくい; nhóm động từ hay dùng: 信じ・理解し・想像し・許しがたい.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "V-ます + 得る（うる）", "s": "V-ます + 得る / 得ない", "m": "得る（うる/える）: khả năng trang trọng “có thể…” — あり得る là trường hợp đặc biệt đã quen.", "ex": [["そんなこともあり得ます。", "Chuyện đó cũng có thể xảy ra."], ["起こり得る問題に備えます。", "Chuẩn bị cho những vấn đề có thể phát sinh."]], "n": "Phủ định: 〜得ない（えない). Dạng る khi bổ nghĩa danh từ: 起こり得る.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "V-ない + ずにはいられない", "s": "V-ない（ず） + にはいられない", "m": "“Không thể không…” vì cảm xúc/xung động mạnh, không kìm được.", "ex": [["子どもの顔を見ると、笑わずにはいられません。", "Nhìn mặt con là không nhịn được cười."], ["感動して、泣かずにはいられませんでした。", "Xúc động quá, không cầm được nước mắt."]], "n": "Dạng đầy đủ: V-ないではいられない; する → せずにはいられない.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "V-ます + ようがない", "s": "V-ます + ようがない", "m": "“Không có cách nào để…” — phương pháp không tồn tại.", "ex": [["壊れてしまって、直しようがありません。", "Hỏng mất rồi, không có cách nào sửa được."], ["多すぎて、数えようがありません。", "Nhiều quá, đếm không xuể (không có cách đếm)."]], "n": "ようがない nối sau gốc động từ (V-ます + ようがない).", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "〜向き", "s": "N + 向き", "m": "向き chỉ tính chất/hướng phù hợp tự nhiên: đối tượng phù hợp, hướng (nam/bắc), kiểu người (内向き).", "ex": [["この辞典は初心者向きです。", "Từ điển này phù hợp cho người mới học (tính chất)."], ["南向きの部屋は明るいです。", "Phòng hướng nam thì sáng."]], "n": "向き nói về đặc tính vốn có; 向け nói về chủ đích thiết kế (mẫu sau).", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "〜向け", "s": "N + 向け", "m": "向け chỉ đích hướng tới có chủ đích: sản phẩm/dịch vụ làm ra cho một nhóm đối tượng.", "ex": [["これは子ども向けの番組です。", "Đây là chương trình dành cho trẻ em (được làm ra cho)."], ["外国人向けのサービスが増えています。", "Dịch vụ dành cho người nước ngoài đang tăng."]], "n": "Câu kinh điển phân biệt: 子ども向き (hợp với trẻ) vs 子ども向け (làm cho trẻ).", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "N + まみれ", "s": "N + まみれ", "m": "まみれ: dính đầy bề mặt cơ thể/quần áo (bùn, máu, mồ hôi, bụi) — chỉ dùng cho chất lỏng/bẩn.", "ex": [["泥まみれになって、遊んでいました。", "Chơi đến lấm lem bùn đất."], ["汗まみれで働いています。", "Làm việc đẫm mồ hôi."]], "n": "まみれ đọc まみれ; chỉ dùng cho một số danh từ giới hạn: 泥・血・汗・ほこり・油.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "N + だらけ", "s": "N + だらけ", "m": "だらけ: “đầy rẫy” những thứ không tốt/không vừa ý (lỗi, bụi, nếp nhăn, đồ bừa).", "ex": [["部屋中、物だらけです。", "Cả phòng toàn đồ đạc (bừa bộn)."], ["彼の作文は間違いだらけです。", "Bài văn của anh ta đầy lỗi sai."]], "n": "だらけ luôn mang sắc thái tiêu cực; vật tốt dùng いっぱい.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "V-ます + そびれる", "s": "V-ます + そびれる", "m": "そびれる: lỡ mất cơ hội làm việc định làm vì chần chừ/quên.", "ex": [["大事なことを言いそびれてしまいました。", "Tôi lỡ mất dịp nói điều quan trọng."], ["買いそびれた本が、もう売っていません。", "Quyển sách lỡ không mua kịp giờ không bán nữa."]], "n": "そびれる nối sau gốc động từ: 言いそびれる、逃げそびれる.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "V-ます + かけ", "s": "V-ます + かけ（の + N)", "m": "かけ: hành động đang làm dở, chưa hoàn thành (cả danh từ かけ: 仕事かけ).", "ex": [["食べかけのパンが残っています。", "Còn lại cái bánh ăn dở."], ["読みかけの本を置いて、出かけました。", "Tôi để cuốn sách đọc dở đó rồi ra ngoài."]], "n": "かけ nối sau gốc động từ; dạng trạng thái: V-かけだ/かけの + N.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "V-ます + きる / きれない", "s": "V-ます + きる / きれない", "m": "きる: làm đến cùng/hết sạch; きれない: không thể làm hết.", "ex": [["この量は一人では食べきれません。", "Lượng này một người ăn không hết."], ["お金を全部使いきってしまいました。", "Tôi tiêu hết sạch tiền rồi."]], "n": "きる nối sau gốc động từ: 使いきる、読みきる、食べきる.", "group": "Khả năng, xu hướng & trạng thái"}, {"p": "〜ないことには", "s": "V-ない + ことには、〜ない", "m": "“Nếu không (làm điều kiện tiên quyết) thì không thể…” — mạnh và trang trọng.", "ex": [["彼が来ないことには、会議を始められません。", "Anh ấy chưa đến thì không bắt đầu họp được."], ["実際に見ないことには、分かりません。", "Chưa tận mắt xem thì không biết được."]], "n": "ことには đứng sau thể phủ định; hệ quả phần sau bị chặn hoàn toàn.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "V-る + ほかない", "s": "V-る + ほかない / ほかありません", "m": "“Không còn cách nào ngoài…” — lựa chọn duy nhất còn lại.", "ex": [["電車がないので、歩いて帰るほかにありません。", "Không có tàu nên đành đi bộ về."], ["謝るほかないでしょう。", "Chỉ còn cách xin lỗi thôi."]], "n": "ほかない nối động từ nguyên dạng; trang trọng hơn しかない trong văn viết.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜ことは〜が", "s": "V/A + ことは + V/A + が", "m": "Nhượng bộ thừa nhận: “X thì đúng là X, nhưng…” — công nhận một phần trước khi nói ý chính.", "ex": [["高いことは高いが、品質はいいです。", "Đắt thì có đắt, nhưng chất lượng tốt."], ["難しいことは難しいですが、やってみます。", "Khó thì có khó, nhưng tôi sẽ thử."]], "n": "Động từ/tính từ lặp lại dạng [X] ことは [X] が/けれど.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜こそあれ", "s": "[Câu] + こそあれ、〜", "m": "こそあれ thừa nhận có sự khác biệt/bất lợi nhưng vẫn khẳng định điều cốt lõi.", "ex": [["国によって文化の違いこそあれ、人の気持ちは同じです。", "Mỗi nước có khác biệt văn hóa, nhưng tình cảm con người thì giống nhau."], ["意見の相違こそあれ、目的は一つです。", "Có bất đồng ý kiến, nhưng mục đích chỉ có một."]], "n": "こそあれ là mẫu văn viết; vế sau là khẳng định mạnh.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜はともかく", "s": "N / [Câu] + はともかく", "m": "“Tạm gác… sang một bên” để ưu tiên nói điều khác trước.", "ex": [["味はともかく、値段が安いです。", "Vị thì chưa nói tới, giá rẻ đã."], ["結果はともかく、努力は認めます。", "Kết quả tạm gác qua một bên, nỗ lực thì tôi ghi nhận."]], "n": "ともかく đứng sau danh từ/mệnh đề được tạm hoãn đánh giá.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜に限らず", "s": "N + に限らず、〜", "m": "“Không chỉ giới hạn ở…” — phạm vi rộng hơn điều vừa nêu.", "ex": [["この問題は今日中に限らず、長期的に考えるべきです。", "Vấn đề này không chỉ giới hạn hôm nay, cần nghĩ dài hạn."], ["日本に限らず、世界中で人気があります。", "Không chỉ ở Nhật, nó nổi tiếng khắp thế giới."]], "n": "限らず đọc かぎらず; khác に限る (là nhất).", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜にかかわらず", "s": "N + にかかわらず、〜", "m": "“Bất kể…” — điều kiện nêu ra không ảnh hưởng kết quả (hay dùng trong thông báo).", "ex": [["経験の有無にかかわらず、応募できます。", "Bất kể có kinh nghiệm hay không đều ứng tuyển được."], ["天候にかかわらず、試合は行われます。", "Bất kể thời tiết, trận đấu vẫn diễn ra."]], "n": "Dạng cặp đối lập hay gặp: 有無・年齢・国籍にかかわらず.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜もかまわず", "s": "N + もかまわず、〜", "m": "“Không màng/không quan tâm đến…” — hành động bỏ qua điều thường phải để ý.", "ex": [["彼は人目もかまわず泣きました。", "Anh ta khóc không màng ánh mắt người xung quanh."], ["場所もかまわず座り込んでしまいました。", "Ngồi bệt xuống không quan tâm chỗ nào cả."]], "n": "かまわず đứng sau danh từ + も: 時間もかまわず、人目もかまわず.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜なんて", "s": "[Câu thường] + なんて", "m": "なんて hạ thấp/ngạc nhiên: “(không ngờ) lại…”, “như… thì (không đáng)”.", "ex": [["彼が来るなんて、思ってもいませんでした。", "Tôi không ngờ anh ta lại đến."], ["あなたに嘘をつくなんて、できません。", "Tôi không thể nào nói dối bạn được."]], "n": "なんて nhấn cảm xúc chủ quan; trang trọng thay bằng など.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜にすぎない", "s": "[Câu thường] / N + にすぎない", "m": "“Chỉ là… mà thôi” — hạ thấp giá trị/mức độ của sự việc.", "ex": [["これは始まりにすぎません。", "Đây chỉ mới là khởi đầu mà thôi."], ["彼はまだ子どもにすぎないのです。", "Anh ta suy cho cùng vẫn chỉ là đứa trẻ thôi."]], "n": "すぎない nối sau [câu thường/N]; sắc thái khiêm tốn hoặc giảm kỳ vọng.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "〜に他ならない", "s": "N / [Câu thường] + に他ならない", "m": "“Không gì khác ngoài/chính là…” — khẳng định dứt khoát bản chất sự việc.", "ex": [["これは努力の結果に他なりません。", "Đây không gì khác chính là kết quả của nỗ lực."], ["成功の秘訣は継続に他なりません。", "Bí quyết thành công không gì khác ngoài sự bền bỉ."]], "n": "他なりません đọc ほか ありません; mẫu văn viết trang trọng.", "group": "Nhấn mạnh & phủ định trang trọng"}, {"p": "N + 次第だ", "s": "N + 次第だ", "m": "Danh từ + 次第だ: “tùy thuộc hoàn toàn vào…” — quyền quyết định nằm ở yếu tố đó.", "ex": [["行くか行かないかは、あなた次第です。", "Đi hay không là tùy ở bạn."], ["結果は本人の努力次第です。", "Kết quả tùy thuộc vào nỗ lực của chính người đó."]], "n": "Khác V-ます次第 (ngay khi) ở điểm này là danh từ + 次第だ cuối câu.", "group": "Nhấn mạnh & phủ định trang trọng"}], "N1": [{"p": "〜や否や", "s": "V + や否や、〜", "m": "“Ngay khi vừa…” — việc sau xảy ra tức thì sau việc trước (văn viết).", "ex": [["ドアが開くや否や、猫が飛び出しました。", "Cửa vừa mở là mèo phóng ra ngay."], ["発表されるや否や、批判が集まりました。", "Vừa công bố là chỉ trích đổ dồn tới."]], "n": "否や đọc いなや; động từ trước や否や dùng nguyên dạng hoặc た.", "group": "Thời gian & trình tự N1"}, {"p": "V-る なり", "s": "V-る + なり、〜", "m": "Việc sau xảy ra ngay sau việc trước một cách bất ngờ, thường là hành động của người khác.", "ex": [["彼は帰るなり、寝てしまいました。", "Anh ta vừa về là ngủ luôn."], ["電話を切るなり、彼女は泣き出しました。", "Vừa cúp máy là cô ấy bật khóc."]], "n": "なり dùng cho chuỗi hành động nhanh và bất ngờ; không dùng cho dự định của người nói.", "group": "Thời gian & trình tự N1"}, {"p": "V-た そばから", "s": "V-た + そばから、〜", "m": "Vừa làm xong việc trước thì (việc gây phiền) lại lặp lại ngay — sắc thái bất lực.", "ex": [["掃除したそばから、子どもが散らかします。", "Vừa dọn xong là trẻ con lại bày bừa ra."], ["覚えたそばから忘れてしまいます。", "Vừa học thuộc là lại quên ngay."]], "n": "そばから luôn kết hợp việc lặp lại gây khó chịu.", "group": "Thời gian & trình tự N1"}, {"p": "V-ては〜、V-ては", "s": "V1-ては V2、V2-ては V1", "m": "ては…ては chỉ chu kỳ hành động lặp lại nhiều lần.", "ex": [["彼は食べては寝る生活をしています。", "Anh ta sống kiểu ăn rồi lại ngủ, lặp đi lặp lại."], ["書いては消し、消しては書いています。", "Cứ viết rồi xóa, xóa rồi viết."]], "n": "Mẫu này nhấn tính lặp lại đơn điệu của thói quen.", "group": "Thời gian & trình tự N1"}, {"p": "〜てからというもの", "s": "V-て + からというもの、〜", "m": "“Kể từ khi…” — sau một bước ngoặt, trạng thái thay đổi hoàn toàn và kéo dài đến nay.", "ex": [["病気をしてからというもの、健康に気をつけています。", "Kể từ khi bị bệnh, tôi rất chú ý sức khỏe."], ["子どもが生まれてからというもの、生活が一変しました。", "Từ khi có con, cuộc sống thay đổi hẳn."]], "n": "Mạnh hơn て以来: nhấn sự thay đổi triệt để sau sự kiện.", "group": "Thời gian & trình tự N1"}, {"p": "N を限りに", "s": "N + を限りに", "m": "“Lấy… làm lần cuối/mốc kết thúc” — văn trang trọng cho quyết định dứt điểm.", "ex": [["今日を限りに、たばこをやめます。", "Từ hôm nay trở đi (lấy hôm nay làm mốc cuối), tôi bỏ thuốc."], ["今月を限りに、その雑誌は休刊となります。", "Lấy tháng này làm số cuối, tạp chí đó sẽ tạm ngưng."]], "n": "限りに đọc かぎりに.", "group": "Thời gian & trình tự N1"}, {"p": "V-る が 最後", "s": "V-る / V-た + が最後、〜", "m": "“Một khi đã… thì (hệ quả xấu không tránh được)” — cảnh báo kết cục tất yếu.", "ex": [["その秘密を知るが最後、無事では済みません。", "Một khi biết bí mật đó thì không xong chuyện đâu."], ["彼に任せるが最後、めちゃくちゃになります。", "Một khi giao cho anh ta là rối tung lên."]], "n": "が最後 dùng cho hệ quả tiêu cực, không đảo ngược được.", "group": "Thời gian & trình tự N1"}, {"p": "N を境に", "s": "N + を境に、〜", "m": "“Lấy… làm ranh giới/bước ngoặt” — trước và sau mốc đó khác hẳn nhau.", "ex": [["彼の結婚を境に、生活が変わりました。", "Lấy việc anh ấy kết hôn làm bước ngoặt, cuộc sống đã thay đổi."], ["その事件を境に、世論が変わり始めました。", "Từ vụ việc đó làm mốc, dư luận bắt đầu thay đổi."]], "n": "境に đọc さかいに.", "group": "Thời gian & trình tự N1"}, {"p": "〜に先駆けて", "s": "N + に先駆けて", "m": "“Đi tiên phong trước…” — làm trước mọi đối tượng khác (văn trang trọng).", "ex": [["他社に先駆けて、新製品を発表しました。", "Đi trước các công ty khác, chúng tôi công bố sản phẩm mới."], ["春に先駆けて、桜が咲きました。", "Đi trước mùa xuân, hoa anh đào đã nở."]], "n": "先駆けて đọc さきがけて.", "group": "Thời gian & trình tự N1"}, {"p": "〜矢先に", "s": "V-ようとした / V-た + 矢先に", "m": "“Đúng ngay lúc vừa định…” thì việc khác xen vào phá ngang.", "ex": [["出かけようとした矢先に、雨が降り出しました。", "Đúng lúc định ra ngoài thì trời đổ mưa."], ["忘れようとした矢先に、その曲が流れてきました。", "Đúng lúc cố quên đi thì bài hát đó lại vang lên."]], "n": "矢先に đọc やさきに.", "group": "Thời gian & trình tự N1"}, {"p": "〜に至って", "s": "N / V-る + に至って", "m": "“Đến khi/mãi đến mức…” mới xảy ra hệ quả — nhấn quá trình kéo dài đến điểm cực.", "ex": [["問題が深刻な事態に至って、ようやく対策が取られました。", "Đến khi tình hình trở nên nghiêm trọng, biện pháp mới được đưa ra."], ["病気が悪化するに至って、入院しました。", "Đến mức bệnh nặng hơn, (anh ấy) đã nhập viện."]], "n": "至って đọc いたって; cũng dùng 事態に至る (đi đến tình trạng).", "group": "Thời gian & trình tự N1"}, {"p": "N + いかんでは", "s": "N + いかんでは、〜", "m": "“Tùy vào (diễn biến)…” — dạng trang trọng của 次第で、 nhấn điều kiện chưa xác định.", "ex": [["結果いかんでは、計画を変更します。", "Tùy theo kết quả thế nào, chúng tôi sẽ thay đổi kế hoạch."], ["態度いかんでは、許しません。", "Tùy theo thái độ ra sao, tôi sẽ không tha thứ."]], "n": "いかん đọc いかん; văn viết/thông báo chính thức.", "group": "Thời gian & trình tự N1"}, {"p": "N + あっての + N", "s": "N1 + あっての + N2", "m": "“Nhờ có X mới có Y” — Y tồn tại được là nhờ nền tảng X.", "ex": [["皆さんの協力あっての成功です。", "Thành công này là nhờ có sự hợp tác của mọi người."], ["努力あっての結果です。", "Kết quả này có được là nhờ nỗ lực."]], "n": "あっての luôn đặt X trước、Y sau: X あっての Y.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "〜こととて", "s": "[Câu thường] + こととて、〜", "m": "Lời xin lỗi/giải thích trang trọng: “vì là… nên (đã lỡ…)”.", "ex": [["知らぬこととて、失礼いたしました。", "Vì tôi không biết nên đã thất lễ, xin thứ lỗi."], ["初めてのこととて、戸惑っております。", "Vì là lần đầu nên tôi còn bỡ ngỡ."]], "n": "こととて hay dùng trong thư từ, lời xin lỗi kinh doanh.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "〜手前", "s": "V-た + 手前、〜", "m": "“Vì thể diện/lập trường đã…” nên buộc phải hành xử tương xứng.", "ex": [["約束した手前、断るわけにはいきません。", "Vì đã hứa (giữ thể diện) nên không thể từ chối."], ["みんなの前で言った手前、引くに引けません。", "Đã nói trước mặt mọi người nên không rút lại được."]], "n": "手前 đọc てまえ; chỉ tâm lý giữ mặt mũi trước người khác.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "N + に免じて", "s": "N + に免じて、〜", "m": "“Vì nể…” — xin bỏ qua lỗi vì mối quan hệ/tình cảm với người được nêu.", "ex": [["私に免じて、今回だけは許してください。", "Vì nể tôi, xin tha cho lần này thôi."], ["亡き父に免じて、許してやってください。", "Vì nể người cha đã mất, xin hãy tha cho nó."]], "n": "免じて đọc めんじて; mẫu cầu xin trang trọng, ít gặp hội thoại thường.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "N + を踏まえて", "s": "N + を踏まえて、〜", "m": "“Đứng trên cơ sở…” — lấy kết quả/kinh nghiệm làm nền cho bước tiếp theo.", "ex": [["アンケート結果を踏まえて、改善策を決めました。", "Dựa trên kết quả khảo sát, chúng tôi quyết định biện pháp cải thiện."], ["経験を踏まえて、判断してください。", "Hãy phán đoán trên cơ sở kinh nghiệm."]], "n": "踏まえて đọc ふまえて.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "N + を受けて", "s": "N + を受けて、〜", "m": "“Tiếp nhận/chịu tác động của…” rồi hành động đáp lại.", "ex": [["住民の要望を受けて、市は計画を見直しました。", "Tiếp nhận yêu cầu của cư dân, thành phố đã xem lại kế hoạch."], ["批判を受けて、彼は謝罪しました。", "Nhận chỉ trích, anh ta đã xin lỗi."]], "n": "受けて ở đây là 'tiếp nhận (yêu cầu, chỉ thị, ảnh hưởng)'.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "〜ともなると / ともなれば", "s": "N + ともなると / ともなれば", "m": "“Khi đã ở mức/vị thế…” thì đương nhiên khác thường.", "ex": [["プロともなると、練習量が違います。", "Đã là dân chuyên nghiệp thì khối lượng luyện tập khác hẳn."], ["四十歳ともなれば、健康が気になります。", "Khi đã 40 tuổi thì sức khỏe thành mối lo."]], "n": "ともなると/ともなれば dùng cho cột mốc vị thế, tuổi tác, quy mô.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "〜せいか", "s": "[Câu thường] / N の + せいか", "m": "Đoán nguyên nhân không chắc chắn: “có lẽ vì…”.", "ex": [["年のせいか、最近疲れやすいです。", "Có lẽ vì tuổi tác, dạo này tôi dễ mệt."], ["気のせいか、誰かに見られている気がします。", "Có lẽ do tôi tưởng tượng, cứ thấy như có ai nhìn mình."]], "n": "せいか hàm ý 'không rõ có phải vì thế không'.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "N + に起因する", "s": "N + に起因する / している", "m": "“Bắt nguồn từ…” — cách nêu nguyên nhân khoa học/trang trọng.", "ex": [["過労に起因する事故が増えています。", "Tai nạn bắt nguồn từ làm việc quá sức đang tăng."], ["この問題は制度に起因しています。", "Vấn đề này bắt nguồn từ chế độ."]], "n": "起因する đọc きいんする; văn báo cáo, tin tức.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "N + に由来する", "s": "N + に由来する / している", "m": "“Có nguồn gốc từ…” — dùng cho từ ngữ, phong tục, tên gọi.", "ex": [["この言葉はラテン語に由来します。", "Từ này có nguồn gốc từ tiếng Latin."], ["彼の芸術は故郷の自然に由来しています。", "Nghệ thuật của ông bắt nguồn từ thiên nhiên quê hương."]], "n": "由来する đọc ゆらいする; khác 起因 (nguyên nhân gây hậu quả xấu là chủ yếu).", "group": "Nguyên nhân & hệ quả N1"}, {"p": "N + がもとで", "s": "N + がもとで、〜", "m": "“Chính… là nguồn cơn” gây ra hậu quả xấu.", "ex": [["油断がもとで、大きな失敗をしました。", "Vì lơ là mà gây ra thất bại lớn."], ["うそがもとで、信用を失いました。", "Vì một lời nói dối mà mất hết uy tín."]], "n": "がもとで luôn đi với kết quả tiêu cực.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "〜あってのことだ", "s": "N + あってのことだ", "m": "“Có X mới có tất cả” — biến thể thành ngữ của あっての, nhấn điều kiện tiên quyết quý giá nhất.", "ex": [["命あっての物種です。", "Còn sống là còn tất cả (mạng sống là gốc của mọi thứ)."], ["健康あっての仕事です。", "Có sức khỏe mới làm việc được."]], "n": "命あっての物種 là câu thành ngữ cố định, hay được trích dẫn.", "group": "Nguyên nhân & hệ quả N1"}, {"p": "N + をものともせず（に）", "s": "N + をものともせず（に）", "m": "“Không hề nao núng/bận tâm trước…” — vượt qua trở ngại với ý chí mạnh.", "ex": [["彼は困難をものともせずに、前進しました。", "Anh ấy tiến lên không nao núng trước khó khăn."], ["周囲の反対をものともせず、計画を実行しました。", "Không để tâm đến phản đối xung quanh, (anh ấy) thực hiện kế hoạch."]], "n": "ものともせず là mẫu văn trang trọng, sắc thái ca ngợi.", "group": "Nhượng bộ & đối lập N1"}, {"p": "N + を顧みず", "s": "N + を顧みず、〜", "m": "“Không đoái hoài đến…” — bỏ qua điều đáng lẽ phải quan tâm.", "ex": [["家族を顧みず、仕事に打ち込みました。", "Không đoái hoài gia đình, anh ta đắm mình vào công việc."], ["危険を顧みず、人を助けました。", "Không màng nguy hiểm, anh ấy cứu người."]], "n": "顧みず đọc かえりみず.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜にもほどがある", "s": "N / V-る + にもほどがある", "m": "“Cái gì cũng có giới hạn!” — trách móc khi việc gì đó vượt quá mức chấp nhận được.", "ex": [["冗談にもほどがあります。", "Đùa cũng phải có mức độ chứ!"], ["心配するにもほどがあるでしょう。", "Lo lắng cũng vừa phải thôi chứ."]], "n": "にもほどがある thường dùng độc lập khi phê phán trực tiếp.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜ばかりか", "s": "[Câu thường] + ばかりか、〜も/まで", "m": "“Không chỉ… mà còn…” — cộng thêm một yếu tố cùng chiều (thường xấu hơn).", "ex": [["彼は疲れたばかりか、風邪まで引きました。", "Anh ta không chỉ mệt mà còn bị cảm nữa."], ["値段が高いばかりか、品質も悪いです。", "Giá không chỉ cao mà chất lượng còn tệ."]], "n": "ばかりか hay đi với まで/も ở vế sau.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜にひきかえ", "s": "[Câu / N] + にひきかえ、〜", "m": "“Trái hẳn với…” — đối lập sắc nét giữa hai đối tượng.", "ex": [["兄が几帳面なのにひきかえ、弟は大雑把です。", "Trái hẳn với anh trai cẩn thận, em trai rất xuề xòa."], ["去年が豊作だったのにひきかえ、今年は不作です。", "Trái với năm ngoái được mùa, năm nay mất mùa."]], "n": "ひきかえ đọc ひきかえ; hai vế phải đối xứng để so sánh.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜とは裏腹に", "s": "N + とは裏腹に、〜", "m": "“Trái ngược hoàn toàn với…” — thực tế ngược hẳn điều bề ngoài/kỳ vọng.", "ex": [["期待とは裏腹に、結果は悪かったです。", "Trái với kỳ vọng, kết quả rất tệ."], ["彼の言葉とは裏腹に、表情は冷たかったです。", "Trái với lời nói, vẻ mặt anh ta lạnh lùng."]], "n": "裏腹に đọc うらはらに.", "group": "Nhượng bộ & đối lập N1"}, {"p": "N + に反して", "s": "N + に反して、〜", "m": "“Trái với (dự đoán, kỳ vọng, quy tắc)…” thì sự việc diễn ra khác hẳn.", "ex": [["予想に反して、株価が上がりました。", "Trái với dự đoán, giá cổ phiếu tăng."], ["親の期待に反して、彼は芸術の道を選びました。", "Trái với kỳ vọng của cha mẹ, anh ấy chọn con đường nghệ thuật."]], "n": "反して đọc はんして; dạng danh từ: 規則に反する行為.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜と思いきや", "s": "[Câu quá khứ] + と思いきや、〜", "m": "“Tưởng là… ai ngờ…” — thực tế hoàn toàn ngoài dự đoán.", "ex": [["試験は終わったと思いきや、もう一つ残っていました。", "Tưởng thi xong rồi, hóa ra còn một môn nữa."], ["彼は怒ると思いましたが、思いきや笑い出しました。", "Tưởng anh ta sẽ giận, ai ngờ lại bật cười."]], "n": "思いきや chỉ dùng khi kết quả bất ngờ trái hẳn suy nghĩ ban đầu.", "group": "Nhượng bộ & đối lập N1"}, {"p": "N + を余儀なくされる", "s": "N + を余儀なくされる", "m": "“Bị buộc phải…” bởi hoàn cảnh, không còn lựa chọn nào khác.", "ex": [["会社は倒産を余儀なくされました。", "Công ty bị buộc phải phá sản."], ["悪天候のため、延期を余儀なくされました。", "Vì thời tiết xấu nên buộc phải hoãn."]], "n": "余儀なくされる đọc よぎなくされる; mẫu văn trang trọng/báo chí.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜ていながら", "s": "V-て いる + ながら、〜", "m": "“Biết rõ là… vậy mà vẫn…” — sắc thái trách nhẹ hành vi trái với nhận thức.", "ex": [["彼は事情を知っていながら、何も言いませんでした。", "Biết rõ tình hình vậy mà anh ta không nói gì."], ["悪いと知っていながら、止められませんでした。", "Biết là xấu vậy mà không dừng được."]], "n": "ていながら dùng cho trạng thái đang duy trì (知っている、住んでいる…).", "group": "Nhượng bộ & đối lập N1"}, {"p": "N + といえども", "s": "N + といえども、〜", "m": "“Dù cho là…” — dạng văn trang trọng của たとえ〜ても cho danh từ/thân phận.", "ex": [["たとえ子どもといえども、礼儀は必要です。", "Dù là trẻ con đi nữa, lễ phép vẫn cần thiết."], ["専門家といえども、間違えることがあります。", "Dù là chuyên gia cũng có lúc sai."]], "n": "といえども đọc といえども.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜と知りながら", "s": "[Câu] + と知りながら、〜", "m": "“Biết rõ là… mà vẫn…” — cố ý làm bất chấp nhận thức (thường tiêu cực).", "ex": [["彼は嘘だと知りながら、黙っていました。", "Biết đó là lời nói dối mà vẫn im lặng."], ["危険だと知りながら、彼は進みました。", "Biết là nguy hiểm mà anh ấy vẫn tiến lên."]], "n": "知りながら là dạng cố định hay gặp nhất của mẫu 〜ながら này.", "group": "Nhượng bộ & đối lập N1"}, {"p": "〜ねばならない", "s": "V-ない（ば形） + ねばならない", "m": "〜ねばならない là dạng trang trọng/văn viết của なければならない.", "ex": [["約束した以上、守らねばなりません。", "Đã hứa thì phải giữ lời (văn trang trọng)."], ["行くと決めたら、行かねばなりません。", "Đã quyết đi thì phải đi."]], "n": "ねば nối thể phủ định rút gọn: 行かなければ → 行かねば.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "V + ずにはすまない", "s": "V-ない（ず） + にはすまない", "m": "“Không làm thì không xong (về mặt đạo lý/xã hội)” — áp lực nghĩa vụ từ bên ngoài.", "ex": [["先輩に対して失礼なことをしたので、謝らずにはすみません。", "Đã làm điều thất lễ với tiền bối nên không xin lỗi thì không xong."], ["借りたものは返さずにはすみません。", "Đồ mượn thì không trả là không được."]], "n": "すまない ở đây là 'không thể cho qua', khác すみません xin lỗi.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "V-て はならない", "s": "V-て + はならない", "m": "Cấm đoán ở văn quy định/biển báo — dạng trang trọng của てはいけません.", "ex": [["ここにゴミを捨ててはなりません。", "Không được vứt rác ở đây (văn quy định)."], ["関係者以外、入ってはなりません。", "Người không liên quan không được vào."]], "n": "なりません mạnh và chính thức hơn いけません.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "V-る + べく", "s": "V-る + べく、〜", "m": "〜べく là dạng trang trọng của ために (mục đích) trong văn viết.", "ex": [["真実を知るべく、調査を続けています。", "Để biết sự thật, chúng tôi tiếp tục điều tra."], ["彼に会うべく、駅へ向かいました。", "Để gặp anh ấy, tôi hướng ra ga."]], "n": "べく đi sau động từ nguyên dạng; する → すべく.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "〜べくして", "s": "V-る + べくして + V-た", "m": "“Xảy ra là điều tất yếu (do tích tụ nguyên nhân)” — không phải ngẫu nhiên.", "ex": [["事故は起こるべくして起こりました。", "Tai nạn xảy ra là điều tất yếu phải xảy ra."], ["二人は出会うべくして出会ったのです。", "Hai người gặp nhau là duyên định sẵn (tất yếu)."]], "n": "べくして mang sắc thái triết lý/số phận của sự việc.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "〜まじ / あるまじき", "s": "V-る + まじ / N にあるまじき + N", "m": "まじ là phủ định ý chí văn cổ: あるまじき = “không được phép có (ở tư cách…)”.", "ex": [["学生にあるまじき行為です。", "Đó là hành vi không thể chấp nhận ở một học sinh."], ["プロにあるまじきミスをしました。", "Anh ta mắc lỗi không đáng có ở dân chuyên nghiệp."]], "n": "Dạng cố định hay dùng: N にあるまじき + hành vi.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "V + んがため（に）", "s": "V-ない gốc + んがために", "m": "んがため là dạng văn chương cổ của ために: “để (đạt mục đích)…”.", "ex": [["生きんがために、彼は働き続けました。", "Để sống, anh ấy làm việc không ngừng."], ["勝たんがために、猛練習しました。", "Để thắng, (đội) luyện tập cật lực."]], "n": "Động từ đổi: 行く → 行かんがため; chỉ còn gặp trong văn viết, lời văn.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "N + なしに（は）", "s": "N / V-ること + なしに（は）、〜ない", "m": "“Không có… thì không thể…” — điều kiện tiên quyết ở văn trang trọng.", "ex": [["努力することなしに、成功は得られません。", "Không nỗ lực thì không thể thành công."], ["彼の協力なしには、この計画は進みません。", "Không có sự hợp tác của anh ấy, kế hoạch này không tiến triển được."]], "n": "なしに/なしには đều dùng được; なしには nhấn mạnh hơn.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "〜ようでは", "s": "[Câu thường] + ようでは、〜", "m": "“Cứ tình trạng này thì…” — cảnh báo hậu quả xấu nếu không thay đổi.", "ex": [["こんな調子では、試験に合格できません。", "Cứ đà này thì không đỗ nổi kỳ thi đâu."], ["今のようでは、信頼を失いますよ。", "Cứ như tình trạng bây giờ thì sẽ mất lòng tin đấy."]], "n": "ようでは đứng sau [thể thường]; phần sau là dự đoán tiêu cực.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "〜に越したことはない", "s": "V-る / A-い / N + に越したことはない", "m": "“Không gì tốt hơn…” — khẳng định lựa chọn tối ưu trong lời khuyên.", "ex": [["健康は、お金で買えるものではありません。大切にするに越したことはありません。", "Sức khỏe không mua được bằng tiền. Chăm sóc nó là tốt nhất, không gì hơn."], ["準備は早いに越したことはありません。", "Chuẩn bị thì càng sớm càng tốt, không gì bằng."]], "n": "越したことはない đọc こしたことはない.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "V-て こそ", "s": "V-て + こそ、〜", "m": "“Phải làm X rồi mới…” — X là điều kiện không thể thiếu để hệ quả có ý nghĩa.", "ex": [["彼に頼んでこそ、分かることです。", "Phải nhờ anh ấy thì mới biết được."], ["努力してこそ、成功が見えてきます。", "Phải nỗ lực rồi mới thấy thành công."]], "n": "てこそ nhấn giá trị chỉ xuất hiện sau khi hành động được thực hiện.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "N + でなくてはならない", "s": "N + でなくてはならない", "m": "“Nhất định phải là…” — dạng trang trọng của でなければならない cho danh từ.", "ex": [["事実でなくてはなりません。", "(Nó) phải là sự thật (mới được)."], ["彼でなくては、この仕事はできません。", "Không phải anh ấy thì không ai làm được việc này."]], "n": "でなくては là rút gọn của でなくてはならない trong văn viết.", "group": "Nghĩa vụ & ý chí N1"}, {"p": "〜も同然だ", "s": "[Câu thường] + も同然だ", "m": "“Coi như/gần như là…” — thực chất khác nhưng trạng thái tương đương.", "ex": [["彼は死んだも同然です。", "Anh ta coi như đã chết (sống mà như chết)."], ["この機械は壊れたも同然です。", "Cái máy này coi như hỏng rồi."]], "n": "も同然 đọc もどうぜん.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "〜に等しい", "s": "[Câu thường] + に等しい", "m": "“Gần như ngang bằng với…” — mức độ tiệm cận trạng thái được so.", "ex": [["この村には店が無いに等しいです。", "Làng này gần như không có cửa hàng nào."], ["合格したに等しい結果でした。", "Đó là kết quả gần như đỗ rồi."]], "n": "等しい đọc ひとしい; văn trang trọng.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "V-る + に堪える / 堪えない", "s": "V-る + に堪える / に堪えない", "m": "堪える hai nghĩa: (1) không chịu nổi (phủ định); (2) đáng để (khẳng định: 一見に堪える = đáng xem).", "ex": [["彼の文章は読むに堪えません。", "Văn của anh ta đọc không chịu nổi (quá dở)."], ["見るに堪えない光景でした。", "Đó là cảnh tượng không nỡ nhìn."]], "n": "堪える đọc たえる; phủ định dùng cho chất lượng quá tệ hoặc cảnh quá đau lòng.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "〜に値する", "s": "N / V-る + に値する", "m": "“Xứng đáng để…” — giá trị đủ để nhận hành động đánh giá/trải nghiệm đó.", "ex": [["彼の努力は評価に値します。", "Nỗ lực của anh ấy xứng đáng được đánh giá cao."], ["一読に値する本です。", "Đây là cuốn sách đáng đọc một lần."]], "n": "値する đọc あたいする.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "〜ざらではない / 〜ざらだ", "s": "[Câu / N] + ざらではない", "m": "“Là chuyện thường/thường xuyên xảy ra” — dạng phủ định kép hoặc ざらだ cho việc phổ biến.", "ex": [["若い人の失敗は珍しいことざらではありません。", "Người trẻ thất bại không phải chuyện hiếm."], ["遅刻はざらです。", "Anh ta đi muộn là chuyện thường ngày."]], "n": "ざら luôn đi với ない hoặc だ ở cuối; văn nói trang trọng.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "N + ぶり（様子）", "s": "N(hoạt động) + ぶり", "m": "〜ぶり chỉ phong cách/thái độ thể hiện qua hành động: 仕事ぶり、生活ぶり、飲みぶり.", "ex": [["彼の仕事ぶりは見事です。", "Cách làm việc của anh ấy thật đáng nể."], ["彼女の話しぶりは丁寧です。", "Cách nói chuyện của cô ấy lịch sự."]], "n": "ぶり cũng chỉ khoảng thời gian xa cách: 三年ぶり (sau 3 năm) — nghĩa khác.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "N + めく / めいた", "s": "N + めく / めいた + N", "m": "めく: bắt đầu mang sắc thái/tính chất của danh từ (mùa, cảm xúc, vẻ bí ẩn).", "ex": [["空が春めいてきました。", "Bầu trời bắt đầu mang hơi thở mùa xuân."], ["彼女は神秘めいた雰囲気があります。", "Cô ấy có bầu không khí huyền bí."]], "n": "めく hay dùng: 春めく、秋めく、神秘めいた、皮肉めいた.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "N + じみた", "s": "N + じみた + N", "m": "じみる: trông giống/mang vẻ của… — thường mang sắc thái hơi tiêu cực, không đúng tuổi/vai.", "ex": [["彼の考えは子どもじみています。", "Suy nghĩ của anh ta trẻ con quá."], ["年寄りじみた服装です。", "Trang phục trông già dặn (như người già)."]], "n": "じみた đứng trước danh từ; chỉ dùng cho người/vẻ bề ngoài.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "〜きっている", "s": "V-ます + きっている", "m": "きる（きっている）: trạng thái đạt đến cực điểm hoàn toàn (mệt lử, căng thẳng hẳn).", "ex": [["彼は疲れきっています。", "Anh ta mệt lử (kiệt sức hoàn toàn)."], ["緊張しきった様子でした。", "Anh ấy có vẻ căng thẳng cực độ."]], "n": "Khác きる (làm hết) ở nhóm khả năng N2: ở đây chỉ trạng thái tinh thần/thể chất tột độ.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "N の 極み", "s": "N(trừu tượng) + の極み", "m": "の極み: “tột đỉnh/tột cùng” của một trạng thái trừu tượng (văn trang trọng).", "ex": [["贅沢の極みを味わいました。", "Tôi đã nếm trải sự xa xỉ tột đỉnh."], ["愚かの極みです。", "Đúng là ngu xuẩn tột độ."]], "n": "極み đọc きわみ.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "Aな + 極まる", "s": "Aな + 極まる", "m": "極まる đứng sau tính từ -な: “cực kỳ… (đến mức không hơn được)” — phê phán mạnh.", "ex": [["無礼極まる人です。", "Anh ta là người vô lễ cực độ."], ["残酷極まる事件でした。", "Đó là vụ việc tàn ác tột cùng."]], "n": "極まる đọc きわまる; luôn mang sắc thái tiêu cực.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "N の 至り", "s": "N(cảm xúc) + の至りです", "m": "の至り: đỉnh điểm của cảm xúc trong các mẫu chào trang trọng (vinh hạnh, xấu hổ, mừng rỡ).", "ex": [["お選びいただき、光栄の至りです。", "Được quý vị lựa chọn, chúng tôi vô cùng vinh hạnh."], ["若輩の至りで、申し訳ありません。", "Tôi còn non nớt, xin lỗi (lời khiêm tốn trang trọng)."]], "n": "至り đọc いたり; các cụm cố định: 光栄の至り、赤面の至り.", "group": "Trạng thái & mức độ cực đoan"}, {"p": "N + すら", "s": "N + すら（〜ない）", "m": "すら nhấn mạnh cực đoan: “ngay cả (mức tối thiểu/tối đa) cũng…”.", "ex": [["専門家ですら、間違えることがあります。", "Ngay cả chuyên gia cũng có lúc sai."], ["彼は名前すら書けません。", "Anh ta ngay cả tên mình cũng không viết được."]], "n": "すら trang trọng hơn さえ; thường đi với phủ định hoặc 'ngay cả X cũng'.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "N + だに", "s": "N + だに + phủ định", "m": "だに nhấn mạnh mức tối thiểu trong văn trang trọng: “ngay cả… (cũng không)”.", "ex": [["想像だにできません。", "Ngay cả tưởng tượng cũng không nổi."], ["夢だに思わなかったことです。", "Đó là việc ngay trong mơ tôi cũng không nghĩ tới."]], "n": "Các cụm cố định: 想像だに、夢だに、考えだに.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "〜たりとも〜ない", "s": "[Lượng từ] + たりとも + phủ định", "m": "“Dù chỉ một…” cũng không — phủ định tuyệt đối với đơn vị nhỏ nhất.", "ex": [["一人たりとも、犠牲にはしません。", "Dù chỉ một người, tôi cũng không để hy sinh."], ["一円たりとも、無駄にできません。", "Dù chỉ một yên cũng không thể lãng phí."]], "n": "たりとも luôn đi với phủ định và lượng từ + trợ từ lượng.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "〜とも（断言）", "s": "[Câu thường] + とも", "m": "とも cuối câu khẳng định dứt khoát, đầy tự tin đồng ý với điều hiển nhiên.", "ex": [["もちろん、行くとも。", "Tất nhiên là đi chứ!"], ["大丈夫とも。心配いりません。", "Ổn chứ. Không cần lo đâu."]], "n": "Sắc thái văn nói mạnh; không dùng trong văn trang trọng.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "〜ではあるまいし", "s": "N + ではあるまいし、〜", "m": "“Có phải… đâu mà…” — bác bỏ lý do biện minh bằng phủ định hiển nhiên.", "ex": [["子どもではあるまいし、泣くのはやめなさい。", "Có phải trẻ con đâu mà khóc, nín đi."], ["初めてではあるまいし、できるはずです。", "Có phải lần đầu đâu, chắc chắn làm được."]], "n": "まいし là dạng rút gọn phủ định suy đoán + し (liệt kê lý do).", "group": "Nhấn mạnh & tu từ N1"}, {"p": "V + んばかり", "s": "V-ない gốc + んばかり（に）", "m": "“Như sắp… đến nơi” — trạng thái cảm xúc đến mức gần như hành động sắp bật ra.", "ex": [["彼女は泣かんばかりに喜びました。", "Cô ấy mừng như sắp khóc đến nơi."], ["飛び上がらんばかりの喜びようでした。", "Anh ấy mừng đến mức như sắp nhảy cẫng lên."]], "n": "んばかり là dạng văn chương của ない + ばかり rút gọn.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "N + といったら", "s": "N(trạng thái) + といったら、〜", "m": "といったら nêu chủ đề để nhấn mạnh mức độ cực đoan ở phần sau.", "ex": [["彼の忙しさといったら、休む暇もありません。", "Nói đến độ bận của anh ấy thì không có cả thời gian nghỉ."], ["うれしさといったら、言葉にできません。", "Niềm vui đó thì không diễn tả nổi bằng lời."]], "n": "といったら luôn đi với danh từ chỉ trạng thái/cảm xúc + kết quả cực đoan.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "N + ときたら", "s": "N + ときたら、〜", "m": "ときたら nêu đối tượng để phàn nàn/phê phán thói quen của họ.", "ex": [["最近の若者ときたら、挨拶もできません。", "Nói đến giới trẻ dạo này thì, chào hỏi cũng không xong (phê phán)."], ["彼は忙しいときたら、電話にも出ません。", "Anh ta mà bận thì đến điện thoại cũng không nghe."]], "n": "ときたら mang sắc thái tiêu cực rõ rệt về đối tượng được nêu.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "N + とやら", "s": "N + とやら", "m": "とやら chỉ sự vật được nhắc tới một cách mơ hồ/xa cách: “cái gọi là…”, “gì đó…”.", "ex": [["免許証とやらを見せてください。", "Cho tôi xem cái gọi là bằng lái của anh."], ["何とかとやらいう会社に勤めています。", "Anh ta làm ở một công ty tên gì gì đó (không nhớ rõ)."]], "n": "とやら mang sắc thái không chắc chắn hoặc hơi coi nhẹ.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "〜ではなかろうか", "s": "[Câu thường] + ではなかろうか", "m": "Dạng văn trang trọng của のではないだろうか: nêu suy đoán một cách thận trọng.", "ex": [["彼は来ないのではなかろうか。", "Có lẽ anh ấy sẽ không đến chăng (suy đoán trang trọng)."], ["これは大きな問題ではなかろうかと思います。", "Tôi cho rằng đây có lẽ là vấn đề lớn."]], "n": "なかろうか đọc なかろうか; hay dùng trong bài phát biểu, văn nghị luận.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "V-る + まい", "s": "V-る + まい", "m": "まい hai nghĩa: (1) ý chí phủ định “quyết không…”; (2) suy đoán phủ định “chắc không… đâu”.", "ex": [["二度と行くまいと決めました。", "Tôi quyết không bao giờ đi nữa."], ["彼はその話を知るまい。", "Chắc anh ấy không biết chuyện đó đâu."]], "n": "まい nối động từ nguyên dạng; する → するまい/すまい.", "group": "Nhấn mạnh & tu từ N1"}, {"p": "V-ます + にかたくない", "s": "V-ます + にかたくない", "m": "“Không khó để…” — suy luận dễ dàng về cảm xúc/tình trạng (thường với 想像・理解).", "ex": [["彼の苦労は想像にかたくありません。", "Nỗi vất vả của anh ấy không khó để hình dung."], ["成功までの道のりは想像にかたくないでしょう。", "Con đường đến thành công chắc không khó tưởng tượng."]], "n": "かたくない đọc かたくない; chỉ dùng với nhóm động từ nhận thức giới hạn.", "group": "Nhấn mạnh & tu từ N1"}]};
